window.JASTROW_CHUNKS[16]={"6400":{"h":"דַּגָּלָא","r":"D00111","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּגַל\">דְּגַל</a>) <i>cunning; false</i>. <span class=\"citation\">Targ. Prov. XIX, 28</span> <span dir=\"rtl\">דיגא׳</span> ed. Lag. (oth. ed. <span dir=\"rtl\">דגל׳</span>, <a href=\"#\" data-headword=\"ר׳\">ר׳</a>). <span class=\"citation\">Ib. XXIV, 28</span> (h. text <a href=\"#\" data-headword=\"חִנָּם\">חנם</a>). <span class=\"citation\">Ib. XX, 17</span> (h. text <a href=\"#\" data-headword=\"שְׁקַר I\">שקר</a>).—<span class=\"citation\">Ab. Zar. 22ᵇ</span> (prov.) <span dir=\"rtl\">מכתבא … ד׳ בחבריה ידע</span> Ar. (ed. a. Ms. M. <a href=\"#\" data-headword=\"רֶגֶל ²\">רגלא</a>) the pencil splits the stone (marble), a schemer finds out his like.</div>","alt":["(דִּיגָּאלָא)"]},"6401":{"h":"דגלום","r":"D00112","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to V, 12</span> <span dir=\"rtl\">ד׳ פטרגוס</span>, a corrupt. arising fr. two Var. to <a href=\"#\" data-headword=\"עַרְטִיל\">ערטיל</a> ibid., <a href=\"#\" data-headword=\"פּוֹדַגְרוֹס\">פודגרוס</a> a. <span dir=\"rtl\">פודלגוס</span> (ποδαγρός, ποδαλγός); cmp. Y. Kidd. I, 61ᵃ; <span class=\"citation\">Sot. 10ᵃ</span>; Tanḥ. Masé 12.</div>","alt":["דגלוס"]},"6402":{"h":"דַּגָּלוּתָא","r":"D00113","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּגַל\">דְּגַל</a>) <i>cunning, scheme</i>. <span class=\"citation\">Targ. Prov. XVII, 4</span> ed. Lag. (Var. <a href=\"#\" data-headword=\"ר׳\">ר׳</a>). <span class=\"citation\">Ib. XXX, 8</span> <span dir=\"rtl\">דיגלתא</span> ed. Lag. (Var. <span dir=\"rtl\">ריג׳</span>); v. <a href=\"#\" data-headword=\"דַּגָּלָא\">דַּגָּלָא</a>.</div>","alt":[]},"6403":{"h":"דִּגְלָת","r":"D00114","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיגְלַת\">דִּיגְלָת</a></div>","alt":[]},"6404":{"h":"דֶּגֶם","r":"D00115","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּגְמָא\">דּוּגְמָא</a></div>","alt":[]},"6405":{"h":"דגמטורין","r":"D00116","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּגְמַטְרִין\">דוגמטרין</a></div>","alt":["דגמטרין"]},"6406":{"h":"דָּגָן","r":"D00117","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"דְּגַן\">next w.</a>) <i>pile; grain, bread, bread-stuff</i>. <span class=\"citation\">Pesik. R. s. 10</span> <span dir=\"rtl\">דְּגָנוֹ של עולם</span> are the store of the world. <span class=\"citation\">Tosef. Ber. IV, 15</span>; Y. ib. VI, 10ᵇ <span dir=\"rtl\">הד׳ שהוא וכ׳</span> the more preferable kind of bread. Tosef. l. c. <span dir=\"rtl\">כל שהוא מין שבע ואינו מין ד׳</span> whatever belongs to the seven produces (<span class=\"citation\">Deut. VIII, 8</span>) but not to breadstuffs; Bab. ib. 37ᵇ. <span class=\"citation\">Pes. III, 1</span>; a. fr.—<span class=\"citation\">Ned. VII, 2</span> <span dir=\"rtl\">הנודר מן הד׳ וכ׳</span> he who vows abstinence from <i>dagan</i>, is forbidden dry Egyptian beans, v. next w.—Pl. <span dir=\"rtl\">דְּגָנִים</span>. <span class=\"citation\">Pesik. R. s. 41</span> <span dir=\"rtl\">מנפף את הד׳</span> swells the grains; (<span class=\"citation\">Yalk. Ps. 755</span> <span dir=\"rtl\">מנפנף את רגליה</span>, read <span dir=\"rtl\">דְּגָנֶיהָ</span>). Tosef. Ber. VII (VI), 8 Var.—<span dir=\"rtl\">בֵּית דָּ׳</span> pr. n. pl. <i>Beth-Dagan</i> in Judea. <span class=\"citation\">Tosef. Ohol. III, 9</span>. [<span class=\"citation\">Tosef. Sabb. VII</span> (<span class=\"citation\">VIII), 2</span>, v. <a href=\"#\" data-headword=\"דָּגוֹן\">דָּגוֹן</a>.]</div>","alt":[]},"6407":{"h":"דְּגַן","r":"D00118","html":"<div class=\"sense\">, <i>Ithpe.</i> אִידְּגַן <i>to be piled up, stored</i>. <span class=\"citation\">Ned. 55ᵃ</span> shall we judge (fr. R. Meir’s opinion VII, 2, v. <a href=\"#\" data-headword=\"דָּגָן\">preced.</a>) <span dir=\"rtl\">כל דמִידְּגַן משמע</span> <i>dagan</i> implies everything which is piled up?—<span class=\"citation\">Ber. 47ᵇ</span>; <span class=\"citation\">Bets. 13ᵇ</span> <span dir=\"rtl\"><a href=\"#\" data-headword=\"הַאי\">האי</a> (<a href=\"#\" data-headword=\"דְּכַר I\">אִדְּ׳</a>) <span dir=\"rtl\">אי׳ וכ׳</span></span> the one (the piled up) has become <i>dagan</i>, the other (standing in the ears) is not yet <i>dagan</i> (with ref. to <span class=\"citation\">Num. XVIII, 27</span>).</div>","alt":[]},"6408":{"h":"דְּגָנָא","r":"D00119","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Ex. XXIII, 19</span> (cmp. Tanḥ. R’eh 17 s. v. <a href=\"#\" data-headword=\"גְּדִי\">גְּדִי</a>).—Y. Ned. VII, 40ᶜ top (ref. to R. Meir’s opinion ib. VII, 2, v. <a href=\"#\" data-headword=\"דְּגַן\">preced.</a>) <span dir=\"rtl\">דְגָנָהּ דארעא</span> dry Egyptian beans are the bread of the land (Palestine, therefore implied in <i>dagan</i>); (ref. to the Rabbis’ opinion, ib.) <span dir=\"rtl\">דגנה מעבורה</span> ‘its bread’ means its home growth.</div>","alt":[]},"6409":{"h":"דְּגַר I","r":"D00120","html":"<div class=\"sense\"><b>1)</b> <i>to heap</i>, v. <a href=\"#\" data-headword=\"דְּגוֹרָא\">דְּגוֹרָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>to brood</i>. <span class=\"citation\">Targ. Job XXXIX, 14</span>.</div><div class=\"sense\"><b>Ithpe. אִידְּגַר</b> <div class=\"sense\"><i>to be piled up</i> (of bowels in pain). <span class=\"citation\">Targ. Lam. I, 20</span>. <span class=\"citation\">Ib. II, 11</span> <span dir=\"rtl\">אידגארן</span> ed. Lag. (h. text <span dir=\"rtl\">חמרמר</span>, cmp. <a href=\"#\" data-headword=\"דְּגוֹרָא\">דְּגוֹרָא</a> = <span dir=\"rtl\">חֹמֶר</span>).</div></div>","alt":[]},"6410":{"h":"*דְּגַר II","r":"D00121","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">זקר</span>) <i>to leap</i>. <span class=\"citation\">Ḥull. 51ᵃ</span> <span dir=\"rtl\">ד׳ נפל מאיגרא</span> (our w. omitted in Ar. s. v. <a href=\"#\" data-headword=\"אִיפּוּמָא\">איפומא</a>) it leaped [and] fell from the roof (Rashi).</div>","alt":[]},"6411":{"h":"דֹּד","r":"D00122","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹד\">דּוֹד</a></div>","alt":[]},"6412":{"h":"דַּד","r":"D00123","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.; = <span dir=\"rtl\">דודו</span>, v. <span dir=\"rtl\">דוה</span>; cmp. <a href=\"#\" data-headword=\"דְּהֵין\">דְּהֵין</a>) <i>breast, nipple, teat</i>. <span class=\"citation\">Sabb. 144ᵇ</span>. <span class=\"citation\">Sifré Num. 89</span>; <span class=\"citation\">Tosef. Sot. IV, 3</span> (ed. Zuck. <span dir=\"rtl\">שד</span>); a. e.—Trnsf. <i>spigot.</i> <span class=\"citation\">Yoma III, 10</span>.—Pl. <span dir=\"rtl\">דַּדִּים</span>. <span class=\"citation\">Ber. 10ᵃ</span>. <span class=\"citation\">Y. Yeb. II, 3ᵈ</span>; a. fr.</div>","alt":[]},"6413":{"h":"דַּד ²","r":"D00124","html":"<div class=\"sense\"> <span class=\"citation\">Ab. Zar. 26ᵃ</span> she may smear poison <span dir=\"rtl\">לד׳ מאבראי</span> on her breast outside.—Pl. <span dir=\"rtl\">דַּדִּין</span>, <span dir=\"rtl\">דַּדַּיָּא</span>. <span class=\"citation\">Targ. Is. XXXII, 12</span> (ed. Lag. <span dir=\"rtl\">תדין</span>).—<span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד מאת׳ 6) <span dir=\"rtl\">ותרין מזגין אילין תרין דדיא</span> (not <a href=\"#\" data-headword=\"דַּד ²\">דדא</a>) the two bottlers (in the riddle) are the two breasts. <span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">יתברכון ד׳ וכ׳</span> blessed are the breasts which nursed such a son.</div>","alt":["דַּדָּא"]},"6414":{"h":"דִּדְבָא","r":"D00125","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּידְבָא\">דִּידְבָא</a></div>","alt":[]},"6415":{"h":"דֹּדָה","r":"D00126","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹד\">דּוֹד</a></div>","alt":[]},"6416":{"h":"דָדָה","r":"D00127","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דדי\">דדי</a></div>","alt":[]},"6417":{"h":"דדהובא","r":"D00128","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּחוּכָא\">דְּחוּכָא</a></div>","alt":[]},"6418":{"h":"דִּדְהֵין","r":"D00129","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּהַן II\"><span dir=\"rtl\">דְּהַן</span> II</a></div>","alt":[]},"6419":{"h":"דַּדְוָותָא","r":"D00130","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּדָא\">דּוּדָא</a></div>","alt":[]},"6420":{"h":"דדי","r":"D00131","html":"<div class=\"sense\"><i>to move nimbly, hop, trip</i>.—Pl. <span dir=\"rtl\">דִּדָּה</span></div><div class=\"sense\"><b>1)</b> <i>to walk, pull</i> (a young child or beast unable to walk by itself). <span class=\"citation\">Sabb. XVIII, 2</span> <span dir=\"rtl\">מְדַדִּין עגלין וכ׳</span> you may lead or pull calves &amp;c. (on the Sabbath). Ib. <span dir=\"rtl\">אשה מְדַדָּה וכ׳</span> a mother may walk her child. Ib. 128ᵇ <span dir=\"rtl\">דוחין אין מדדין לא</span> push you may, but make them hop, no. <span class=\"citation\">Pes. IV, 7</span> (<span class=\"citation\">55ᵇ</span>) <span dir=\"rtl\">מְדַרִּין ומחזירין וכ׳</span> Ar. (ed. only <span dir=\"rtl\">מחזירין</span>). <span class=\"citation\">Sabb. 88ᵇ</span> and the angels <span dir=\"rtl\">מְדַדִּין אותך</span> led them (the frightened Israelites) back; <span dir=\"rtl\">א&quot;ת ידודון אלא יְדַדּוּן</span> read not (<span class=\"citation\">Ps. LXVIII, 13</span>) <i>yiddodun</i> but <i>y’daddun</i> (they led them). <span class=\"citation\">Cant. R. to VIII, 11</span> the angels <span dir=\"rtl\">מְדַדִּין להם וכ׳</span> led the Israelites away, <span dir=\"rtl\">והיו מִדַּדִּין לפני וכ׳</span> and they themselves tripped timidly before the Lord, v. infra. <span class=\"citation\">Y. Sabb. XVII, end, 16ᵇ</span>; Y. Erub. X, 26ᶜ top <span dir=\"rtl\">מְדַדֵּהוּ וכ׳</span> he makes the bolt slide with his finger tips. <span class=\"citation\">Cant. R. to IV, 8</span> [read:] <span dir=\"rtl\">אדין מְדַדֵּם ואינם וכ׳</span> He had just been leading them (through the Red Sea), and they should not trust?—ד׳ פיתקין <i>to shake stones</i> (<i>ballots</i>), i.e. <i>to protest against</i>. <span class=\"citation\">Esth. R. to I, 2</span> <span dir=\"rtl\">מה&quot;ש מְדַדִּין פיתקין וכ׳</span> the angels protested against the Lord’s decision; <span class=\"citation\">Cant. R. to VIII, 11</span> <span dir=\"rtl\">יִדּוֹדוּן בהם ממדדין פיטקין</span> (read <span dir=\"rtl\">מדדין</span>) they (the angels) were excited against them, they protested (ref. to <span class=\"citation\">Joel IV, 3</span>).</div><div class=\"sense\"><b>Hithpa. הִדַּדָּה</b> <div class=\"sense\"><i>to hop, trip</i> (of young or tied birds). <span class=\"citation\">B. Mets. 25ᵇ</span> אי מִידַּדִּין Ms. M. (ed. <span dir=\"rtl\">אי בְמִדַּ׳</span>) if the tied birds (deposited in a certain place) hop from spot to spot. <span class=\"citation\">B. Bath. 23ᵇ</span>; <span class=\"citation\">Bets. 11ᵃ</span></div></div>","alt":["דָּדָה"]},"6421":{"h":"דדי ²","r":"D00132","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"דדי\">דַּדֵּי</a> ch. same. <span class=\"citation\">Sabb. 128ᵇ</span> <span dir=\"rtl\">דַּדּוּיֵי מְדַרִּינָן</span> pull them we may, opp. <a href=\"#\" data-headword=\"עֲקַר I\">עקר</a>.</div><div class=\"sense\"><b>Ithpa. אִידַּדֵּי</b> <div class=\"sense\"><b>1)</b>  as <a href=\"#\" data-headword=\"דדי\">preced.</a> Hithpa. <span class=\"citation\">B. Bath. 24</span> as <a href=\"#\" data-headword=\"דדי\">preced.</a> Hithpa. <span class=\"citation\">B. Bath. 24ᵃ</span> <span dir=\"rtl\">כל דמִידַּדֵּי וכ׳</span> any young bird which hops, will hop only within sight of its nest. <span class=\"citation\">Bets. 11ᵃ</span> <span dir=\"rtl\">אִידַּדּוּיֵי אִידַּדּוּ</span> they came hopping (from the nest). <span class=\"citation\">Sabb. 99ᵇ</span> <span dir=\"rtl\">דלא לִדַּדּוּ וכ׳</span> that the boards should not shake.</div><div class=\"sense\"><b>—2)</b> <i>to move about</i>. Y. Kidd. III, 64ᵃ top <span dir=\"rtl\">כיני אורחא דזבונה מִדַּדְיָיה</span> it is the habit of traders to travel from place to place.</div></div>","alt":[]},"6422":{"h":"דדינון","r":"D00133","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. II, beg. 4ᶜ</span>, v. <a href=\"#\" data-headword=\"*דְּרִינוֹן\">דְּרִינון</a></div>","alt":["דדינין"]},"6423":{"h":"דדכאות","r":"D00134","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּידְכֵי\">דִּידְכֵי</a></div>","alt":[]},"6424":{"h":"דדנייא","r":"D00135","html":"<div class=\"sense\">, <span class=\"citation\">Lam. R. to II, 2</span>, v. <a href=\"#\" data-headword=\"דּוֹדָא\">דּוֹדָא</a></div>","alt":[]},"6425":{"h":"דְּדָנִים","r":"D00136","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (b. h.) <i>Dedanites</i>, a nomadic tribe on the borders of Idumaea. Tanḥ. Yithro 5.—V. <a href=\"#\" data-headword=\"דּוֹדָנִים\">דּוֹדָנִים</a>.</div>","alt":[]},"6426":{"h":"דדנין","r":"D00137","html":"<div class=\"sense\">, <span class=\"citation\">Y. R. Hash. II, 58ᵃ</span> top, expl. <span dir=\"rtl\">עצי שמן</span> (Mish. <span class=\"citation\">ib. II, 2</span>), prob. <a href=\"#\" data-headword=\"דדינון\">דָּדִינִין</a> (δᾴδινος, pl.) <i>pine-wood</i>, (used for torches; Bab. <span class=\"citation\">R. Hash. 23ᵃ</span> <a href=\"#\" data-headword=\"אַפַּרְסְמָא\">אפרסמא</a>; v. Sm. Ant. s. v. Taeda).</div>","alt":[]},"6427":{"h":"דדרא","r":"D00138","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּרָרָא I\"><span dir=\"rtl\">דְּרָרָא</span> I</a></div>","alt":[]},"6428":{"h":"דַּדְקֶרֶת","r":"D00139","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּרוּקֶרֶת\">דְּרוֹקֶרֶת</a></div>","alt":[]},"6429":{"h":"דָּה","r":"D00140","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דָּא I\">דָּא</a></div>","alt":[]},"6430":{"h":"דָּהַב","r":"D00141","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">זהב</span>, <span dir=\"rtl\">צהב</span>) <i>to be red</i> (or<i> yellow</i>).—<i>Hif.</i> הִדְהִיב <i>to redden, make red</i> (<i>with anger</i>). <span class=\"citation\">Lev. R. s. 15</span>, end (play on <i>madhebah</i>, <span class=\"citation\">Is. XIV, 4</span>) <span dir=\"rtl\">שהיא מַדְהֶבֶת וכ׳</span> that reddens with indignation the face of every one coming near her.</div>","alt":[]},"6431":{"h":"דְּהַב","r":"D00142","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>gold</i>. <span class=\"citation\">Targ. Gen. II, 11</span>; a. e.—<span class=\"citation\">Y. B. Mets. II, 8ᶜ</span> bot. <span dir=\"rtl\">קופד דד׳</span> a golden piece resembling meat; <span class=\"citation\">Tam. 32ᵃ</span>; a. fr.—<span class=\"citation\">B. Mets. 70ᵃ</span>; <span class=\"citation\">B. Bath. 166ᵃ</span> <span dir=\"rtl\">ד׳ פריכא</span> broken pieces of gold (for the melting pot). <span class=\"citation\">Ib. 165ᵇ</span> <span dir=\"rtl\">ד׳ אין פחות וכ׳</span> if a note has the word ‘gold’ (without any further definition), it means no less than a Denar in gold (v. Rabb. D. S. a. l. note).</div>","alt":["דַּהֲבָא"]},"6432":{"h":"דַּהֲבַאי","r":"D00143","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּהַב\">preced.</a>) <i>Dahăbai</i> (Goldsmith). <span class=\"citation\">Ḥag. 2ᵃ</span></div>","alt":[]},"6433":{"h":"דַּהֲבוֹנָא","r":"D00144","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דַּהֲבַאי\">preced. ws.</a>) <i>price in gold, cash</i>. Targ. II Esth. III, 11 (ed. Lag. <a href=\"#\" data-headword=\"ר׳\">ר׳</a>, corr. acc.).</div>","alt":[]},"6434":{"h":"דְּהָבִי","r":"D00145","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"זָהָבִי\">זְהָבִי</a>, <i>goldsmith</i>.—Pl. <a href=\"#\" data-headword=\"דְּהָבִי\">דְּהָבִין</a>. <span class=\"citation\">Cant. R. to V, 5</span> <span dir=\"rtl\">דהבים</span> (corr. acc.).</div>","alt":[]},"6435":{"h":"דַּהֲבָן","r":"D00146","html":"<div class=\"sense\"> <span class=\"citation\">Y. Gitt. IV, 46ᵃ</span></div>","alt":[]},"6436":{"h":"דַּהֲבַת","r":"D00147","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Dahăbath</i>. <span class=\"citation\">Taan. 7ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"דִּכְוָון\">דִּי׳</a>).</div>","alt":["(דִּיהֲ׳)"]},"6437":{"h":"דָּהָה","r":"D00148","html":"<div class=\"sense\"><i>to be faint</i>, v. <a href=\"#\" data-headword=\"דֵּיהֶא\">דֵּיהָה</a>.</div>","alt":[]},"6438":{"h":"דָּהוֹן","r":"D00149","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דְּהֵין\">דְּהֵין</a>) <i>fattening substance, urin-soaked dung; a concrete of dung used for vessels</i>, cmp. <a href=\"#\" data-headword=\"גָּלָל\">גָּלָל</a>. <span class=\"citation\">Y. Ab. Zar. II, 41ᵇ</span> bot. <span dir=\"rtl\">אהן ד׳ של מימי וכ׳</span> a vessel made of dung prepared with urin absorbs no liquids.—<span class=\"citation\">Gen. R. s. 39</span>, end (ref. to <i>Bethel</i>, changed into <i>Beth-aven</i>, <span class=\"citation\">Josh. VII, 2</span>) [read:] <span dir=\"rtl\"><span dir=\"rtl\">לא זכתה … בית העמל הרי … בית העמד תמן קריין לפועלא טבא עמילא</span> (<span dir=\"rtl\">ולהִרְהוּן</span>) <span dir=\"rtl\">ולדהון … עמידה</span></span> she did not deserve even to be named <i>Beth Heamal</i> (house of toil, cmp. <span dir=\"rtl\">עמל ואון</span> <span class=\"citation\">Ps. XC, 10</span>), now she is named <i>Beth-Heamad</i> (dung-house); there (in Samaria, Galilee &amp;c.) they call the good laborer <i>amela</i> (the industrious, v. <a href=\"#\" data-headword=\"עָמָל\">עמל</a>), and the dung prepared with urin <i>amidah</i> (concrete, cmp. <a href=\"#\" data-headword=\"עָמָד I\">עָמַד</a> Hif.); <span class=\"citation\">Y. Sabb. IX, 11ᵈ</span>; <span class=\"citation\">Y. Ab. Zar. III, 43ᵃ</span> bot.; <span class=\"citation\">Yalk. Josh. 17</span> (v. Koh. Ar. Compl. s. v. <a href=\"#\" data-headword=\"דָּהוֹן\">הרהון</a>).</div>","alt":["(רָהוֹן","הִרְהוּן)"]},"6439":{"h":"דְּהֵיךְ","r":"D00150","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"דְּחֵיךְ\">דְּחַךְ</a>. <span class=\"citation\">Targ. Job XI, 3</span>. <span class=\"citation\">Targ. Ps. II, 4</span> ed. Lag.</div>","alt":["דְּהַךְ"]},"6440":{"h":"דְּהֵין","r":"D00151","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">דוה</span>; interch. dialectically with <a href=\"#\" data-headword=\"רָהַן\">רהן</a>, cmp. <span dir=\"rtl\">רוה</span>) <i>to drip, to be fat</i> (corresp. to h. <a href=\"#\" data-headword=\"דָּשֵׁן\">דָּשַׁן</a> a. <a href=\"#\" data-headword=\"רָוָה\">רָוָה</a>). <span class=\"citation\">Targ. Prov. XI, 25</span> <span dir=\"rtl\">תדהן</span> ed. Lag. (Var. <span dir=\"rtl\">תודכן</span>, <span dir=\"rtl\">תורכן</span>, corr. acc.); a. fr.</div><div class=\"sense\"><b>Pa. דַּהֵין</b> <div class=\"sense\"><b>1)</b> <i>to fatten</i>. <span class=\"citation\">Targ. Ps. XXIII, 5</span>. <span class=\"citation\">Targ. Prov. XV, 30</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to grow fat</i>. <span class=\"citation\">Targ. Y. Deut. XXXI, 20</span>.—[<span class=\"citation\">Targ. Ps. XX, 4</span>, v. <a href=\"#\" data-headword=\"*דַּהֲנַאן\">דַהְנַאן</a>.]</div></div><div class=\"sense\"><b>Ithpa. אִידַּהֵין</b> <div class=\"sense\"><i>to drip, be fat</i>. <span class=\"citation\">Targ. Is. XXXIV, 6</span>.—<span class=\"citation\">Shebu. 47ᵇ</span>, v. <a href=\"#\" data-headword=\"דְּהִין\">next w.</a></div></div>","alt":["דְּהַן"]},"6441":{"h":"דְּהִין","r":"D00152","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּהֵין\">preced.</a>) <i>fat, sappy</i>. <span class=\"citation\">Shebu. 47ᵇ</span> <span dir=\"rtl\">קרב לגבי ר׳ ואִידַּהֵין</span> go near a fat man, and be fat.—Pl. <span dir=\"rtl\">דְּהִינִין</span>. <span class=\"citation\">Targ. Ps. XCII, 15</span>. <span class=\"citation\">Ib. XXII, 30</span> (Var. <a href=\"#\" data-headword=\"רִיהֲטָא\">רה׳</a>).</div>","alt":["דּהִינא"]},"6442":{"h":"דְּהִינוּנִיתָא","r":"D00153","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּהֲנוּנִיתָא\">דּהֲנוּנִיתָא</a></div>","alt":[]},"6443":{"h":"דְּהַךְ","r":"D00154","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּחֵיךְ\">דְּחֵיךְ</a></div>","alt":[]},"6444":{"h":"דַּהֲכָא","r":"D00155","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹחֲכָא\">דּוֹחֲכָא</a></div>","alt":[]},"6445":{"h":"דְּהַן I","r":"D00156","html":"<div class=\"sense\"><i>to be fat</i>, v. <a href=\"#\" data-headword=\"דְּהֵין\">דְּהֵין</a>.</div>","alt":[]},"6446":{"h":"דְּהַן II","r":"D00157","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּהַן I\">preced.</a>) <i>fat</i>. <span class=\"citation\">Targ. Ps. XXXVI, 9</span> (Var <a href=\"#\" data-headword=\"רָהַן\">רהן</a>). <span class=\"citation\">Targ. Is. LV, 2</span> ed. Bxt. <span dir=\"rtl\">בד׳</span> (ed. Lag. a. oth. <span dir=\"rtl\">בדִדְהֵין</span>; cmp. <a href=\"#\" data-headword=\"דִּידְבָא\">דּידְבָא</a>).</div>","alt":["דַּהֲנָא"]},"6447":{"h":"*דַּהֲנַאן","r":"D00158","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"דְּהַן II\">preced.</a>; cmp. <a href=\"#\" data-headword=\"*דַּאֲבַן\">דַּאֲבַן</a>) <i>to consider fat, to accept</i>. <span class=\"citation\">Targ. Ps. XX, 4</span> (ed. Wil. <span dir=\"rtl\">יְדַהֵן</span>; h. text <span dir=\"rtl\">יְדַּשְּׁנֶה</span>).</div>","alt":[]},"6448":{"h":"דַּהַנְיְתָא","r":"D00159","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּהֵין\">דהן</a>, cmp. <a href=\"#\" data-headword=\"דָּהוֹן\">דָּהוֹן</a>) <i>manure</i>. <span class=\"citation\">Targ. Ez. XXXII, 6</span> (ed. Lag. <span dir=\"rtl\">דוה׳</span>).</div>","alt":[]},"6449":{"h":"דַּהֲנוּנִיתָא","r":"D00160","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דַּהַנְיְתָא\">preced. ws.</a>) <i>of a fat land</i>. <span dir=\"rtl\">תמרתא ד׳</span> (a fat-land date) <i>a species of dates of strongperfume</i>. <span class=\"citation\">Keth. 61ᵃ</span> <span dir=\"rtl\">דהנ׳</span>; <span class=\"citation\">Sot. 49ᵃ</span> <span dir=\"rtl\">דחינ׳</span> (corr. <span dir=\"rtl\">דהינ׳</span>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ריחא דחינ׳</span> (read <span dir=\"rtl\">דדהינ׳</span>) the flavor of a <i>d’hinunitha</i></div>","alt":["דְּהינוּ׳"]},"6450":{"h":"דהק","r":"D00161","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּחַק I\">דחק</a></div>","alt":[]},"6451":{"h":"דּוּ I","r":"D00162","html":"<div class=\"sense\"> (= <span dir=\"rtl\">רְּהוּ</span>, cmp. <a href=\"#\" data-headword=\"דִּי\">דִּי</a>) <i>who, which is, since he, it</i>, &amp;c. <span class=\"citation\">Y. Sabb. XIX, beg. 16ᵈ</span> <span dir=\"rtl\">דו אמר … הוא דאמר</span> the same that says …, says also &amp;c. <span class=\"citation\">Y. Peah I, 15ᶜ</span> top <span dir=\"rtl\">בגין דו בעי וכ׳</span> because he wants to teach &amp;c. <span class=\"citation\">Y. Maasr. I, 49ᵃ</span> bot. <span dir=\"rtl\">מן דו</span> from the time that. <span class=\"citation\">Y. Gitt. IX, 50ᶜ</span> top nobody says ‘even’ <span dir=\"rtl\">אלא דו מודה וכ׳</span> except he admits the preceding; a. fr.</div>","alt":[]},"6452":{"h":"דּוּ II","r":"D00163","html":"<div class=\"sense\"> c. (= <a href=\"#\" data-headword=\"דֵּן\">דֵּן</a>) <i>this, that</i>. <span class=\"citation\">Y. Naz. IV, end, 53ᶜ</span>. <span class=\"citation\">Y. Erub. V, 22ᶜ</span> top <span dir=\"rtl\">דו ואַלְפַּיִם</span> itself (the whole area of the town) and two thousand cubits beside.</div>","alt":[]},"6453":{"h":"דּוּ III","r":"D00164","html":"<div class=\"sense\"> (δύο, only in certain compounds) <i>two, double</i>. <span class=\"citation\">Lev. R. s. 14</span>, beg. <span dir=\"rtl\">דו פרצופין נברא</span> Adam was created with two faces (male and female persons combined); <span class=\"citation\">Gen. R. s. 8</span>, beg. <a href=\"#\" data-headword=\"דְּיוֹ I\">דיו</a>; Ber. 68ᵃ; a. e.—<span class=\"citation\">Ex. R. s. 5</span> <span dir=\"rtl\">דו פרצ׳ היה יוצא</span> the word of the Lord went forth in two characters (killing and reviving). V. <a href=\"#\" data-headword=\"דִּיוֹ II\"><span dir=\"rtl\">דְּיוֹ</span> II</a>.</div>","alt":[]},"6454":{"h":"דְּיָא","r":"D00165","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּוַי\">דְּוִי</a></div>","alt":[]},"6455":{"h":"דּוֹאֵג","r":"D00166","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Doeg</i>, </div><div class=\"sense\"><b>1)</b>  the servant of Saul. <span class=\"citation\">Snh. 106ᵇ</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  one D. ben Joseph. <span class=\"citation\">Lam. R. to I, 16</span>; Sifra <span class=\"citation\">B’ḥuck. ch. VI</span>.</div>","alt":[]},"6456":{"h":"דַּוַּאר","r":"D00167","html":"<div class=\"sense\">, Pa. of <a href=\"#\" data-headword=\"דּוּר\">דּוּר</a> I ch.</div>","alt":[]},"6457":{"h":"דַּוָּאר I","r":"D00168","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (דּוּר I, cmp. <a href=\"#\" data-headword=\"דַּוַּאר\">preced.</a>) </div><div class=\"sense\"><b>1)</b>  (transl. of cursor) <i>mail-carrier, despatch-bearer</i>. Tanḥ. Ekeb 11 <span dir=\"rtl\">ד׳ שהיה מהלך וכ׳</span> a <i>cursor</i> who travelled with an ordinance in his hand. <span class=\"citation\">Sabb. 19ᵃ</span> קביע ד׳ במתא Ms. M. (ed. <a href=\"#\" data-headword=\"דָּרֵי\">בי ד׳</a>) the mail-carrier (ed. the post office) is permanently located in town.</div><div class=\"sense\"><b>—2)</b>  (Pers. dâvar, judge, ruler, Fl.) <a href=\"#\" data-headword=\"דָּרֵי\">בֵּי ד׳</a> <i>the (Persian) circuit court</i> consisting of regular law scholars, opp. <span dir=\"rtl\">דייני דמגיסתא</span> squires in country places ignorant of the law. <span class=\"citation\">B. Kam. 114ᵃ</span> (Ms. R. <span dir=\"rtl\">אַבֵּי ד׳</span> in the &amp;c., Ms. M. <span dir=\"rtl\">בודאור</span>, corr. acc.). <span class=\"citation\">Gitt. 58ᵇ</span> <span dir=\"rtl\">כיון דאיכא בי ד׳ וכ׳</span> since there exists (in Persia) a lawful court, and he did not sue (the tax officer). <span class=\"citation\">Ab. Zar. 26ᵃ</span> נקיטא לי זימנא לבי ד׳ I am summoned to court (and have no time). [In later Hebr. literature <span dir=\"rtl\">בי דואר</span> is used in the sense of <i>post-office</i>.]</div>","alt":["דַּוָּואר","דַּוָּור"]},"6458":{"h":"*דַּוָּאר II","r":"D00169","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"דַּוָּאר I\">preced.</a>) <i>davvar</i>, a species of lizard. <span class=\"citation\">Ex. R. s. 15</span> end [prob. to be read <a href=\"#\" data-headword=\"עָרוֹד\">עָרוֹד</a>, v. <span class=\"citation\">Ḥull. 127ᵃ</span>, or <a href=\"#\" data-headword=\"חֲוַורְבָּרָא\">חֲוַורְבָּר</a>, v. Sifra Sh’mini ch. VI, Par. 5].</div>","alt":[]},"6459":{"h":"דּוּב","r":"D00170","html":"<div class=\"sense\"> , <i>to flow, drip</i>. <span class=\"citation\">Targ. Ps. LXXVIII, 20</span> (Var. <span dir=\"rtl\">ודָיְיבַן</span>). <span class=\"citation\">Targ. Lev. XV, 25</span> <span dir=\"rtl\">יִרּוֹב</span>.—Part. <a href=\"#\" data-headword=\"דָּאִיב\">דָּאִיב</a>, <a href=\"#\" data-headword=\"דְּאִב\">דָּיֵיב</a>. <span class=\"citation\">Ib. 33</span>.—<span class=\"citation\">Ḥull. 8ᵇ</span> bot.—<span class=\"citation\">Pes. 74ᵇ</span> <span dir=\"rtl\">מֵרַב דָּיֵיב</span> it drips. <span class=\"citation\">Nidd. 22ᵃ</span> <span dir=\"rtl\">עד דמידב ד׳</span> it must be fluid. <span class=\"citation\">Ḥull. 133ᵃ</span></div>","alt":["דִּיב"]},"6460":{"h":"דּוֹב","r":"D00171","html":"<div class=\"sense\"> c. (b. h.;  [<i>murmurer</i>,] <i>bear</i>. <span class=\"citation\">Kidd. 72ᵃ</span>; <span class=\"citation\">Ab. Zar. 2ᵇ</span>; <span class=\"citation\">Meg. 11ᵃ</span> (used of Persians, ref. to <span class=\"citation\">Dan. VII, 5</span>).—Allegorically: <i>temptation</i>. <span class=\"citation\">Num. R. s. 13</span>; a. e., v. <a href=\"#\" data-headword=\"גָּרָה\">גָּרָה</a>.—Pl. <span dir=\"rtl\">דּוּבִּים</span>. <span class=\"citation\">Snh. 107ᵇ</span></div>","alt":["דֹּב"]},"6461":{"h":"דּוֹב ²","r":"D00172","html":"<div class=\"sense\"> <span class=\"citation\">Targ. II Sam. XVII, 8</span>. <span class=\"citation\">Targ. Is. XI, 7</span> (some ed. <span dir=\"rtl\">דיבא</span>, corr. acc.).—<span class=\"citation\">Kidd. 72ᵃ</span>. <span class=\"citation\">Taan. 25ᵃ</span>.—<span class=\"citation\">Gen. R. s. 87</span>, beg. <span dir=\"rtl\">הא ד׳ קמך</span> here is the temptation before thee.—Pl. <span dir=\"rtl\">דּוּבִּין</span>, <span dir=\"rtl\">דּוּבֵּי</span>. <span class=\"citation\">Targ. II Kings II, 24</span>.—Taan. l. c.; <span class=\"citation\">B. Mets. 106ᵃ</span>.—[<a href=\"#\" data-headword=\"דּוֹב ²\">דּוּבָא</a>, <a href=\"#\" data-headword=\"דּוֹבָא\">דּוֹבָא</a> <i>wolf</i>, v. <a href=\"#\" data-headword=\"דֵּיבָא\">דֵּיבָא</a>.] [<span class=\"citation\">Targ. I Kings XIV, 28</span>, v. <a href=\"#\" data-headword=\"דּוּכָא\">דּוּכָא</a>.]</div>","alt":["דֹּב","דּוּבָּא"]},"6462":{"h":"דּוֹבָא","r":"D00173","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>flux, gonorrhœa, abnormal menstruation</i>. <span class=\"citation\">Targ. Lev. XV, 2</span> sq. [<span class=\"citation\">Targ. Y. ib. 3</span> <a href=\"#\" data-headword=\"דְּיֵיה\">דְּיֵיה</a>, read <span dir=\"rtl\">דְּוָיֵה</span>]; a. e.</div>","alt":["דּווָֹא","דְּוָיָא","דִּיבָא"]},"6463":{"h":"דּוּבִּיאֵל","r":"D00174","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Dubbiël</i> (bear-god), the genius of the Persians (v. <a href=\"#\" data-headword=\"דּוֹב\">דּוֹב</a>). <span class=\"citation\">Yoma 77ᵃ</span>, v. <a href=\"#\" data-headword=\"אִיסְרָא II\"><span dir=\"rtl\">אִיסְרָא</span> II</a>.</div>","alt":[]},"6464":{"h":"דּוּבְלָא","r":"D00175","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דְּבֵילָה\">דְּבֵילָה</a>) <i>a species of figs or sycamore.</i> Pl. <span dir=\"rtl\">דּוּבְלֵי</span>. <span class=\"citation\">Ber. 40ᵇ</span> (defin. <span dir=\"rtl\">בנות שקמה</span>). [<a href=\"#\" data-headword=\"דּוּבְלָא\">דובלא</a>, <span class=\"citation\">Sot. 10ᵃ</span>, v. <a href=\"#\" data-headword=\"יַבְלָא\">יַבְלָא</a>.]</div>","alt":[]},"6465":{"h":"דּוֹבָנָא","r":"D00176","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דּוֹבָא\">דּוֹבָא</a>) = h. <a href=\"#\" data-headword=\"זָב\">זָב</a>, <i>one afflicted with gonorrhœa</i>. <span class=\"citation\">Targ. Lev. XV, 4</span>; <span class=\"citation\">7</span>; a. e.</div>","alt":[]},"6466":{"h":"דּוּבְקָא","r":"D00177","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיבְקָא\">דִּיבְקָא</a></div>","alt":[]},"6467":{"h":"דּוּבַר","r":"D00178","html":"<div class=\"sense\"><i>back</i>, v. <a href=\"#\" data-headword=\"בְּדוּבַר\">בְּדוּבַר</a>.</div>","alt":[]},"6468":{"h":"*דּוֹבֶשׁ","r":"D00179","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דְּבַשׁ\">דְּבַשׁ</a>) <i>honey-crop</i>. <span class=\"citation\">Deut. R. s. 1</span> <span dir=\"rtl\">דּוּבְשָׁהּ לבעלה</span> what honey the bee produces, belongs to its owner; <span class=\"citation\">Yalk. ib. 795</span>. [<span class=\"citation\">Ḥall. I, 4</span> <span dir=\"rtl\">דובשין</span>, Mish. ed., v. <a href=\"#\" data-headword=\"דּוּבְשָׁן\">דּוּבְשָׁן</a>.]</div>","alt":[]},"6469":{"h":"דּוּבְשָׁא","r":"D00180","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"דְּבַשׁ\">דְּבַשׁ</a>. <span class=\"citation\">Targ. Jud. XIV, 8</span>; a. fr.—<span class=\"citation\">Ber. 37ᵇ</span>. <span class=\"citation\">Ib. 38ᵃ</span> <span dir=\"rtl\">ד׳ דתמרי</span> date honey; a. e.—<span class=\"citation\">Yoma 83ᵇ</span> some ed. <a href=\"#\" data-headword=\"דִּיבְשָׁא\">דיבשא</a>.</div>","alt":[]},"6470":{"h":"דּוּבְשָׁן","r":"D00181","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּבְשָׁא\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>honey-crop, honey-store</i>. <span class=\"citation\">B. Kam. 114ᵇ</span>. <span class=\"citation\">Snh. 101ᵃ</span>. <span class=\"citation\">B. Bath. 80ᵃ</span> <a href=\"#\" data-headword=\"דּוּבְשָׁן\">דּוּבְשָׁנָן</a> their own stock of honey.</div><div class=\"sense\"><b>—2)</b> <i>honey-cake</i>.—Pl. <span dir=\"rtl\">דּוּבְשָׁנִין</span>. <span class=\"citation\">Ḥall. I, 4</span> (<span class=\"citation\">3</span>), expl. Y. ib. 57ᵈ <span dir=\"rtl\">מלי גאלה</span> meligala, honey and milk cake (Mish. ed. <span dir=\"rtl\">דובשין</span>, corr. acc.).</div>","alt":[]},"6471":{"h":"דּוּבְשָׁנִיתָא","r":"D00182","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּבְשָׁן\">preced.</a> wds.) <i>honey-like</i>. <span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">חלבניתא ד׳</span> sweet galbanum.</div>","alt":[]},"6472":{"h":"דובשקא","r":"D00183","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִפְשְׁקָא\">דִּפְשְׁקָא</a></div>","alt":[]},"6473":{"h":"דּוּג","r":"D00184","html":"<div class=\"sense\"> , <i>to be anxious, troubled</i>. Part. <a href=\"#\" data-headword=\"דָּאֵיג\">דָאִיג</a>, <a href=\"#\" data-headword=\"דָּיֵיג\">דָּיֵיג</a>. <span class=\"citation\">Sabb. 156ᵇ</span> <span dir=\"rtl\">הוה דְאִיגָא וכ׳</span> she was very much troubled over it. <span class=\"citation\">M. Kat. 28ᵃ</span> <span dir=\"rtl\">הוו קא דַיְיגֵי רבנן</span> the rabbis were troubled (over R. Huna’s sudden death).</div>","alt":[]},"6474":{"h":"דוגזר","r":"D00185","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*רוּנְגָּר\">רוּנְגָּר</a></div>","alt":[]},"6475":{"h":"דּוּגֵי","r":"D00186","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּג\">דוג</a>, v. <a href=\"#\" data-headword=\"דָּאַג\">דָּאַג</a>) <i>drippings</i> from melting fat.—<a href=\"#\" data-headword=\"דָּרֵי\">בֵּי ד׳</a> a receptacle for the drippings of a roast. <span class=\"citation\">Ḥull. 111ᵇ</span></div>","alt":[]},"6476":{"h":"דוגיאות","r":"D00187","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Deut. 923</span>, v. <a href=\"#\" data-headword=\"כדכיאות\">כדכיאות</a></div>","alt":[]},"6477":{"h":"דוגין","r":"D00188","html":"<div class=\"sense\">, <span class=\"citation\">Y. Keth. II, 26ᵈ</span>, v. <a href=\"#\" data-headword=\"זוֹגָא\">זוֹג</a></div>","alt":[]},"6478":{"h":"דּוּגִית","r":"D00189","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"דְּגוּגִית\">דגוגית</a>, denom. of <a href=\"#\" data-headword=\"דָּג\">דָּג</a>) <i>fisher-boat, light-going boat for shallows</i>, Palestinean word for Babylonian <a href=\"#\" data-headword=\"בִּיצִּית\">בִּיצִּית</a>. <span class=\"citation\">B. Bath. 73ᵃ</span>; <span class=\"citation\">78ᵇ</span>; Y. ib. V, beg. 15ᵃ</div>","alt":[]},"6479":{"h":"דּוּגְמָא","r":"D00190","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (δεῖγμα, cmp. παράδειγμα) </div><div class=\"sense\"><b>1)</b> <i>simile, illustration</i> (cmp. <span dir=\"rtl\">מָשָׁל ל־</span>, <span dir=\"rtl\">משל למה הדבר דומה</span>). Cant. R., introd. <span dir=\"rtl\">עד … היתה ד׳</span> up to Solomon’s days the method of argument by illustration was unknown (in Hebrew literature).</div><div class=\"sense\"><b>—2)</b> <i>show, exhibition, public appearance</i>. <span class=\"citation\">Y. Hor. III, beg. 47ᵃ</span> <span dir=\"rtl\">די׳ דידכו דמי וכ׳</span> (prob. to be read <span dir=\"rtl\">דמיא</span>) your appearance resembles that of your Maker. <span class=\"citation\">Eduy. V, 6</span>; <span class=\"citation\">Ber. 19ᵃ</span> <span dir=\"rtl\">ד׳ השקוה</span> it was for show that they made her drink, i.e. they merely pretended to give her the real ‘bitter waters’; [oth. opin. they performed the act on one who was, <i>like themselves</i>, a descendant of gentiles; <span class=\"citation\">Y. M. Kat. III, 81ᵈ</span> <span dir=\"rtl\">דִּכְמָהּ השקוה</span>, (a popular adaptation of our w.; v. <a href=\"#\" data-headword=\"דִּכְמָא\">דִּכְמָא</a>), expl. <span dir=\"rtl\">דִּכְוָותָהּ</span> something like it]. Midr. Sam. ch. XX (expl. <span dir=\"rtl\">תפקד לשלום</span>, <span class=\"citation\">I Sam. XVII, 18</span>) <span dir=\"rtl\">ד׳ דידהין</span> how they look.</div><div class=\"sense\"><b>—3)</b> <i>sample, example, token</i> (corresp. to h. <a href=\"#\" data-headword=\"אוֹת I\">אוֹת</a>). <span class=\"citation\">Ḥag. 16ᵃ</span> (play on <span dir=\"rtl\">ד̇ג̇ול מ̇רבבה</span>, <span class=\"citation\">Cant. V, 10</span>) <span dir=\"rtl\">ד̇וג̇מ̇א הוא ברבבה שלו</span> He is exemplified by His myriad (of angels), i.e. the Divine nature is recognized indirectly from the nature of His ministering messengers, v. <span class=\"citation\">Cant. R. to V, 9</span>.—<span class=\"citation\">Keth. 28ᵇ</span> <span dir=\"rtl\">קחו לכם ד׳ וכ׳</span> take a warning example &amp;c. <span class=\"citation\">Taan. 23ᵃ</span> <span dir=\"rtl\">ד׳ לדורות</span> a sample (of great fertility) as a lesson for future generations. <span class=\"citation\">Sabb. 30ᵇ I</span> will show thee <span dir=\"rtl\">דּוּגְמָתָן וכ׳</span> (Ms. M. <span dir=\"rtl\">דּוּגְמָתוֹ</span>) the like thereof in this world.—<span class=\"citation\">Ib. 11ᵇ</span> the dyer must not go out on the Sabbath <span dir=\"rtl\">בדו׳ שבצוארו</span> (Ar. <span dir=\"rtl\">בדי׳ שבאזנו</span>; Tosef. ib. I, 8 <span dir=\"rtl\">בדו׳ שבאזנו</span>) with the sample of colors around his neck, v. <a href=\"#\" data-headword=\"אוֹת II\"><span dir=\"rtl\">אוֹת</span> II</a>.—<span class=\"citation\">Num. R. s. 6</span> (expl. <span class=\"citation\">Job XXXVI, 7</span> <a href=\"#\" data-headword=\"עֵינָיו\">עיניו</a>) <span dir=\"rtl\">ד׳ דידהו</span> that which is like his own doing, i.e. some realization of his ideal, v. <a href=\"#\" data-headword=\"עַיִן ²\">עֵינָא</a>; Midr. Sam. ch. XXVIII <span dir=\"rtl\">דוגמה דידהון</span>; <span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">דוגמת דידיה</span> (corr. acc.), v. <a href=\"#\" data-headword=\"דּוּגְמַטְרִין\">next w.</a>; a. fr.—Pl. <span dir=\"rtl\">דּוּגְמוֹת</span>. <span class=\"citation\">B. Kam. 119ᵇ</span>, v. <a href=\"#\" data-headword=\"אוֹת I\">אוֹת</a> II (Var. Ms. <span dir=\"rtl\">דּוּגְמָאוֹת</span>). [Our w., owing to its phonetic resemblance to <a href=\"#\" data-headword=\"דִּכְמָא\">דִּכְמָא</a>, is inflected as though it were a native, whence the forms: <a href=\"#\" data-headword=\"דּוּגְמָא\">דּוּגְמָה</a>, <span dir=\"rtl\">דּוּגְמת</span>, <span dir=\"rtl\">דוּגְמָת־</span>, <span dir=\"rtl\">דּוּגְמוֹת</span>, and even a Var. to <span class=\"citation\">Tosef. Sabb. I, 8</span> <span dir=\"rtl\">דִּגְמוֹ</span>, as though fr. <a href=\"#\" data-headword=\"דֶּגֶם\">דֶּגֶם</a>.]</div>","alt":["דִּיגְמָא","דּוּגְמָה"]},"6480":{"h":"דּוּגְמַטְרִין","r":"D00191","html":"<div class=\"sense\">, (<span dir=\"rtl\">דיגמטורי</span>) m. pl. (a transpos. of διαγράμματα; cmp. <a href=\"#\" data-headword=\"גִּימַטְרְיָא\">גִּימַטְרְיָא</a>) <i>plans, designs</i>. <span class=\"citation\">Gen. R. s. 11</span> מראה לאלו מעין ד׳ שלהן וכ׳ Ar. (ed. <span dir=\"rtl\">דוגמא גטורין</span>, some ed. in one w., corr. acc.; Tanḥ. Ki Thissa 33 <span dir=\"rtl\">מעין דוגמא שלהם</span>) He shows to these (the righteous) something corresponding to their designs (reward) and to those &amp;c. Tanḥ. P’kudé 11 (ref. to <span class=\"citation\">Job XXXVI, 7</span>) the Lord refuses not to the righteous man <span dir=\"rtl\">ד׳ שלו</span> a realization of his designs (ideals), v. <a href=\"#\" data-headword=\"דּוּגְמָא\">preced.</a></div>","alt":["דִּגְמַטְרִין"]},"6481":{"h":"דוגמניות","r":"D00192","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. CXVIII</span>, read <span dir=\"rtl\">הֶגְמוֹנִיּוֹת</span>, v. <a href=\"#\" data-headword=\"הֶגְמוֹנְיָא\">הֶגְמוֹנְיָה</a></div>","alt":[]},"6482":{"h":"דָּוִד","r":"D00193","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>David</i>, King of Israel. <span class=\"citation\">Ber. 4ᵃ</span>; a. v. fr.—<span dir=\"rtl\">בן ד׳</span> or <a href=\"#\" data-headword=\"ד׳\">ד׳</a> (= <a href=\"#\" data-headword=\"מָשִׁיחַ\">משיח</a>) the son of David (the David of the future), the redeemer of Israel from captivity. <span class=\"citation\">Snh. 98ᵇ</span> <span dir=\"rtl\">ד׳ אחר</span> a second David. <span class=\"citation\">R. Hash. 25ᵃ</span> (a secret watchword) <span dir=\"rtl\">ד׳ מלך וכ׳</span> David, the King of Israel, is alive &amp;c. <span class=\"citation\">Y. Ber. II, 5ᵃ</span> top. <span class=\"citation\">Yeb. 62ᵃ</span>; a. fr.</div>","alt":["דָּיִיד"]},"6483":{"h":"דּוֹד","r":"D00194","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>friend, lover, beloved;</i> (allegor.) <i>the Lord</i>, as the beloved of Israel. <span class=\"citation\">Cant. R. to I, 4</span>, v. <a href=\"#\" data-headword=\"גִּנּוּן\">גִּנּוּן</a>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>uncle, father’s brother</i>. Sifra K’dosh. Par. 10, ch. XI; <span class=\"citation\">Yeb. 54ᵇ</span>.—Fem. <a href=\"#\" data-headword=\"דּוֹדָה\">דּוֹדָה</a>, <a href=\"#\" data-headword=\"דֹּדָה\">דֹּדָה</a> <i>aunt</i>. Ib.—Pl. <span dir=\"rtl\">דּוֹדִים</span> 1) <i>friends, related</i>. <span class=\"citation\">Y. Snh. XI, 30ᵃ</span> bot.; <span class=\"citation\">Y. Ber. I, 3ᵇ</span> bot. (ref. to <span class=\"citation\">Cant. I, 2</span>) <span dir=\"rtl\">ד׳ דברי וכ׳</span> the words of the scholars are related to the words of the Law; Cant. R. to l. c. <span class=\"citation\">Ab. Zar. 35ᵃ</span> דברי דודים Ms. M. (ed. <span dir=\"rtl\">דודיך</span>) the words of the friends (the scholars); <span class=\"citation\">Num. R. s. 14</span>. <span class=\"citation\">Gen. R. s. 37</span> <span dir=\"rtl\">בני דוֹדֵיהֶן וכ׳</span> cousins (related nation).—2) (abstr. noun) <i>friendship, love</i>. <span class=\"citation\">Ab. Zar. II, 5</span> (<span class=\"citation\">29ᵇ</span>) do you read <span dir=\"rtl\">כי טובים דּוֹדֶיךָ מיין … דּוֹדַיִיךְ מיין</span> Ms. M. (v. Rabb. D. S. a. l. a. Cant. R. l. c.) better is thy (God’s) love, or thy (Israel’s) love?</div>","alt":["דֹּד"]},"6484":{"h":"דּוֹדָא","r":"D00195","html":"<div class=\"sense\"> <span class=\"citation\">Gen. R. s. 37</span>, beg. <span dir=\"rtl\">בני דוֹדֵיכֶן אנן</span> we are your cousins (Yalk. Chr. 1073 <span dir=\"rtl\">דוֹדֵיכוֹן</span>, pl.).—Pl. <span dir=\"rtl\">דּוֹדַיָּא</span>. Y. Taan. IV, 69ᵃ top <span dir=\"rtl\">כן ארתהון דבני ד׳ עבדין</span> is this the way cousins act?; <span class=\"citation\">Lam. R. to II, 2</span> <a href=\"#\" data-headword=\"דדנייא\">דדנייא</a> (corr. acc.).</div>","alt":[]},"6485":{"h":"דּוּדָא","r":"D00196","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>boiler, caldron, pot</i>. <span class=\"citation\">Targ. II Kings IV, 38</span>; a. e.—<span class=\"citation\">Snh. 64ᵃ</span>, v. <a href=\"#\" data-headword=\"אֲבָר ²\">אֲבָרָא</a>; a. fr.—Pl. <span dir=\"rtl\">דּוּדַיָּא</span>, <span dir=\"rtl\">דּוּדֵי</span>. Targ. Zach. XIV, 20; a. e.—<span class=\"citation\">Nidd. 68ᵃ</span> <span dir=\"rtl\">ד׳ תסרת</span> thou wantest boilers (for hot water). <span class=\"citation\">B. Kam. 101ᵃ</span> top, v. <a href=\"#\" data-headword=\"כַּפְרָא\">כַּפְרָא</a>. <span class=\"citation\">Sabb. 41ᵃ</span>, v. <a href=\"#\" data-headword=\"*אַנְטִיכִי\">אַנְטִיכִי</a>.—Fem. <a href=\"#\" data-headword=\"דּוּדְוָותָא\">דּוּדְוָותָא</a>, <span dir=\"rtl\">דַּדְוָו׳</span>. <span class=\"citation\">Targ. Y. Ex. XVI, 3</span>; <span class=\"citation\">XXXVIII, 3</span>; a. e. <span class=\"citation\">Targ. Y. Lev. VIII, 31</span> <span dir=\"rtl\">דּוֹדְוָותַיָּא</span> (!).</div>","alt":[]},"6486":{"h":"דודאי","r":"D00197","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*דּוּרַאי\">דּוּרַאי</a></div>","alt":[]},"6487":{"h":"דּוּדְבָא","r":"D00198","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּידְבָא\">דִּידְבָא</a></div>","alt":[]},"6488":{"h":"דּוֹדָה","r":"D00199","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹד\">דּוֹד</a></div>","alt":[]},"6489":{"h":"דּוּדְוָותָא","r":"D00200","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּדָא\">דּוּדָא</a></div>","alt":[]},"6490":{"h":"דודורין","r":"D00201","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּרְדּוּר\">דַּרְדּוּר</a></div>","alt":[]},"6491":{"h":"דּוֹדַנְיָא","r":"D00202","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּרְדַּנְיָא\">דַּרְדַנְיָא</a></div>","alt":[]},"6492":{"h":"דּוֹדָנִים","r":"D00203","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>Dodanites</i>, a Javanic tribe, v. <a href=\"#\" data-headword=\"דַּרְדַּנְיָא\">דַּרְדַּנְיָיא</a>. <span class=\"citation\">Gen. R. s. 37</span>, beg.; Yalk. Chr. 1073 (ref. to <span dir=\"rtl\">דֹּדָ׳</span>, <span class=\"citation\">Gen. X, 4</span>, a. <span dir=\"rtl\">רוֹדָ׳</span>, <span class=\"citation\">I Chr. I, 7</span>).</div>","alt":[]},"6493":{"h":"דָּוָה","r":"D00204","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דוי\">דוי</a></div>","alt":[]},"6494":{"h":"*דּוּהִי","r":"D00205","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דוי\">דוי</a>) <i>menstruation</i>. Y. Ab. Zar. II, 40ᵈ bot.; v., however, <a href=\"#\" data-headword=\"זַכְרוּתא\">זַכְרוּתָא</a>.</div>","alt":[]},"6495":{"h":"דּוּהֲנָא","r":"D00206","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"דְּהַן II\"><span dir=\"rtl\">דְּהַן</span> II</a>. <span class=\"citation\">Targ. Prov. III, 8</span> ed. Lag. (ed. <span dir=\"rtl\">רוה׳</span>, Ms. <a href=\"#\" data-headword=\"רְוָוחָא\">רַוְחָ׳</a>, h. text <span dir=\"rtl\">שקוי</span>).</div>","alt":[]},"6496":{"h":"דּוּהֲנִיתָא","r":"D00207","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּהַנְיְתָא\">דַּהַנְיְתָא</a></div>","alt":[]},"6497":{"h":"דּווָֹא","r":"D00208","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹבָא\">דּוֹבָא</a></div>","alt":[]},"6498":{"h":"דַּוָּואר","r":"D00209","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּוָּאר I\">דַּוָאר</a></div>","alt":[]},"6499":{"h":"דֵּוָודָא","r":"D00210","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*דִּיוָודָא\">דִּיוָודָא</a></div>","alt":[]},"6500":{"h":"דָּוֶוה","r":"D00211","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">דָּוִוים</span> v. <a href=\"#\" data-headword=\"דוי\">דוי</a>.</div>","alt":[]},"6501":{"h":"דְּוַוי","r":"D00212","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּוַי\">דְּוַי</a></div>","alt":[]},"6502":{"h":"דְּוַול","r":"D00213","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דול</span>) <i>bucket;</i> (collect.) <i>irrigation</i> by means of buckets. <span class=\"citation\">Targ. Is. XL, 15</span> (ed. Vien. <a href=\"#\" data-headword=\"דּוּל\">דּוּל</a>).—<span class=\"citation\">Erub. 20ᵇ</span> <span dir=\"rtl\">דרי ליה לד׳ בהדיה</span> he might carry the bucket with him.—<span class=\"citation\">B. Mets. 104ᵃ</span> top <span dir=\"rtl\">איבעי לך … בד׳</span> you ought to have brought the water over from the large well by irrigating works. <span class=\"citation\">Ib. 77ᵃ</span> <span dir=\"rtl\">מאן … לד׳</span> if one hired working men for irrigating work. <span class=\"citation\">M. Kat. 4ᵃ</span> <span dir=\"rtl\">הוה דלי ד׳</span> was doing irrigating work. <span class=\"citation\">Yeb. 97ᵇ</span> <span dir=\"rtl\">דלאי דדלו ד׳</span> ye water drawers engaged in irrigation.—Pl. <span dir=\"rtl\">דַּוְולִין</span>. Targ. II Esth. I, 2.</div>","alt":["דְּוַל","דַּוְולָא","דַּוְ׳"]},"6503":{"h":"דַּוְולָלָא","r":"D00214","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּוְלָלָא\">דַּוְלָלָא</a></div>","alt":[]},"6504":{"h":"דָּווֹן","r":"D00215","html":"<div class=\"sense\"> m. = <span dir=\"rtl\">דַּאֲבוֹן</span>. <span class=\"citation\">Ab. II, 7</span> Ar. (ed. <span dir=\"rtl\">דְּאָגָה</span>).</div>","alt":[]},"6505":{"h":"דְּוָון","r":"D00216","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דָּאבוֹנָא\">דָּאבוֹנָא</a></div>","alt":["דָּווֹנָא","דְּוָונָא"]},"6506":{"h":"דַּיְוקָא","r":"D00217","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּוְקָא\">דַּוְקָ׳</a></div>","alt":["דַּוְוקָנָא"]},"6507":{"h":"דַּוַּור","r":"D00218","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּר\">דּוּר</a></div>","alt":[]},"6508":{"h":"דַּוָור","r":"D00219","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּוָּאר I\">דַּוָּאר</a></div>","alt":[]},"6509":{"h":"דַּוְושָׁא","r":"D00220","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּשׁ\">דּוּשׁ</a>) </div><div class=\"sense\"><b>1)</b> <i>treading, passage</i>. <span class=\"citation\">Sabb. 81ᵇ</span> <span dir=\"rtl\">משום ד׳</span> because of treading down (injuring a neighbor’s field). <span class=\"citation\">B. Bath. 22ᵇ</span> <span dir=\"rtl\">ד׳ דהכא וכ׳</span> the passage between the walls (stamping the ground) is beneficial to both buildings.</div><div class=\"sense\"><b>—2)</b> <i>ordinary course, habit</i>. <span class=\"citation\">B. Kam. 116ᵇ</span> <span dir=\"rtl\">דַוְושֵׁיה נקיט ואזיל</span> he (the boatman) took his wonted course. <span class=\"citation\">Ber. 16ᵃ</span> דוושיה נקיט Ar. (ed. <span dir=\"rtl\">סרכיה</span>) he followed his habit (in recitation).</div>","alt":[]},"6510":{"h":"*דָּווּתָא","r":"D00221","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דוי\">דוי</a>) <i>the sick man’s draught, medicine for the appetite</i>. <span class=\"citation\">Targ. Job VI, 7</span> (Ms. <a href=\"#\" data-headword=\"*זָוְותָא\">זוותא</a>; h. text <span dir=\"rtl\">כדוי</span>).</div>","alt":[]},"6511":{"h":"דָּוְותָא","r":"D00222","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"דָּוָה\">דָּוָה</a>; v. <a href=\"#\" data-headword=\"דּוֹבָא\">דּוֹבָא</a>) <i>a menstruating woman</i>. <span class=\"citation\">Targ. Y. Num. XXXI, 23</span> (some ed. <a href=\"#\" data-headword=\"דָּוְתָא\">דְּוָתָא</a>).</div>","alt":["דָּוְתָא"]},"6512":{"h":"דוזגר","r":"D00223","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*רוּנְגָּר\">רוּנְגָּר</a></div>","alt":[]},"6513":{"h":"דּוּחַ","r":"D00224","html":"<div class=\"sense\">, <i>Hif.</i> <a href=\"#\" data-headword=\"נָדַח\">הֵדִיחַ</a> (b. h.; v. <a href=\"#\" data-headword=\"דְּחַהּ\">דְּחַהּ</a>) [<i>to brighten</i>,] <i>to wash off, cleanse, rinse.</i> <span class=\"citation\">Mikv. VII, 3</span>. <span class=\"citation\">Ḥull. 8ᵇ</span> <a href=\"#\" data-headword=\"מדיח\">מֵדִיחַ</a> he must wash the meat (at the place where the knife passed); a. fr.—<span class=\"citation\">Tam. IV, 2</span> <span dir=\"rtl\">בית המְדִיחִין</span> the washers’ hall where the offering meat was washed.—<span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> bot. <span dir=\"rtl\">לָדִיחַ</span> = <span dir=\"rtl\">לְהָדִיחַ</span>.</div><div class=\"sense\"><b>Hof. הוּדָח</b> <div class=\"sense\"><i>to be washed, cleansed.</i> <span class=\"citation\">Makhsh. IV, 3</span> <span dir=\"rtl\">בשביל שתּוּדַח</span> in order that the dish may be washed by the rain; <span class=\"citation\">Ḥull. 16ᵃ</span>; <span class=\"citation\">Sabb. 11ᵇ</span>; a. fr.</div></div><div class=\"sense\"><b>Nif. נִידּוֹחַ  נָדוֹחַ</b> <div class=\"sense\"><i>to be washed away</i>. <span class=\"citation\">Koh. R. to VII, 1</span>; Midr. Sam. ch. XXIII.</div></div>","alt":[]},"6514":{"h":"דּוּחַ ²","r":"D00225","html":"<div class=\"sense\"><i>Af</i>. <span dir=\"rtl\">אֲדִיחַ</span> <a href=\"#\" data-headword=\"דּוּחַ\">same</a>. <span class=\"citation\">Targ. II Chr. IV, 6</span>.</div>","alt":[]},"6515":{"h":"דּוּחָה","r":"D00226","html":"<div class=\"sense\">, <span class=\"citation\">Yeb. 80ᵇ</span>; <span class=\"citation\">Gitt. 57ᵃ</span>, v. <a href=\"#\" data-headword=\"דֵּיהֶא\">דֵּיהָה</a></div>","alt":[]},"6516":{"h":"דּוֹחִינָא","r":"D00227","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"דּוֹחַן\">דּוֹחַן</a>. <span class=\"citation\">Targ. Y. Num. XV, 19</span>.</div>","alt":[]},"6517":{"h":"דּוֹחֲכָא","r":"D00228","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּחֵיךְ\">דְּחַךְ</a>) <i>laughter, scorn</i>. <span class=\"citation\">Targ. Job XXXIV, 7</span> (Lev. <a href=\"#\" data-headword=\"דַּהֲכָא\">דַּהֲכָא</a>).</div>","alt":[]},"6518":{"h":"דּוֹחַן","r":"D00229","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>a species of millet</i>. <span class=\"citation\">Pes. 35ᵃ</span>. <span class=\"citation\">Ber. 37ᵃ</span>; a. fr.</div>","alt":[]},"6519":{"h":"דֹּוחַק","r":"D00230","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּחַק I\">דחק</a>) [<i>pressure;</i>] </div><div class=\"sense\"><b>1)</b> <i>need, distress</i>. <span class=\"citation\">Ḥag. 5ᵃ</span> <span dir=\"rtl\">בשעת דּוֹחֲקוֹ</span> just when he needs it (no sooner); <span class=\"citation\">Yeb. 63ᵃ</span> (v. Tosaf. a. l.). <span class=\"citation\">Ab. II, 3</span> <span dir=\"rtl\">בשעת דָּחְקוֹ</span> when he is in need (of official protection). <span class=\"citation\">Y. Ber. V, 9ᵇ</span> <span dir=\"rtl\">מד׳</span>, v. <a href=\"#\" data-headword=\"אַזְכָּרָה\">אַזְכָּרָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>crowd</i>, v. <a href=\"#\" data-headword=\"דִּיחוּק\">דִּיחוּק</a>.</div><div class=\"sense\"><b>—3)</b> <i>emergency</i>, v. <a href=\"#\" data-headword=\"דְּחָק\">דְּחָק</a>. [In later Hebr. <a href=\"#\" data-headword=\"דֹּוחַק\">דּוֹחַק</a> <i>a forced opinion or reply</i>, v. next w.]</div>","alt":["דֹּחַק"]},"6520":{"h":"דּוּחֲקָא","r":"D00231","html":"<div class=\"sense\"><b>1)</b> <i>squeezing, forcing</i>. <span class=\"citation\">Targ. Y. Num. XXII, 24</span> <span dir=\"rtl\">בד׳</span> in a narrow place.—<span class=\"citation\">Pes. 14ᵇ</span>, a. e. <span dir=\"rtl\">מאי דּוֹחֲקֵיה דר׳ וכ׳</span> what forces R. … (logically) to put it &amp;c.—<span class=\"citation\">Ḥull. 8ᵇ</span> <span dir=\"rtl\">ד׳ דסכינא</span> the force of the knife (the blade forcing its way).</div><div class=\"sense\"><b>—2)</b> <i>crowded state, pushing</i>. <span class=\"citation\">Ber. 6ᵃ</span> ד׳ דכלה Ms. M. (ed. <span dir=\"rtl\">ד׳ דהוה בכלה</span>) the pushing at public lectures, v. <a href=\"#\" data-headword=\"כַּלָּה\">כַּלָּה</a>. <span class=\"citation\">Ib.ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲגַר III\"><span dir=\"rtl\">אַגְרָא</span> I</a>.</div><div class=\"sense\"><b>—3)</b> <i>oppression, extortion, distress</i>. <span class=\"citation\">Targ. Ex. III, 9</span>; a. e.—<span class=\"citation\">Gitt. 45ᵃ</span> <span dir=\"rtl\">משום ד׳ דציבורא</span> because the exorbitant price is an extortion of the community.</div><div class=\"sense\"><b>—4)</b> <i>difficulty</i>. <span class=\"citation\">Bets. 30ᵃ</span> <span dir=\"rtl\">דדרו בד׳</span> (Ms. M. <a href=\"#\" data-headword=\"רהקא\">רהקא</a>) a load carried (on ordinary days) with a great effort.</div>","alt":["דּוּחְקָא"]},"6521":{"h":"דוי","r":"D00232","html":"<div class=\"sense\"> [<i>to drip, melt away</i>,] <i>to mourn, repine</i>. <span class=\"citation\">Nidd. 23ᵇ</span> (ref. to <span class=\"citation\">Deut. XXI, 17</span> <a href=\"#\" data-headword=\"אָנוּ\">אֹנוֹ</a>, cmp. <a href=\"#\" data-headword=\"דְּוַי\">דְּוַי</a>) <span dir=\"rtl\">מי שלבו דָוֶה עליו</span> a child over whose death his (the father’s) heart is grieved. <span class=\"citation\">Ber. 16ᵇ</span> <span dir=\"rtl\">אל יִדְיֶה לבנו</span> may our heart not sink. <span class=\"citation\">Kidd. 81ᵇ</span> <span dir=\"rtl\">יִדְווּ כל הדָּוִוים</span> let all those mourn who feel the affliction; <span class=\"citation\">Naz. 23ᵃ</span>. <span class=\"citation\">Yeb. 47ᵃ</span> the Israelites … are <span dir=\"rtl\">דווים</span> (some ed. <span dir=\"rtl\">דְּווּיִים</span>, Part. pass.) broken down (under persecution). <span class=\"citation\">Gen. R. s. 60</span>; s. 74; a. fr.</div><div class=\"sense\"><b>Nif. נִדְוֶוה</b> <div class=\"sense\"><i>to be afflicted</i>. Pesik. Asser, p. 96ᵃ <span dir=\"rtl\">על אותו האיש שנ׳</span> over this man (me) in his affliction; Tanḥ. R’eeh ed. Bub. 7 (Tanḥ. ib. 10 <span dir=\"rtl\">שנידוהו</span>, <span class=\"citation\">Yalk. Deut. 892</span>; <span class=\"citation\">Yalk. Prov. 962</span> <span dir=\"rtl\">שנדוהו</span>, corr. acc.).</div></div><div class=\"sense\"><b>Hif. הִדְוֶה</b> <div class=\"sense\"><i>to afflict</i>. Y. R. Hash. I, 57ᵇ bot. <span dir=\"rtl\">מַדְוֶה לה וכ׳</span> afflicts it (the year, causes prayers and fasting from fear of failure of the crop) in its beginning.</div></div>","alt":["דָּוָה"]},"6522":{"h":"דוי ²","r":"D00233","html":"<div class=\"sense\"><span class=\"citation\">Targ. Jer. XLVIII, 17</span>; a. e.</div><div class=\"sense\"><b>Ithpe. אִירְּוִי</b> <div class=\"sense\"><i>to feel pain, groan</i>. <span class=\"citation\">Ḥull. 51ᵃ</span> <span dir=\"rtl\">מִידְּווּ וקיימי</span> they groan constantly.</div></div>","alt":["דְּוָא I"]},"6523":{"h":"דוי ³","r":"D00234","html":"<div class=\"sense\"> (v. preced; cmp. b. h. <a href=\"#\" data-headword=\"כָּסַף\">כָּסַף</a>, <a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a>) <i>to look out for, espy</i>. <span class=\"citation\">Sabb. 35ᵃ</span> דָּוֵי למזרח Ar. (ed. <a href=\"#\" data-headword=\"דָּאוֵי\">דָּאוֵי</a>) he looked eastward (for the reflection of the setting sun). Ib. 53ᵇ they raise their nostrils [read:] <span dir=\"rtl\">ומסגי כי דָּוֵי</span> (Ms. O. <span dir=\"rtl\">כדובי</span>) and march like looking out (for the wolf). <span class=\"citation\">Ker. 6ᵃ</span> דְּווּ לפומיה וכ׳ Ar. (ed. <span dir=\"rtl\">חזו</span>) watch the lips of &amp;c. <span class=\"citation\">Tam. 26ᵇ</span> <span dir=\"rtl\">דוי להכא וכ׳</span> he (the watchman) looks out in both directions.</div>","alt":["דְּוָא II"]},"6524":{"h":"דָּוֵי","r":"D00235","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (דְּוָא I) <i>sad, depressed</i>. <span class=\"citation\">Targ. I Kings XX, 43</span>; <span class=\"citation\">XXI, 4</span> (ed. Vien. <a href=\"#\" data-headword=\"דָּוֵי\">דַּוָי</a>).—Pl. <a href=\"#\" data-headword=\"דְּוָן\">דָּוָן</a>, <a href=\"#\" data-headword=\"דְּוָון\">דָּוָון</a>. <span class=\"citation\">Targ. Is. XVI, 7</span> (ed. Lag. <span dir=\"rtl\">הו׳</span>, corr. acc.); <span class=\"citation\">11</span>.</div>","alt":["דַּוֵּי"]},"6525":{"h":"דְּוַי","r":"D00236","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"דְּוַי\">דְּוַי</a>, v. <a href=\"#\" data-headword=\"דָּוֵי\">preced.</a>) <i>grief, affliction</i>. <span class=\"citation\">Targ. Gen. XXXV, 18</span> (h. text <a href=\"#\" data-headword=\"אוֹנִי I\">אוֹנִי</a>, v. <a href=\"#\" data-headword=\"דָּוָה\">דָּוָה</a>). <span class=\"citation\">Targ. Y. ib. XLII, 38</span> <span dir=\"rtl\">דָּווֹי</span> (O. <span dir=\"rtl\">דוונא</span>).</div>","alt":["דְּוַוי","דֵּיוָא"]},"6526":{"h":"דַּוְיָא","r":"D00237","html":"<div class=\"sense\"> m. <a href=\"#\" data-headword=\"דְּוַי\">same</a>. <span class=\"citation\">Snh. 100ᵇ</span> (cit. fr. the Book of Ben Sira) <span dir=\"rtl\">לא תעיל ד׳ וכ׳</span> suffer not grief to enter thy heart &amp;c.; v. <a href=\"#\" data-headword=\"גִּיבַּר\">גִּיבַּר</a></div>","alt":[]},"6527":{"h":"דְּוָיָא","r":"D00238","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹבָא\">דּוֹבָא</a></div>","alt":[]},"6528":{"h":"דִּוְיוֹן","r":"D00239","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דוי\">דוי</a>) <i>grief</i>. <span class=\"citation\">Yalk. Jer. 279</span> <span dir=\"rtl\">דּוְיוֹנוֹ של בית</span> the grief over the (destroyed) Temple (differ. in Lam. R. introd. 32).</div>","alt":[]},"6529":{"h":"דְּוִיל","r":"D00240","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (דּוּל Af.) <i>winding; clue</i>, only in <span dir=\"rtl\">דויל ידיה</span> the clue which one’s own hand wound up, i.e. <i>one’s own doing</i>. <span class=\"citation\">Pes. 28ᵃ</span>, v. <a href=\"#\" data-headword=\"גִּירָאָה\">גִּירָאָה</a>. Cmp. <a href=\"#\" data-headword=\"דְּלִיל\">דְּלִיל</a>.</div>","alt":[]},"6530":{"h":"דּוּךְ I","r":"D00241","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to pound, break</i>. <span class=\"citation\">Y. Bets. I, 60ᵈ</span> top <span dir=\"rtl\">ויָדוֹךְ וכ׳</span> but why should he not pound a day before?—Part. pass. <a href=\"#\" data-headword=\"דֵּךְ\">דָּךְ</a>, v. <a href=\"#\" data-headword=\"דַּךְ\">דַּךְ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to designate, mark off</i>, v. <a href=\"#\" data-headword=\"דּוּךְ II\"><span dir=\"rtl\">דּוּךְ</span> II</a>. [<span class=\"citation\">Gen. R. s. 5</span>, v. <a href=\"#\" data-headword=\"דּוּךְ III\"><span dir=\"rtl\">דּוּךְ</span> III</a>.]</div><div class=\"sense\"><b>Nif. נִידּוֹךְ  נָדוֹךְ</b> <div class=\"sense\"><i>to be pounded, crushed</i>. <span class=\"citation\">Bets. I, 7</span> <span dir=\"rtl\">נִדּוֹכִין כדרכן</span> are pounded (on Holy Days) in their usual way. <span class=\"citation\">Ib. 14ᵃ</span> <span dir=\"rtl\">לָדוֹכָהּ וכ׳</span> as to pounding it (salt) alone. <span class=\"citation\">Yoma 75ᵃ</span> <span dir=\"rtl\">דבר שנ׳ וכ׳</span> something which is pounded in the mortar (spices); a. fr.</div></div><div class=\"sense\"><b>Pol. דּוֹכֵךְ</b> <div class=\"sense\">, part. pass. <span dir=\"rtl\">מְדוּכָּךְ</span> <i>crushed</i>. <span class=\"citation\">Yalk. Ps. 848</span> <span dir=\"rtl\">מְדוּכָּכִים אנו</span> we are crushed (<span class=\"citation\">Gen. R. s. 5</span> <span dir=\"rtl\">מדוכנין</span>, v. <a href=\"#\" data-headword=\"דָּכַן\">דָּכַן</a>).</div></div>","alt":[]},"6531":{"h":"דּוּךְ","r":"D00242","html":"<div class=\"sense\">Part. <a href=\"#\" data-headword=\"דָּאֵיג\">דָּאִיךְ</a>, <a href=\"#\" data-headword=\"דָּאֵיג\">דָּאֵיךְ</a>. <span class=\"citation\">Targ. O. Num. XI, 8</span>. <span class=\"citation\">Bets. 14ᵃ</span> <a href=\"#\" data-headword=\"דּוּךְ\">דּוֹךְ</a>, v. infra.</div><div class=\"sense\"><b>Pa. דַּיֵּיךְ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"דּוּךְ I\">same</a>. <span class=\"citation\">Bets. 14ᵃ</span> <span dir=\"rtl\">כי דַיְיכַת וכ׳</span> ed. (Ms. M. <span dir=\"rtl\">דייקת … דוק</span>) when thou poundest (on a Holy Day), bend the mortar sideways and pound.</div></div><div class=\"sense\"><b>Af. אָדֵיךְ</b> <div class=\"sense\"> (cmp. <span dir=\"rtl\">דעך</span>) <i>to extinguish</i>. <span class=\"citation\">Kidd. 81ᵃ</span> אתו כ&quot;ע לַאֲדוּכֵיה Ar. s. v. <span dir=\"rtl\">אדך</span> (missing in ed.) people came to put the fire out.</div></div>","alt":[]},"6532":{"h":"דּוּךְ II","r":"D00243","html":"<div class=\"sense\">, m. (cmp. <a href=\"#\" data-headword=\"דֵּךְ\">דֵּךְ</a>; Assyr. <a href=\"#\" data-headword=\"דכי\">דכי</a> <i>to muster</i>, Schr. KAT p. 209<sup>9</sup>) [<i>marked off, pointed out</i>,] <i>place, stand, hall</i>. <span class=\"citation\">Targ. I Kings XIV, 28</span> (ed. Lag. <span dir=\"rtl\">דובא</span>, some ed. <span dir=\"rtl\">רובא</span>, corr. acc.); <span class=\"citation\">Targ. II Chr. XII, 11</span> (h. text <a href=\"#\" data-headword=\"תָּא\">תָּא</a>).—<span class=\"citation\">Ber. 18ᵇ</span>. <span class=\"citation\">Ib. 42ᵇ</span>.  v. <a href=\"#\" data-headword=\"דּוּכְתָּא\">דּוּכְתָּא</a>.</div>","alt":["דּוּכָא"]},"6533":{"h":"דּוּךְ III","r":"D00244","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דּוּךְ II\">preced.</a>) <i>leader, chief commander</i>, only in <span dir=\"rtl\">דּוּךְ דּוּכָנִין</span> (an adaptation of dux ducum, δώξ δωκῶν, v. Du Cange s. v.) the leader of the services of the Levites, v. <a href=\"#\" data-headword=\"דּוּכָן\">דּוּכָן</a>. <span class=\"citation\">Y. Sabb. X, 12ᶜ</span>; <span class=\"citation\">Num. R. s. 7</span> (rendering of <span dir=\"rtl\">נשיא נשיאי</span> <span class=\"citation\">Num. III, 32</span>). <span class=\"citation\">Num. R. s. 4</span>, end [read:] <span dir=\"rtl\">אלעזר היה דוך דוכנין וכ׳</span> Eleazar was chief commander, prince over princes; cmp. <a href=\"#\" data-headword=\"דּוּכּוֹס\">דּוּכּוֹס</a>.—*Pl. <span dir=\"rtl\">דּוּכִים</span>. <span class=\"citation\">Gen. R. s. 5</span> (play on <span dir=\"rtl\">ד̇כ̇י̇ם̇</span>, <span class=\"citation\">Ps. XCIII, 3</span>) (‘the rivers lift up their voices’, saying to the waves of the Sea) <span dir=\"rtl\">דּוֹּכִֹיֹםֹ קבלונו</span> ye leaders, receive us; [<span class=\"citation\">Yalk. Ps. 848</span> <span dir=\"rtl\">דַּכִּים אנו</span> we are crushed].</div>","alt":[]},"6534":{"h":"דּוּכָא","r":"D00245","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּךְ II\"><span dir=\"rtl\">דּוּךְ</span> II</a></div>","alt":[]},"6535":{"h":"דּוּכּוֹס","r":"D00246","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (dux) <i>dux, commander</i>. <span class=\"citation\">Ex. R. s. 15</span>; a. fr.—[<span class=\"citation\">Gen. R. s. 5</span> לדוכוס ים Rashi, v. <a href=\"#\" data-headword=\"דִּכְסָס\">דכסס</a>.]—Pl. <span dir=\"rtl\">דּוּכְסִים</span>, <span dir=\"rtl\">דּוּכּוֹסִין</span>. <span class=\"citation\">Cant. R. to II, 15</span> <span dir=\"rtl\">עשו ודוּכְסֶיהָ</span> (read <a href=\"#\" data-headword=\"רומי\">רומי</a>) Rome and her <i>duces</i>. <span class=\"citation\">Gen. R. s. 78</span> <a href=\"#\" data-headword=\"דּוּכָּס\">דּוּכְסַי</a> my (Rome’s) <i>duces;</i> a. fr. [<span class=\"citation\">Lev. R. s. 16</span> <span dir=\"rtl\">דוכוסיא רואני</span>, read as ed. Wil. <span dir=\"rtl\">דוכוס אחד ר׳</span>.] V. <a href=\"#\" data-headword=\"דּוּכָּס\">דּוּכְסָא</a>.</div>","alt":["דּוּכָּס"]},"6536":{"h":"דוכוסיא","r":"D00247","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּכּוֹס\">preced.</a></div>","alt":[]},"6537":{"h":"דּוּכִיתָא","r":"D00248","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּךְ\">דּוּךְ</a>) <i>mortar</i>(h. . <span class=\"citation\">Targ. Y. I Num. XI, 8</span>.</div>","alt":[]},"6538":{"h":"דּוּכָן","r":"D00249","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"דּוּךְ II\"><span dir=\"rtl\">דּוּךְ</span> II</a>) <i>place to stand on, stand, stage</i>, esp. <i>Dukhan</i>, the priests’stage from which they pronounce the benediction. <span class=\"citation\">Midd. II, 6</span>; a. fr.—<span dir=\"rtl\">עלה לד׳</span> to go up the stage, <i>to officiate as priest</i>. <span class=\"citation\">Sabb. 118ᵇ</span>; a. e.—2) <i>religious service from the stand, the Levite’s singing, teaching</i>. <span class=\"citation\">Meg. 3ᵃ</span>; <span class=\"citation\">Arakh. 4ᵃ</span> the Levites <span dir=\"rtl\">מִדּוּכָנָן</span> Ms. M. (ed. <span dir=\"rtl\">בר׳</span>) must interrupt their services.—Pl. <span dir=\"rtl\">דּוּכָנִים</span>, <span dir=\"rtl\">דּוּכָנִין</span>, v. <a href=\"#\" data-headword=\"דּוּךְ III\"><span dir=\"rtl\">דּוּךְ</span> III</a>. Cmp. <a href=\"#\" data-headword=\"דָּכוֹן\">דָּכוֹן</a>.</div>","alt":[]},"6539":{"h":"דּוּכָן ²","r":"D00250","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Num. VI, 23</span>. <span class=\"citation\">Targ. Ezek. XLII, 12</span> (h. <span dir=\"rtl\">גדרת</span>); a. e.—In gen. <i>teacher’s platform, pulpit</i>. <span class=\"citation\">B. Bath. 21ᵃ</span> ריש ד׳ <i>superintendent of the platform</i>, title of a tutor who assists the teacher of a primary class numbering more than twenty five pupils.—Cmp. <a href=\"#\" data-headword=\"דִּכְוָון\">דִּכְוָון</a>.</div>","alt":["דּוּכָנָא"]},"6540":{"h":"דּוֹכְנָה","r":"D00251","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּךְ\">דוך</a>, v. <span dir=\"rtl\">דכן</span>) <i>pounding, pounded dish</i>. <span class=\"citation\">Y. M. Kat. I, 80ᵈ</span> bot. buy for us <span dir=\"rtl\">שיחורין לד׳</span> peas for pounding.</div>","alt":[]},"6541":{"h":"דּוּכָּס","r":"D00252","html":"<div class=\"sense\"> <span class=\"citation\">Lam. R. to I, 5</span>. <span class=\"citation\">Ab. Zar. 11ᵃ</span>; a. e.—Pl. <span dir=\"rtl\">דּוּכְסִין</span>, <span dir=\"rtl\">דּוּכְסַיָּיא</span>. <span class=\"citation\">Targ. Cant. VI, 8</span>; a. e.—<span class=\"citation\">Gen. R. s. 67</span>; a. fr.—<span class=\"citation\">Koh. R. to X, 18</span>; Lam. R. introd. (R. Alex. 2) (ref to <span class=\"citation\">Is. XXII, 8</span> <a href=\"#\" data-headword=\"מָסַךְ I\">מסך</a>) [read:] <span dir=\"rtl\">גלי דֻּכְסַיֵּיה</span> He uncovered (disgraced) its (the Temple’s) commanders (cmp. <a href=\"#\" data-headword=\"דּוּךְ III\"><span dir=\"rtl\">דּוּךְ</span> III</a>).</div>","alt":["דּוּכְסָא"]},"6542":{"h":"דוכסוסטון","r":"D00253","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּכְסוּסְטוֹס\">next w.</a></div>","alt":[]},"6543":{"h":"דּוּכְסוּסְטוֹס","r":"D00254","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transpos. of δύσχιστος) <i>hard to split</i>, an inferior kind of <i>parchment</i>, opp. to <span dir=\"rtl\">קלף</span>, a split parchment of superior quality. <span class=\"citation\">Men. 31ᵇ</span>. <span class=\"citation\">Ib. 32ᵇ</span> sq.; <span class=\"citation\">Sabb. 79ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">דּוּכְסוּסְטִין</span>. Y. Sabb. VIII, 11ᵇ (not <span dir=\"rtl\">טון …</span>).</div>","alt":[]},"6544":{"h":"דּוּכְסוּסְיָא","r":"D00255","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דּוּךְ III\"><span dir=\"rtl\">דּוּךְ</span> III</a>, a. <a href=\"#\" data-headword=\"סוּסְיָא\">סוּסְיָא</a>; a popular adaptation of <span dir=\"rtl\">טַכְסְיוֹטָא</span>, ταξεώτης) <i>the magistrate’s officer, sergeant</i>. <span class=\"citation\">Meg. 27ᵃ</span> <span dir=\"rtl\">דוכסו׳</span> ed. (Ms. M. <span dir=\"rtl\">דוכסס׳</span>, Ar. <span dir=\"rtl\">דכסס׳</span>), expl. by R. Shesheth <span dir=\"rtl\">פרשא דמתא</span> the riding messenger of the town. [Cmp. <a href=\"#\" data-headword=\"דּוֹרְקְטִי\">דורקטי</a>.]</div>","alt":[]},"6545":{"h":"דּוּכְסוּתָא","r":"D00256","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"דּוּכָּס\">דּוּכְסָא</a>) <i>dukedom</i>, (<i>ducatus</i>), <i>governorship</i>. <span class=\"citation\">Cant. R. to VI, 12</span> [read:] <span dir=\"rtl\">הב לי ד׳ דגובבתא</span> give me the governorship of G. (v. <a href=\"#\" data-headword=\"גּוֹבְבָתָא\">גּוֹבַבְתָּא</a>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כד נסב ד׳ וכ׳</span> having entered the office he came down from there (to Sepphoris).</div>","alt":[]},"6546":{"h":"דוכסן","r":"D00257","html":"<div class=\"sense\">, Y. B. Mets. II, 8ᶜ bot. <span dir=\"rtl\">בד׳</span>, some ed., v. <a href=\"#\" data-headword=\"פְּרַכְסִין\">פְּרַכְסִין</a></div>","alt":[]},"6547":{"h":"דוכסס","r":"D00258","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּכְסָס\">דִּכְסֵס</a></div>","alt":[]},"6548":{"h":"דוכססיא","r":"D00259","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּכְסוּסְיָא\">דּוּכְסוּסְיָא</a></div>","alt":[]},"6549":{"h":"דּוּכְרָא","r":"D00260","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּכַר II\"><span dir=\"rtl\">דְּכַר</span> II</a></div>","alt":[]},"6550":{"h":"דּוּכְרָן","r":"D00261","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דָּכְרָן\">דָּכְרָן</a></div>","alt":["דּוּכְרָנָא"]},"6551":{"h":"דּוּכְרָנִית","r":"D00262","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"דּוּכְרָא\">דּוּכְרָא</a>) <i>ram-like</i>, or <i>man-like</i>. <span class=\"citation\">Keth. 11ᵃ</span>, v. <a href=\"#\" data-headword=\"אַיְלוֹנִית\">אַיְלוֹנִית</a>.</div>","alt":[]},"6552":{"h":"דּוּכְתָּא","r":"D00263","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דּוּךְ II\"><span dir=\"rtl\">דּוּךְ</span> II</a>) <i>place</i>. <span class=\"citation\">Ber. 42ᵇ</span> (interch. with <a href=\"#\" data-headword=\"דּוּךְ\">דּוּךְ</a>). <span class=\"citation\">Ib. 4ᵇ</span> <span dir=\"rtl\">בכל ד׳</span> everywhere else (in Rabbinical writings). <span class=\"citation\">Yeb. 62ᵃ</span> <span dir=\"rtl\">בד׳ אחריתי</span> in another place (of the Scriptures). <span class=\"citation\">B. Mets. 93ᵇ</span> bot.; a. v. fr.</div>","alt":[]},"6553":{"h":"דּוּל","r":"D00264","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דְּלָא\">דְּלָא</a>) <i>to wind, draw water</i>. Denom. <a href=\"#\" data-headword=\"דְּוַל\">דְּוַל</a>, <a href=\"#\" data-headword=\"דְּוַול\">דַּוְולָא</a>.</div><div class=\"sense\"><b>*. אַדְוֵיל</b> <div class=\"sense\"><i>to wind up, make skeins, prepare for spinning</i>. <span class=\"citation\">Yeb. 63ᵃ</span> זבון ולא תדויל Ar. s. v. <a href=\"#\" data-headword=\"דִּל\">דל</a> 5 buy (ready-made) and do not wind skeins (ed. <span dir=\"rtl\">זבין ולא תיזול</span>, v. <a href=\"#\" data-headword=\"זוּל\">זוּל</a> I a. II).</div></div><div class=\"sense\"><b>Ithpe. אִדְּוִיל  אִידְּ׳</b> <div class=\"sense\"><i>to be drawn from, to give water enough for irrigation</i>. <span class=\"citation\">B. Bath. 8ᵃ</span> <span dir=\"rtl\">ודילמא לא מִידְּוִול</span> but perhaps the well (to be dug) will prove unfit for irrigation? <span class=\"citation\">Ib. 12ᵇ</span></div></div>","alt":[]},"6554":{"h":"דְּוַל","r":"D00265","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּוַול\">דְּוול</a></div>","alt":["דַּוְלָא"]},"6555":{"h":"דּוּלְבָּא","r":"D00266","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּלוּב\">דְּלוּב</a></div>","alt":[]},"6556":{"h":"דּוּלְבְּקִי","r":"D00267","html":"<div class=\"sense\">, v, <a href=\"#\" data-headword=\"דְּלִפְקִי\">דְלִפְקִי</a>. </div>","alt":[]},"6557":{"h":"דַּוְלָלָא","r":"D00268","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּל\">דּוּל</a>, v. <a href=\"#\" data-headword=\"דְּוִיל\">דְּוִיל</a>) <i>clue, skein</i>.—Pl. <span dir=\"rtl\">דַּוְלָלֵי</span>. <span class=\"citation\">Ḥull. 60ᵃ</span> they give the leper a reel <span dir=\"rtl\">וסתר דַּוְלָלֵי</span> ed. (Ar. <span dir=\"rtl\">דווללא</span>) and he must wind up the clues or skeins.</div>","alt":["דַּוְולָלָא"]},"6558":{"h":"דּוּלְפִינִין","r":"D00269","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> pl<i>.</i> (δελφίν) <i>dolphins</i> (a fish about which many fables were circulated among the ancients, cmp. Sm. Ant. s. v.). <span class=\"citation\">Bekh. 8ᵃ</span> <span dir=\"rtl\">דולפנ׳</span> (Var. <span dir=\"rtl\">דּוּלְפִינָא</span>, corr. acc.; Ar. ed. pr. <a href=\"#\" data-headword=\"דִּלְדֵּל\">דִּילְ׳</a>); Tosef. ib. I, 11.</div>","alt":[]},"6559":{"h":"דּוֹלְפָנָא","r":"D00270","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דלף</span>) <i>blear-eyed</i>.—Pl. <a href=\"#\" data-headword=\"דּוֹלְפָנָא\">דּוֹלְפָנֵי</a>. <span class=\"citation\">Keth. 60ᵇ</span>. [<span dir=\"rtl\">דולפנין</span>, <span class=\"citation\">Bekh. 8ᵃ</span>, v. preced.] [<span dir=\"rtl\">דולפני</span>, <span class=\"citation\">Tosef. Kel. B. Bath. I, 9</span>, read <a href=\"#\" data-headword=\"דּוּלְפְקִי\">דולפקי</a>.]</div>","alt":[]},"6560":{"h":"דּוּלְפְקִי","r":"D00271","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּלִפְקִי\">דְּלִפְקִי</a></div>","alt":[]},"6561":{"h":"דולפקוס","r":"D00272","html":"<div class=\"sense\">, <span class=\"citation\">Sifré Deut. 231</span>, v. <a href=\"#\" data-headword=\"לִיבְדְּקוֹס\">לִיבְדְּקוֹס</a></div>","alt":["דולפקס"]},"6562":{"h":"דולריא","r":"D00273","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּרַרְיָא\">דְּרַרְיָא</a></div>","alt":[]},"6563":{"h":"דּוֹם","r":"D00274","html":"<div class=\"sense\">, imper. of <a href=\"#\" data-headword=\"דָּמַם\">דָּמַם</a>.</div>","alt":[]},"6564":{"h":"דּוּם","r":"D00275","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"דָּמַם\">דמם</a>, <a href=\"#\" data-headword=\"דְּבָב\">דבב</a>) <i>to speak in a low voice, to suspect</i>. Part. pass. <a href=\"#\" data-headword=\"דָּמִים\">דָּיִים</a> <i>suspected</i>. <span class=\"citation\">Yeb. 52ᵃ</span> <span dir=\"rtl\">מֵידַם הוה דָ׳ מחימתיה</span> he was suspected of illicit relations with his mother-in-law; <span class=\"citation\">Kidd. 12ᵇ</span> <span dir=\"rtl\">דַיְימָא חמתיה מיניה …</span> (v. Rashi to Yeb. l. c.) his mother-in-law was suspected &amp;c.; <span class=\"citation\">Yeb. 69ᵇ</span> sq.</div>","alt":["דִּים"]},"6565":{"h":"דּוּמָא","r":"D00276","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Duma</i>. <span class=\"citation\">Tosef. Par. II</span> (<span class=\"citation\">I), 1</span> <span dir=\"rtl\">וד׳ היתה נקראת</span> the cow was named Duma (Var. <span dir=\"rtl\">וד׳ שמו</span> the owner’s name was D., v. <a href=\"#\" data-headword=\"דָּמָא\">דָּמָא</a>); <span class=\"citation\">Yalk. Num. 759</span> <a href=\"#\" data-headword=\"דֶּמֶת\">דמת</a>.—V. <a href=\"#\" data-headword=\"דּוּמָה II\"><span dir=\"rtl\">דּוּמָה</span> II</a>.</div>","alt":[]},"6566":{"h":"דּוּמָה I","r":"D00277","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דּוּם\">דּוּם</a>) </div><div class=\"sense\"><b>1)</b> <i>evil report, rumor</i>. <span class=\"citation\">Nidd. 66ᵃ</span>, v. <a href=\"#\" data-headword=\"דמי\">דִּימָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>a woman of ill repute</i>. <span class=\"citation\">Sot. 27ᵃ</span>. <span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">דשדתיה ד׳ בת ד׳</span> which an ill reputed daughter of an ill-reputed mother has spun.</div>","alt":[]},"6567":{"h":"דּוּמָה II","r":"D00278","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"דּוּמָה I\">preced.</a>) <i>silence, land of death</i>. Masc. <i>Dumah</i>, the guardian angel of the deceased. <span class=\"citation\">Ber. 18ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"דּוּמָא\">דּוּמָא</a>). <span class=\"citation\">Ḥag. 5ᵃ</span> משלימנא ליה לד׳ I (the angel of death) hand him over to Dumah. <span class=\"citation\">Sabb. 152ᵇ</span></div>","alt":[]},"6568":{"h":"דּוֹמוֹס","r":"D00279","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּימוֹס I\">דִּימוֹס</a></div>","alt":[]},"6569":{"h":"דומסייא","r":"D00280","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּימוֹסִין\">דִּימוֹסִין</a></div>","alt":[]},"6570":{"h":"דּוּמִי","r":"D00281","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּם\">דּוּם</a>) <i>evil report, gossip</i>. <span class=\"citation\">M. Kat. 18ᵇ</span>; <span class=\"citation\">Yeb. 25ᵃ</span> <span dir=\"rtl\">ד׳ דמתא וכ׳</span> the gossip of a place must remain undenied for a day and a half (in order to be acted upon legally).</div>","alt":[]},"6571":{"h":"דּוּמְיָא","r":"D00282","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּמָא\">דְּמָא</a>) <i>resemblance</i>, (<i>there is</i>) <i>an analogy;</i> (<i>under</i>) <i>analogous conditions</i>. <span class=\"citation\">Kidd. 19ᵃ</span> בנו ד׳ דידיה וכ׳ ‘his son’ (<span class=\"citation\">Ex. XXI, 9</span>) means a son like himself (the father), as he (the father) is of age, so must his son (to whom he designates her) be of age. <span class=\"citation\">Shebu. 40ᵇ</span>; <span class=\"citation\">B. Mets. 4ᵇ</span> <span dir=\"rtl\">ד׳ דכלים וכ׳</span> under similar conditions as the just stated claim of chattel and landed property. <span class=\"citation\">Meg. 2ᵃ</span> זמניהם ד׳ דזמנם מה וכ׳ <i>z’mannehem</i> (their respective seasons, <span class=\"citation\">Esth. IX, 31</span>) is analogous to <i>z’mannam</i> (ib. 27); as <i>z’mannam</i> means two days &amp;c.—<span class=\"citation\">M. Kat. 4ᵃ</span>; a. fr.</div>","alt":[]},"6572":{"h":"דּוֹמִיטְיָנוֹס","r":"D00283","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Domitian</i>, the Roman Emperor. <span class=\"citation\">Y. Sabb. XIV, 14ᵈ</span> <span dir=\"rtl\">ברתיה דדמיטי׳</span>; <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> <span dir=\"rtl\">דתימטיניס</span> (corr. acc.).</div>","alt":[]},"6573":{"h":"דומין","r":"D00284","html":"<div class=\"sense\">, <span class=\"citation\">Esth. R. to VI, 10</span> <span dir=\"rtl\">ד׳ פנטון</span>, read <span dir=\"rtl\">קוֹמִיס פְרִיבָטוֹן</span>, v. <a href=\"#\" data-headword=\"בגרון\">בגרון</a>. V. <a href=\"#\" data-headword=\"קוֹמֵיס\">קוֹמִיס</a>.</div>","alt":[]},"6574":{"h":"דומינו","r":"D00285","html":"<div class=\"sense\">, read <span dir=\"rtl\">דּוֹמִינֵי</span> (vocat. of dominus) <i>O Lord</i>. <span class=\"citation\">Lam. R. to I, 5</span> Ar., v. <span dir=\"rtl\">בִּיבֵי</span>. [<a href=\"#\" data-headword=\"דומינו\">דומינו</a>, <span dir=\"rtl\">דומינון</span>, <span dir=\"rtl\">דומינין</span>, <span class=\"citation\">Gen. R. s. 8</span>; <span class=\"citation\">Koh. R. to VI, 10</span>, read <a href=\"#\" data-headword=\"הִימְנוֹן\">הִימְנוֹן</a>.]</div>","alt":[]},"6575":{"h":"דּוֹמִינְקֵי","r":"D00286","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> pl<i>.</i> (dominicae, sub aedes, v. Revue des Etudes Juives, 1884, p. 277) <i>churches</i>. <span class=\"citation\">Snh. 74ᵇ</span> הני קווקי וד׳ היכי יהבינן להו נורא Ms. M. (ed. omit. <span dir=\"rtl\">נורא</span>; Var. lect., v. Rabb. D. S. a. l.) how dare we give fire to those churches (on Sundays)? [<a href=\"#\" data-headword=\"קְוָוקֵי\">קווקי</a>, <span dir=\"rtl\">קוואקי</span> &amp;c., misnomer of κυριακή, the name used by the Greek teachers of Christianity, corresp. to the Latin dominica.—For another explan. v. Revue des Etudes Juives 1885, p. 195 sq.]</div>","alt":["דּוֹמְנִיקֵי"]},"6576":{"h":"דּוּמְכָא","r":"D00287","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּמְכָא\">דַּמְכָא</a></div>","alt":[]},"6577":{"h":"דּוּמָם","r":"D00288","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דָּמַם\">דָּמָם</a></div>","alt":[]},"6578":{"h":"דּוֹמְנִיקֵי","r":"D00289","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹמִינְקֵי\">דּוֹמִינְקֵי</a></div>","alt":[]},"6579":{"h":"דומסיא","r":"D00290","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּימוֹסְיָא\">דִּימוֹסְיָא</a></div>","alt":[]},"6580":{"h":"דומקיא","r":"D00291","html":"<div class=\"sense\">, <span class=\"citation\">Yeb. 17ᵃ</span>, v. <a href=\"#\" data-headword=\"רומקי\">רומקי</a></div>","alt":[]},"6581":{"h":"דּוּן","r":"D00292","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּין\">דִּין</a></div>","alt":[]},"6582":{"h":"*דּוֹן","r":"D00293","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דָּנָא\">דַּנָּא</a>) <i>keg, measure</i>. <span class=\"citation\">B. Bath. 90ᵇ</span> they called it <span dir=\"rtl\">ד׳ פפא</span> (quot. Tosaf. to <span class=\"citation\">Yeb. 79ᵃ</span> ed. <span dir=\"rtl\">רוז</span>, Ms. M. <a href=\"#\" data-headword=\"רָז\">רז</a>, Ms. H. <a href=\"#\" data-headword=\"כּוּז\">כּוּז</a>) and they named it (the measure introduced by Papa) <span dir=\"rtl\">ד׳ פפא</span> <i>Papa’s keg</i></div>","alt":[]},"6583":{"h":"דְּוָן","r":"D00294","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּוָון\">דְּוָון</a></div>","alt":[]},"6584":{"h":"דּוֹנָאטִיבָא","r":"D00295","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (donativa, pl.) <i>imperial donations</i>. <span class=\"citation\">Gen. R. s. 10</span>, end (<span dir=\"rtl\">בה …</span>, corr. acc.); <span class=\"citation\">Yalk. ib. 16</span> <span dir=\"rtl\">דונאט׳</span>. <span class=\"citation\">Ex. R. s. 41</span> <a href=\"#\" data-headword=\"דונה\">דונה טיבה</a> some ed. (corr. acc.). <span class=\"citation\">Num. R. s. 7</span>; a. fr.</div>","alt":["דּוֹנָטִיבָא"]},"6585":{"h":"דּוּנְבָא","r":"D00296","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּנְבָא\">דַּנְבָא</a></div>","alt":[]},"6586":{"h":"דּוּנָג","r":"D00297","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּינָג\">דִּינָג</a></div>","alt":[]},"6587":{"h":"דּוֹנַג","r":"D00298","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>wax</i>. <span class=\"citation\">Lam. R. to I, 4</span> <span dir=\"rtl\">נעשו כד׳</span> they became (yellow-complected) like wax.</div>","alt":[]},"6588":{"h":"דונגר","r":"D00299","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*רוּנְגָּר\">רוּנְגָּר</a></div>","alt":[]},"6589":{"h":"דונה","r":"D00300","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹנָאטִיבָא\">דּוֹנָאטִיבָא</a></div>","alt":["דונה טיבה","דונהטיבה"]},"6590":{"h":"דּוּס","r":"D00301","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"דּוּשׁ\">דּוּשׁ</a>) <i>to stamp;</i> denom. <a href=\"#\" data-headword=\"דַּיְּיסָא\">דַּיְיסָא</a>.</div>","alt":[]},"6591":{"h":"דּוֹסָא","r":"D00302","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (prob. an abbrev. of Dositheus, v. <a href=\"#\" data-headword=\"דּוֹסְתַּאי\">דוֹסְתַּאי</a>) <i>Dosa</i>, a Tannai, usu. named <i>R. D.</i> <i> ben Harkhinas</i>, or <i>Hork’nos.</i> <span class=\"citation\">Eduy. III, 1</span>.—<span class=\"citation\">Tosef. Kel. B. Bath. IV, 14</span>; a. fr.—<span class=\"citation\">Erub. 83ᵃ</span> [read:] <span dir=\"rtl\">ר׳ נתן אומר ר׳ ד׳ אומר</span> (v. Rabb. D. S. a. l.). [<span class=\"citation\">Y. Shek. VII, 50ᵈ</span> <span dir=\"rtl\">ר׳ ד׳</span>, <span class=\"citation\">Men. 50ᵇ</span> <span dir=\"rtl\">ר׳ יוסי</span>.] V. <a href=\"#\" data-headword=\"חֲנִינָא\">חְנִינָא</a>, a. <a href=\"#\" data-headword=\"הַרְכִּינָס\">הַרְכִּינָס</a>.</div>","alt":[]},"6592":{"h":"דוסאי","r":"D00303","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹסְתַּאי\">דּוֹסְתַּאי</a></div>","alt":[]},"6593":{"h":"דוסיקאות","r":"D00304","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. II, 3</span>, v. <a href=\"#\" data-headword=\"דִּיסַקְיָא\">דִּיסַקְיָא</a></div>","alt":[]},"6594":{"h":"דוסמקא","r":"D00305","html":"<div class=\"sense\">, Tanḥ. Noah 1, v. <a href=\"#\" data-headword=\"דּוּרְמַסְקִית\">דּוּרְמַסְקִית</a></div>","alt":["דוסקמא"]},"6595":{"h":"דּוֹסְתַּאי","r":"D00306","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Δοσίθεος) <i>Dostai</i>, </div><div class=\"sense\"><b>1)</b>  a disciple of Shammai. Orlah II, 5.—2) D. father of Abba José. <span class=\"citation\">Tosef. Peah IV, 2</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"דוסאי\">דוסאי</a>); <span class=\"citation\">Yoma 22ᵇ</span>; a. fr.—3) R. D. son of R. Judah. <span class=\"citation\">Tosef. Shebi. II, 18</span>; a. e.—4) R. D. son of R. Jannai. Tosef. Ber. VII. (VI), 8. <span class=\"citation\">Nidd. 31ᵇ</span>; a. fr.</div>","alt":[]},"6596":{"h":"דופורון","r":"D00307","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"רִיפּוּדִין\">רִיפּוֹדִין</a> m. (repudium) <i>divorce</i>. <span class=\"citation\">Gen. R. s. 18</span> (among gentiles) the wife may divorce him <span dir=\"rtl\">והיא נותנה לו ד׳</span> and she gives him the <i>repudium</i> (v. Sm. Ant. s. v.).</div>","alt":["דופורין"]},"6597":{"h":"דּוֹפִי","r":"D00308","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <a href=\"#\" data-headword=\"דֹּפִי\">דָּפִי</a>; r. <span dir=\"rtl\">דָּפָה</span> <i>to strike against, damage;</i> cmp. <span dir=\"rtl\">דפן</span>) <i>damage to reputation</i> (cmp. meanig of <a href=\"#\" data-headword=\"גָּדַף\">גָּדַף</a>), <i>taint, reproach.</i> <span class=\"citation\">Yoma 22ᵇ</span> <span dir=\"rtl\">לא היה בו שום ד׳</span> no reproach rested on Saul’s descent. <span class=\"citation\">Tem. 15ᵇ</span>; <span class=\"citation\">Tosef. B. Kam. VIII, 13</span>; a. fr.—<span class=\"citation\">Snh. 99ᵇ</span> <span dir=\"rtl\">הגדות של ד׳</span>; v. <a href=\"#\" data-headword=\"דָּרַשׁ\">דָּרַשׁ</a>.—<span class=\"citation\">Pes. 30ᵇ</span> earthen ware <span dir=\"rtl\">אינו יוצא מידי דוֹפְיוֹ לעולם</span> (Ms. O. <span dir=\"rtl\">מדפנו</span>, v. Rabb. D. S. a. l. note 50; <span class=\"citation\">Ab. Zar. 34ᵃ</span> <span dir=\"rtl\">דופנו</span>, Ms. M. <a href=\"#\" data-headword=\"דֹּפִי\">דָּפְיוֹ</a>) can never get rid of its defect (once made unclean, it cannot be cleansed by any process, v. <a href=\"#\" data-headword=\"תַּקָּנָה\">תַּקָּנָה</a>).</div>","alt":[]},"6598":{"h":"דּוֹפְיָא","r":"D00309","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ps. L, 20</span> (Var. <a href=\"#\" data-headword=\"דּוֹפִי\">דּוֹפִי</a>, <a href=\"#\" data-headword=\"דֹּפִי\">דָּפְיָא</a>, Regia <a href=\"#\" data-headword=\"דֹּפִי\">דָּפְיוּ</a> fem.).</div>","alt":[]},"6599":{"h":"דופלומטר","r":"D00310","html":"<div class=\"sense\">, v. <span dir=\"rtl\">דיפלומט׳</span></div>","alt":[]},"6600":{"h":"דופלין","r":"D00311","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*דיפלון\">דיפלון</a></div>","alt":[]},"6601":{"h":"*דּוֹפֶן","r":"D00312","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>damage, defect</i>. <span class=\"citation\">Ab. Zar. 34ᵃ</span>, v. <a href=\"#\" data-headword=\"דּוֹפִי\">דּוֹפִי</a>.</div>","alt":["דֹּפֶן"]},"6602":{"h":"דּוֹפָן","r":"D00313","html":"<div class=\"sense\"> c. (<span dir=\"rtl\">דפן</span>, v. <a href=\"#\" data-headword=\"דַּף\">דַּף</a>) </div><div class=\"sense\"><b>1)</b> <i>board-partition</i>, esp. a wall of the festive booth <a href=\"#\" data-headword=\"סוּכָּה\">(סוּכָּה</a>). <span class=\"citation\">Succ. 4ᵃ</span> <span dir=\"rtl\">ד׳ האמצעי</span> the middle of the three walls. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ד׳ עקומה</span> <i>the curved wall</i>, a legal fiction by which a part of the ceiling may be considered as part of a curved wall.—<span class=\"citation\">Ib. 6ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (trnsf.) <i>side</i> of a vessel, oppos. to bottom, rim &amp;c. Ohol. IX, 16 <span dir=\"rtl\">תחת דָּפְנָהּ</span> under the belly of its side; Tosef. ib. X, 9 <span dir=\"rtl\">דּוֹפְנָהּ</span>. Ib. VII, 10 side of a cave, opp. to <a href=\"#\" data-headword=\"שְׁקוֹף\">שקוף</a> &amp;c.; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>the chest surrounding the lungs, ribs</i>, also <i>a single rib</i>. <span class=\"citation\">Ḥull. 48ᵃ</span>, a. fr. <span dir=\"rtl\">ריאה הסמוכה לד׳</span> lungs adhering to the chest. <span class=\"citation\">Snh. 49ᵃ</span> <span dir=\"rtl\">ד׳ חמישית</span> the fifth rib (counting from the lowest).</div><div class=\"sense\"><b>—4)</b> <i>the paries of the abdomen</i>. <span dir=\"rtl\">יוצא ד׳</span> a fetus extracted by means of <i>the cesarean section</i>. <span class=\"citation\">Nidd. V, 1</span>; a. fr.—Metaph. <span dir=\"rtl\">תלה בד׳</span> to suspend from the wall, i.e. <i>to leave a decision in suspense</i>. <span class=\"citation\">Y. Kidd. IV, 65ᵇ</span> bot.; <span class=\"citation\">Y. Snh. VI, 23ᶜ</span> bot. <span dir=\"rtl\">בריפן</span> (corr. acc.).—Pl. <span dir=\"rtl\">דּוֹפַנִּים</span>, constr. <a href=\"#\" data-headword=\"דּוֹפְנִי\">דּוֹפַנֵּי</a>; mostly <a href=\"#\" data-headword=\"דְּפַנּוֹת\">דְּפַנּוֹת</a>. <span class=\"citation\">Ḥull. 45ᵇ</span> דופני ריאה <i>the grooves between the lungs</i>, <a href=\"#\" data-headword=\"דְּפַנּוֹת\">דפנות</a> <i>ribs</i>. <span class=\"citation\">Ib. 45ᵃ</span> <span dir=\"rtl\">שתי ד׳</span> two sides of the chest.—<span class=\"citation\">Succ. I, 1</span>; a. fr.—<span class=\"citation\">Tosef. Ohol. VI, 2</span> <span dir=\"rtl\">בצד דּוֹפְנִי וכ׳</span> ed. Zuck. on the <i>wall-like</i> side of the tent. Ib. <span dir=\"rtl\">עם דופני של אוהל</span>, ed. Zuck., read (with R. S. to Ohol. V, 7) <span dir=\"rtl\">רפנות</span> or (with ed.) <span dir=\"rtl\">דּוֹפְנוֹ</span>.</div>","alt":["דֹּפָן"]},"6603":{"h":"דּוֹפְנָא","r":"D00314","html":"<div class=\"sense\"> <span class=\"citation\">B. Mets. 23ᵇ</span> אי דדפנ׳ Ar. (ed. <span dir=\"rtl\">דפקא</span>) whether the piece is from the ribs.—Pl. <span dir=\"rtl\">דּוֹפַנְיָיתָא</span>. <span class=\"citation\">Targ. Y. Lev. XXIII, 42</span> <span dir=\"rtl\">(דּוֹפַנְיָיהָא</span>).—<span dir=\"rtl\">דָּפְנָתָא</span>. Y. Succ. I, 51ᵈ</div>","alt":["דָּפְנָא"]},"6604":{"h":"דּוֹפְנִי","r":"D00315","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹפָן\">דּוֹפָן</a></div>","alt":[]},"6605":{"h":"דּוֹפֵק","r":"D00316","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דפק</span>; cmp. <a href=\"#\" data-headword=\"אַגָּף\">אַגָּף</a>) <i>that against which a turning body knocks, frame, </i>esp<i>.</i> <i> dofek, the frame supporting the movable stone of a tomb</i>, v. <a href=\"#\" data-headword=\"גּוֹלֵל\">גּוֹלֵל</a>. Ohol. II, 4; a. e.—Pl. <a href=\"#\" data-headword=\"דּוֹפְקָנִין\">דּוֹפְקִין</a>. Ib. <span dir=\"rtl\">דופק ד׳</span> the frame supporting the frame stones or sills.</div>","alt":[]},"6606":{"h":"דּוֹפְקָא","r":"D00317","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Num. XIX, 16</span>; <span class=\"citation\">18</span>.</div>","alt":[]},"6607":{"h":"דּוֹפְקָנִין","r":"D00318","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">דפק</span>) <i>knockers</i>, name of a parasite plant growing on thorns, cmp. <a href=\"#\" data-headword=\"כָּשׁוּת\">כָּשׁוּת</a>. Tosef. Erub. XI (VIII), 11 <span dir=\"rtl\">קרנין וד׳</span> (Var. <span dir=\"rtl\">קוצין</span>) ‘horns’ and ‘knockers’.</div>","alt":[]},"6608":{"h":"דופרה","r":"D00319","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיפְרָא\">דִּיפְרָא</a></div>","alt":[]},"6609":{"h":"דּוּפְשְׂקָא","r":"D00320","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִפְשְׁקָא\">דִּפְשְׂקָא</a></div>","alt":[]},"6610":{"h":"דּוּץ I","r":"D00321","html":"<div class=\"sense\"> (b. h.) <i>to skip, dance; to rejoice</i>. Denom. <a href=\"#\" data-headword=\"דִּיצָה\">דִּיצָה</a>.</div>","alt":["דִּיץ"]},"6611":{"h":"דּוּץ","r":"D00322","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XLI, 14</span> <span dir=\"rtl\">תדיץ</span> ed. Lag. (Ms. <span dir=\"rtl\">תדוץ</span>, some ed. <span dir=\"rtl\">תדיף</span>, corr. acc.).—<span class=\"citation\">Targ. II Sam. I, 20</span>. <span class=\"citation\">Targ. Ps. XXI, 14</span> (ed. Lag. <span dir=\"rtl\">נְדוֹצְצָא</span> <i>Pol</i>.); a. fr.—<i>Part.</i> <a href=\"#\" data-headword=\"דָּאִיץ\">דָּאִיץ</a>, <span dir=\"rtl\">דָּיֵיץ</span>. Targ. <span class=\"citation\">Hab. I, 15</span>. <span class=\"citation\">Targ. Prov. XXIX, 6</span>; a. e.</div>","alt":["דִּיץ"]},"6612":{"h":"דּוּץ II","r":"D00323","html":"<div class=\"sense\"> (contr. of <a href=\"#\" data-headword=\"דּעַץ\">דְּעַץ</a>) <i>to prick, stick, squeeze</i>. <span class=\"citation\">Sabb. 50ᵇ</span> <span dir=\"rtl\">דָּצָהּ שלפה וכ׳</span> if he stuck it in, pulled it out &amp;c.—<span class=\"citation\">Ib. 156ᵇ</span> <span dir=\"rtl\">דָּצְתָהּ בגודא</span> (Ms. O. <span dir=\"rtl\">דעיצתא בביזעא</span>, v. Rabb. D. S. a. l. note 30) she stuck it (the brooch) into the wall. <span class=\"citation\">Ḥull. 93ᵇ</span> <span dir=\"rtl\">אי דָץ ביה מידי</span> if he stuck something into the nostrils (so as to keep them open). <span class=\"citation\">Succ. 37ᵇ</span> <span dir=\"rtl\">לא לֵדוּץ וכ׳</span> one must not squeeze the palm branch between the myrtle and willow (after they have been tied together). [<span class=\"citation\">B. Bath. 74ᵃ</span> דצייה Ar., v. <a href=\"#\" data-headword=\"דּעַץ\">דְּעַץ</a>.]</div>","alt":[]},"6613":{"h":"דּוֹק","r":"D00324","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>a withered spot in the eye</i>, v. <a href=\"#\" data-headword=\"דַּק II\"><span dir=\"rtl\">דַּק</span> II</a>.</div>","alt":[]},"6614":{"h":"דּוּק","r":"D00325","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"דּוּךְ\">דוּךְ</a>) </div><div class=\"sense\"><b>1)</b> <i>to pound, beat; to powder</i>. <span class=\"citation\">Bets. 14ᵃ</span>, v. <a href=\"#\" data-headword=\"דּוּךְ\">דּיּךְ</a>.—Part. Peil <a href=\"#\" data-headword=\"דּוּק\">דָּיִיק</a> <i>powdered</i>. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">ד׳ טפי</span> fine-powdered. <span class=\"citation\">Ḥull. 51ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּיתַּן\">כִּיתְנָא</a>, V. <a href=\"#\" data-headword=\"דְּקַק\">דְּקַק</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"בִּין\">בִּין</a>, <a href=\"#\" data-headword=\"בָּקַר\">בָּקַר</a> a. oth.) <i>to examine carefully, to be particular, exact in expression; to pay special attention, to mind</i>. Ib. 6ᵃ, a. fr. <span dir=\"rtl\">דָּק ואשכח</span> he examined and found. <span class=\"citation\">Succ. 8ᵃ</span> <span dir=\"rtl\">לא דק</span> he did not express himself exactly; a. fr.—<i>Part.</i> דָּיֵיק <i>careful</i>. <span class=\"citation\">Keth. 18ᵇ</span> <span dir=\"rtl\">מֵידַק ד׳</span> he is very careful (as to what witnesses he uses). <span class=\"citation\">Yoma 83ᵇ</span> <span dir=\"rtl\">הווה ד׳ בשמא</span> minded a man’s name (considering it an indication of his character). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא הוו דַיְיקֵי בשמא</span> did not mind &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דַּיְיקִיתוּ</span> ye mind.—Part. Peil <a href=\"#\" data-headword=\"דּוּק\">דָּיִיק</a> (v. <i>Pa</i>.) <i>proved, conclusive</i>. <span class=\"citation\">B. Kam. 3ᵇ</span> those verses <span dir=\"rtl\">לא כמר דָּיְיקֵי וכ׳</span> are no evidence either for the one or the other.—Denom. <a href=\"#\" data-headword=\"דֵּיקָא\">דֵּיקָא</a>, <a href=\"#\" data-headword=\"דְּיוּקָא\">דְּיוּקָא</a>, <a href=\"#\" data-headword=\"דַּוְקָא\">דּוְקָא</a>.</div><div class=\"sense\"><b>Pa. דַּיֵּיק</b> <div class=\"sense\"><b>1)</b> <i>to grind, to chew carefully</i>. <span class=\"citation\">Sabb. 155ᵃ</span> bot. <span dir=\"rtl\">דדֵיְּיקָה ואכלה</span> Ms. M. (ed. <span dir=\"rtl\">דדיקה באוכלא</span>) she grinds her food carefully.</div><div class=\"sense\"><b>—2)</b> <i>to argue by pressing a word, to analyze, prove</i>. <span class=\"citation\">Keth. 31ᵇ</span> <span dir=\"rtl\">ד׳ מרישא</span> takes his argument from the first clause; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to calculate exactly</i>. <span class=\"citation\">Targ. Y. Lev. XXVII, 18</span>. <span class=\"citation\">Ib. XXV, 50</span>, v. <a href=\"#\" data-headword=\"דִּקְדֵּק\">דִּקְדֵק</a>; a. e.</div></div><div class=\"sense\"><b>Af. אוֹדִיק  אֲדִיק</b> <div class=\"sense\"><i>to be punctilious, get impatient</i>. <span class=\"citation\">Koh. R. to III, 9</span> <span dir=\"rtl\">א׳ מלכא</span> the king was irritated. Pesik. B’shall. p. 86ᵇ; <span class=\"citation\">Yalk. Sam. 152</span> אוֹדִיקַת סרח וכ׳ Serah … grew <i>angry;</i> cmp. <a href=\"#\" data-headword=\"דִּקְדֵּק\">דִּקְדֵּק</a>.—2) <i>to examine, look with anxiety, wait attentively</i>. <span class=\"citation\">Targ. Prov. VII, 6</span>. <span class=\"citation\">Targ. Ps. XIV, 2</span>; a. fr.—<span class=\"citation\">Gen. R. s. 17</span> אודיק … לקלהון R. … examined into the noise they made; <span class=\"citation\">Lev. R. s. 34</span>; <span class=\"citation\">Yalk. Lev. 665</span>; <span class=\"citation\">Yalk. Is. 352</span>. Y. Keth. XII, 35ᵃ top; Y. Kil. IX, 32ᵇ top <span dir=\"rtl\">א׳ לון תכ׳</span> Bar K. looked out for them (waiting for them to ask him).</div></div>","alt":[]},"6615":{"h":"דַּוְקָא","r":"D00326","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּק\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>exactness, minuteness</i>. Nez. 7ᵇ <span dir=\"rtl\">נחית לד׳</span> enters into minuteness (saying ‘one and a half’).</div><div class=\"sense\"><b>—2)</b>  (as an adv.) <i>exactly, exclusively, only</i>. <span class=\"citation\">Yeb. 76ᵃ</span> <span dir=\"rtl\">ד׳ שערתא</span> a real barley corn it must be (nothing else). <span class=\"citation\">Men. 30ᵃ</span> <span dir=\"rtl\">באמצע שיטה ד׳</span> only in the middle of a line.—<span class=\"citation\">Gitt. 44ᵃ</span> <span dir=\"rtl\">ד׳ או לאו ד׳</span> is this meant exactly (one hundred), or not exactly? <span class=\"citation\">Men. 27ᵇ</span> אל ד׳ <i>el</i> (towards) is meant in its exact sense; a. fr.</div>","alt":["דַּוְוקָא"]},"6616":{"h":"דּוּקָא I","r":"D00327","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דוק</span>) = h. <a href=\"#\" data-headword=\"דַּק\">דַּק</a>, <i>chaff</i>. <span class=\"citation\">Targ. Is. XL, 15</span>. <span class=\"citation\">Ib. XXVIII, 28</span>.</div>","alt":[]},"6617":{"h":"דּוּקָא II","r":"D00328","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"דַּק\">דַּק</a>, <i>a withered spot in the eye</i> (or<i> withered in growth, dwarf</i>). <span class=\"citation\">Targ. O. Lev. XXI, 20</span> (Y. II ib. <span dir=\"rtl\">נניס</span>).</div>","alt":[]},"6618":{"h":"דּוּקְיָא","r":"D00329","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דוק</span>) <i>evidence by conclusion, exact meaning</i>. Keth<i>.</i> 31ᵇ <span dir=\"rtl\">בד׳ דהא וכ׳</span> they differ as to the conclusion to be drawn from this Mishnah. <span class=\"citation\">Zeb. 31ᵇ</span> (Rashi: <a href=\"#\" data-headword=\"דְּיוּקָא\">דְּיוּקָא</a>).</div>","alt":[]},"6619":{"h":"דּוֹקְיָיא","r":"D00330","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (δόκια, pl. of δόκιον) <i>beams of the ceiling</i>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (<span dir=\"rtl\">חד בר נש</span>, an oneirocritical interpret. of Kappadokia) <i>Kappa</i> in Greek is <i>twenty</i>, <span dir=\"rtl\">ד׳ בל&quot;י קורות</span> (not <span dir=\"rtl\">דיקיא</span>) <i>dokia</i> in Greek is <i>beams;</i> v. <a href=\"#\" data-headword=\"*דִּיקָא\">דִּיקָא</a>.</div>","alt":[]},"6620":{"h":"דוקלינוס","r":"D00331","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיקְלִטְיָאנוֹס\">דִּיקְלִיטְיָינוֹס</a></div>","alt":[]},"6621":{"h":"דּוּקִים","r":"D00332","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דּוּק\">דּוּק</a>) pr. n. pl. <i>Dukim</i> (cmp. <a href=\"#\" data-headword=\"צוֹפִים\">צוֹפִים</a>), <i>Dokos</i>, a stronghold near Jericho. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> <span dir=\"rtl\">טקסיס דד׳</span> the garrison of D.</div>","alt":[]},"6622":{"h":"דּוּקִינָר","r":"D00333","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ducenarius, δουκηνάριος S.) <i>commander, procurator</i>. <span class=\"citation\">Y. Ab. Zar. I, 39ᵇ</span> (Bab. <span class=\"citation\">ib. 6ᵇ</span> <a href=\"#\" data-headword=\"מִינָא II\">מינאה</a>).</div>","alt":[]},"6623":{"h":"דּוּקְלִיטְיָאנוֹס","r":"D00334","html":"<div class=\"sense\">, v. <span dir=\"rtl\">דִּיקְלִיטְ׳</span></div>","alt":[]},"6624":{"h":"דַּוְקָנָא","r":"D00335","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּק\">דּוּק</a>) <i>calculating, accurate scholar</i>. <span class=\"citation\">Ab. Zar. 10ᵃ</span> <span dir=\"rtl\">ספרא ד׳</span> an accurate scribe (paying attention to exact historical dates).—Pl. <a href=\"#\" data-headword=\"דּוּקְנִי\">דַּוְקָנֵי</a>, <a href=\"#\" data-headword=\"דְּוַול\">דַּוְו׳</a>. <span class=\"citation\">Men. 29ᵇ</span> <span dir=\"rtl\">ספרי ד׳</span> careful copyists of the Bible. <span class=\"citation\">Yeb. 43ᵃ</span> <span dir=\"rtl\">משום דמסיימי בה ד׳ זו וכ׳</span> because exact scholars report a traditional addition (to the Halachah in question), ‘These are the words of R. S.’</div>","alt":["דַּוְוקָנָא"]},"6625":{"h":"דּוּקְנִי","r":"D00336","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"דְּקַן\">דְּקַן</a>; adopted in Hebr.) <i>trimming shears</i> on a pole. <span class=\"citation\">Y. Maasr. III, end, 51ᵃ</span> <span dir=\"rtl\">היתה ניטלת בד׳</span> if the fruit is taken off with trimming shears (by a person standing outside the garden). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">צור צור דּוּקְנִיתָךְ וכ׳</span> wrap well up (keep well thy question about) the pruner (sophistical as it is), it is better than anything (the Agadists have to say).—<span class=\"citation\">Tosef. Kel. B. Mets. III, 9</span> <span dir=\"rtl\">האיזמל של די׳</span> one knife of the shears.</div>","alt":["דִּיקְנִי"]},"6626":{"h":"דּוּקְנִיתָא","r":"D00337","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּקְנִי\">preced.</a></div>","alt":[]},"6627":{"h":"דּוּקְרָא","r":"D00338","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<span dir=\"rtl\">דקר</span>) <i>fork-like reed</i>, opp. to <a href=\"#\" data-headword=\"קני\">קני</a> plain stems; prop. Pl. <span dir=\"rtl\">דּוּקְרִין</span>, <span dir=\"rtl\">דּוּקְרֵי</span>. <span class=\"citation\">Succ. 13ᵃ</span> <span dir=\"rtl\">ד׳ דקני</span> the pronged reeds (corresp. to <a href=\"#\" data-headword=\"אַפְקוֹתָא\">אַפְקוֹתָא</a> of the palm-tree, Rashi). <span class=\"citation\">Lev. R. s. 12</span>.</div>","alt":[]},"6628":{"h":"דּוֹקְרָן","r":"D00339","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <i>fork, fork-like reed, pronged pole</i>. <span class=\"citation\">Y. Erub. I, 18ᶜ</span> <span dir=\"rtl\">קנה וד׳</span> reed-stem and prongs. Ib. 19ᶜ <span dir=\"rtl\">כמין דק׳</span>; <span class=\"citation\">Y. Kil. IV, 29ᵇ</span> <span dir=\"rtl\">כמין דוק׳</span>; <span class=\"citation\">Y. Succ. I, 52ᵃ</span> bot. <span dir=\"rtl\">כמין דְּקָרִים</span> (v. <a href=\"#\" data-headword=\"דֶּקֶר\">דֶּקֶר</a>). <span class=\"citation\">Y. Shebi. II, 33ᵈ</span> top <span dir=\"rtl\">עושה לה דיק׳</span> (corr. acc.) he puts under it a pronged prop. <span class=\"citation\">Tosef. Kel. B. Mets. III, 14</span> <span dir=\"rtl\">הדוק׳</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"דורקין\">דורקין</a>).—Pl. <span dir=\"rtl\">דּוֹקְרָנִים</span>, <span dir=\"rtl\">דּוֹקְרָנִין</span>, <a href=\"#\" data-headword=\"דּוֹקְרָנָא\">דָּק׳</a>. Y. Kil. l. c. he took <span dir=\"rtl\">דוק׳ וסותם</span> forked reeds with which he closed the breach; Y. Erub. I, 19ᶜ top; Y. Succ. l. c.—<span class=\"citation\">Tosef. ib. I, 4</span> if one made a ceiling of the Succah <span dir=\"rtl\">בקנים ובד׳</span> with (plain) reeds and with forked reeds; Bab. ib. 13ᵃ <span dir=\"rtl\">קנים וד׳</span> (Ms. M. 2 <span dir=\"rtl\">קנים הד׳</span>, v. Ar. s. v. <span dir=\"rtl\">דקר</span>), expl. <span dir=\"rtl\">קנים של ד׳</span> pronged reeds. <span class=\"citation\">Tosef. Men. XI, 6</span> <span dir=\"rtl\">דומין לדק׳</span> shaped like forks; <span class=\"citation\">Men. XI, 6</span> (<span class=\"citation\">96ᵃ</span>) <span dir=\"rtl\">מפוצלין … כמין ד׳</span> Ar. (ed. omit. <span dir=\"rtl\">כמין ד׳</span>).—*Denom. <a href=\"#\" data-headword=\"מְדוּקְרָן\">מְדוּקְרָן</a> <i>fork-shaped</i>. <span class=\"citation\">Tosef. Kil. IV, 5</span> <span dir=\"rtl\">קנים מְדוּקְרָנִים</span>; <span class=\"citation\">Erub. 16ᵃ</span>; <span class=\"citation\">11ᵇ</span> <span dir=\"rtl\">קנים הדוקרנין</span> (Ms. M. <span dir=\"rtl\">הדוקרים</span>).</div>","alt":["דַּקְרָן"]},"6629":{"h":"דּוֹקְרָנָא","r":"D00340","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">דּוֹקְרָנִין</span>, <a href=\"#\" data-headword=\"דּוֹקְרָנָא\">דַּקְ׳</a>. <span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span> <span dir=\"rtl\">כמין תרין דק׳ וכ׳</span> like two prongs of light; <span class=\"citation\">Y. Ber. I, 2ᶜ</span> <span dir=\"rtl\">דקור׳</span> (corr. <span dir=\"rtl\">דוקר׳</span>); <span class=\"citation\">Gen. R. s. 50</span> Ar. (ed. <span dir=\"rtl\">תרתין קרנין</span>).</div>","alt":["דַּק׳"]},"6630":{"h":"דּוּר I","r":"D00341","html":"<div class=\"sense\"><b>[1)</b> <i>to form a circle or enclosure</i> (v. Fl. to Levy Talm. Dict. I, p. 440ᵃ sq.).—Denom. <a href=\"#\" data-headword=\"דּוּר II\"><span dir=\"rtl\">דּוּר</span> II</a>, <a href=\"#\" data-headword=\"דּוֹר\">דּוֹר</a>, <a href=\"#\" data-headword=\"דִּירָה I\">דִּירָה</a></div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"דִּירָה I\">דִּירָה</a>) <i>to reside, dwell</i>. <span class=\"citation\">Ber. 8ᵃ</span> <span dir=\"rtl\">לעולם יָדוֹר וכ׳</span> one must try to live in the same place with his teacher. <span class=\"citation\">Keth. 72ᵃ</span>; a. fr. <span dir=\"rtl\">אין אדם דָּר וכ׳</span>, v. <a href=\"#\" data-headword=\"כְּפִיפָה\">כְּפִיפָה</a>. <span class=\"citation\">Ib. 110ᵇ</span> <span dir=\"rtl\">בל הדָּר בא&quot;י</span> whoever lives in Palestine.—<span class=\"citation\">Succ. 35ᵃ</span> (ref. to <i>hadar</i>, <span class=\"citation\">Lev. XXIII, 40</span>) <span dir=\"rtl\">א&quot;ת הָדָר אלא הַדָּר דבר שֶדָּר וכ׳</span> ed. (Ms. M. <span dir=\"rtl\">הָדָר דבר הַדָּר וכ׳</span>) read not <i>hadar</i> but <i>haddar</i>, something which remains on its tree from year to year (without withering); a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to lodge</i>, v. infra.</div><div class=\"sense\"><b>Pi. דִּיֵּיר</b> <div class=\"sense\"><b>1)</b> <i>to cause a circuit;</i> ד׳ שדה <i>to let cattle change folds within a field, to collect manure in a field, by letting cattle live on it.</i> <span class=\"citation\">Shebi. III, 4</span>. Y. ib. 34ᶜ bot. <span dir=\"rtl\">מְדַיְּירִין בטובה</span> you may let your cattle live on one’s field as a favor; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to lodge</i>, v. infra.</div></div><div class=\"sense\"><b>Hif. הֵדִיר</b> <div class=\"sense\"><i>to lodge</i>. <span class=\"citation\">Pesik. R. s. 3</span>, beg. (play on <a href=\"#\" data-headword=\"דָּֽרְבָן\">דָּֽ֗רְ֗בָ֗ן֗</a>) <span dir=\"rtl\">שמֵדִ֗יר̇ ב̇ינ̇ה בפרה</span> it (the goad) causes understanding to dwell in the cow; Pesik. Baḥod. p. 153ᵃ <span dir=\"rtl\">שמורה</span> (ed. O. <span dir=\"rtl\">שמדיר</span>); <span class=\"citation\">Koh. R. to XII, 11</span> [read:] <span dir=\"rtl\">שהוא מְדַיֵּיר</span>; <span class=\"citation\">Num. R. s. 14</span> <a href=\"#\" data-headword=\"שְׁדַר I\">שדָּר</a>; Y. Snh. Tanḥ. B’haăl 15 <span dir=\"rtl\">דָּר אצל הפרה וכ׳</span>.—[Num. R. l. c. the words of the wise <span dir=\"rtl\">דָּ֗רִ֗ים ב̇ינ̇ה וכ׳</span> lodge understanding with men.]</div></div><div class=\"sense\"><b>Nithpa. נִדּיָּיר</b> <div class=\"sense\"><i>to be manured</i> by cattle living in folds, v. Piel. <span class=\"citation\">Shebi. IV, 2</span>; <span class=\"citation\">M. Kat. 13ᵃ</span>; a. e.</div></div>","alt":[]},"6631":{"h":"דּוּר","r":"D00342","html":"<div class=\"sense\">, <i>to dwell</i>. <span class=\"citation\">Targ. Ps. CV, 23</span>; a. fr.—<span class=\"citation\">Pes. 113ᵃ</span> top (v. Rabb. D. S. a. l. note 6).—Part. <a href=\"#\" data-headword=\"דָּאִיץ\">דָּאִיר</a>, <span dir=\"rtl\">דָּיֵיר</span>. <span class=\"citation\">Targ. Ps. LVII, 5</span> דָיְירָא Ms. (ed. <span dir=\"rtl\">חיירא</span>).—<span class=\"citation\">Yeb. 52ᵃ</span> <span dir=\"rtl\">דאיר בבי וכ׳</span> he resides with his father-in-law. <span class=\"citation\">B. Mets. 117ᵃ</span> <span dir=\"rtl\">דהוו דָיְירֵי</span> who occupied. <span class=\"citation\">Taan. 24ᵃ</span> דָּיִירְנָא וכ׳ I live in a poor village.</div><div class=\"sense\"><b>Pa. דַּוַּור  דַּוַּאר</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"דִּיֵּיר\">דַּיֵּיר</a> </div><div class=\"sense\"><b>1)</b> <i>to go around, to peddle</i> (cmp. h. <a href=\"#\" data-headword=\"סָחַר\">סָחַר</a>). <span class=\"citation\">R. Hash. 9ᵇ</span> (expl. <a href=\"#\" data-headword=\"דְּרוֹר\">דְּרוֹר</a>, <span class=\"citation\">Lev. XXV, 10</span>) <span dir=\"rtl\">כמְדַיֵּיר דיירא ומוביל וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">בי דיירא</span>, Ar. s. v. <span dir=\"rtl\">דר</span> 3: <span dir=\"rtl\">כי מדַוַּאר דריא</span>) as a traveller is licensed to go around and carry his goods through the whole district.</div><div class=\"sense\"><b>—2)</b> <i>to deposit manure</i>, v. <a href=\"#\" data-headword=\"דּוּר I\">preced.</a><i>Pi</i>.—<span class=\"citation\">B. Kam. 113ᵇ</span> הני דדַיְּירֵי דירי Rashi (ed. <a href=\"#\" data-headword=\"דָּרֵי\">דרי</a>, Ms. R. <span dir=\"rtl\">דמְדַיְּירֵי דיירי</span>, v. Rabb. D. S. a. l. note) those (gentiles) who manure fields for pay by letting cattle live on them in folds.</div><div class=\"sense\"><b>—3)</b> <i>to place around</i> (<i>in a row</i>, Rashi). <span class=\"citation\">Kidd. 81ᵃ</span> <span dir=\"rtl\">ד׳ גולפי</span> placed jugs around (as a partition).—</div><div class=\"sense\"><b>*4)</b> <i>to round a person, to overtake</i>. <span class=\"citation\">B. Kam. 92ᵇ</span>; <span class=\"citation\">B. Mets. 107ᵇ</span> (prov.) <span dir=\"rtl\">רהוט … ולא דַּוְּורוּהוּ וכ׳</span> Ar. (ed. <a href=\"#\" data-headword=\"מָטוּ\">מטו</a>, <a href=\"#\" data-headword=\"אַמְטוּ\">אמטו</a>) runners run but overtake not one who has taken a morning meal.</div></div>","alt":["דִּיר"]},"6632":{"h":"דּוּר II","r":"D00343","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּר\">preced.</a>, cmp. <a href=\"#\" data-headword=\"זֵר\">זֵר</a>) <i>rim, wreath.</i> <span class=\"citation\">Kel. XVI, 3</span>.—Pl. <span dir=\"rtl\">דּוּרִים</span>. Ib.</div>","alt":[]},"6633":{"h":"*דּוּר III","r":"D00344","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> a <i>stuffed bag</i>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כות׳ 2), v. <a href=\"#\" data-headword=\"אֵדֶר I\"><span dir=\"rtl\">אֵדֶר</span> I</a>. [<span class=\"citation\">Y. Snh. X, 28ᵃ</span> top; <span class=\"citation\">Num. R. s. 14</span>; <span class=\"citation\">15</span>; Tanḥ. B’haăl. 15, v. <a href=\"#\" data-headword=\"כַּדּוּר\">כַּדּוּר</a>.]</div>","alt":[]},"6634":{"h":"דּוֹר","r":"D00345","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>circle, period</i>, cmp. <a href=\"#\" data-headword=\"גִּיל I\">גִּיל</a>] <i>generation, contemporaries</i>. <span class=\"citation\">Arakh. 17ᵃ</span> <span dir=\"rtl\">ד׳ לפי פרנס</span> as the leader so the generation; a. v. fr.—<span dir=\"rtl\">ד׳ הפלגה</span> the generation which witnessed the separation of races; <span dir=\"rtl\">ד׳ המבול</span> which perished in the flood; <span dir=\"rtl\">ד׳ המדבר</span> which perished in the desert, &amp;c. <span class=\"citation\">Snh. X, 3</span> (<span class=\"citation\">107ᵇ</span>, sq.); a. fr.—Pl. <span dir=\"rtl\">דּוֹרוֹת</span>. Ib. 99ᵃ; a. fr.—לַדּוֹרוֹת <i>for all time to come; permanent</i>, opp. <span dir=\"rtl\">לשעה</span>, <span dir=\"rtl\">הוראת שעה</span> a temporary ordinance. Ib. 16ᵇ (ref. to <span class=\"citation\">Num. VII, 1</span>) <span dir=\"rtl\">אותם במשיחה ולא לד׳ וכ׳</span> only they were installed with ointment, but not as a precedent for future installations; a. fr.—<span class=\"citation\">Men. 19ᵇ</span>, a. e. <span dir=\"rtl\">ד׳ משעה לא ילפינן</span> a permanent law cannot be derived from a special temporary legislation.—<span dir=\"rtl\">פסח ד׳</span> annual Passover celebration, opp. to <span dir=\"rtl\">פסח מצרים</span> the one observed in Epypt. <span class=\"citation\">Pes. IX, 5</span>; a. fr.</div>","alt":[]},"6635":{"h":"דּוֹר ²","r":"D00346","html":"<div class=\"sense\"> imperat. of <a href=\"#\" data-headword=\"נָדַר\">נָדַר</a>. <span class=\"citation\">Kidd. 41ᵃ</span>; a. fr.</div>","alt":[]},"6636":{"h":"דּוּרָא I","r":"D00347","html":"<div class=\"sense\"><i>m</i>. (<i>v</i>. <a href=\"#\" data-headword=\"דּוּר I\"><span dir=\"rtl\">דּוּר</span> I</a>) <i>district, settlement, village</i> (corresp. to h. <a href=\"#\" data-headword=\"חָצֵר\">חָצֵר</a>). <span class=\"citation\">B. Bath. 54ᵇ</span> ד׳ דרעוותא Ms. M. (ed. <span dir=\"rtl\">דרעואתא</span>); <span class=\"citation\">Erub. 12ᵃ</span> דּוּרָה דרעותא <i>Shephardville</i> (v., however, Berl. Beitr. z. Geogr. Babyl. p. 30).—<span class=\"citation\">Pes. 40ᵃ</span> <span dir=\"rtl\">ד׳ דבי וכ׳</span> the settlement of Be-Ḥashu.—Pl. <span dir=\"rtl\">דּוּרָתַיָּא</span>. <span class=\"citation\">Targ. Ps. X, 8</span> ed. Lag. (Var. <span dir=\"rtl\">דרתיא</span>, v. <a href=\"#\" data-headword=\"דַּרְתָּא\">דַּרְתָּא</a>; Ms. <span dir=\"rtl\">דּוּרָאתָיָיא</span>).</div>","alt":[]},"6637":{"h":"דּוּרָא II","r":"D00348","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. Ges. H. Dict. s. v.) <i>dura</i>, name of <i>a jewel, mother of pearl</i>(?). <span class=\"citation\">Targ. Esth. I, 6</span> <span dir=\"rtl\">ד׳ דכרכי וכ׳</span> the dura of the Sea places.—Esth. R. to l. c. <span dir=\"rtl\">אית אתר … למרגליתא דּוּרָה</span> there is a place where a pearl (or jewel) is called <i>durah;</i> <span class=\"citation\">Meg. 12ᵃ</span> there is a precious stone in the Sea places <span dir=\"rtl\">ודִירָה שמה</span> Ms. M. (ed. <span dir=\"rtl\">דָּרָה</span>) whose name is <i>dirah</i> (<i>darah</i>); <span class=\"citation\">Y. Snh. X, 28ᵃ</span> top <span dir=\"rtl\">תמן קריין … דירה</span></div>","alt":[]},"6638":{"h":"דּוּרָא III","r":"D00349","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (דּוּר I) a <i>parasite worm</i> in the bowels. <span class=\"citation\">Num. R. s. 7</span> [read:] <span dir=\"rtl\">שאהיה נותן ד׳ במעיהן</span>; v. <a href=\"#\" data-headword=\"דְּרַרְיָא\">דְּרַרְיָא</a>.</div>","alt":["דַּוָּרָא"]},"6639":{"h":"דּוּרָא IV","r":"D00350","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (דרי II) <i>burden, load</i>. <span class=\"citation\">B. Kam. 92ᵇ</span> (prov.) <span dir=\"rtl\">אי דלית ד׳ וכ׳</span> (our w. missing in Ar. s. v. <span dir=\"rtl\">דלא</span>) if thou wilt lift the burden, I shall lift (if you will share the responsibility, I shall take the lead).</div>","alt":[]},"6640":{"h":"*דּוּרָא IV","r":"D00351","html":"<div class=\"sense\">, or <a href=\"#\" data-headword=\"דּוּרָא III\">דַּוָּרָא</a>, <a href=\"#\" data-headword=\"כֵּיפֵי\">בֵּי ך׳</a> (cmp. <a href=\"#\" data-headword=\"דַּוָּאר I\"><span dir=\"rtl\">דַּוָּאר</span> I</a>) <i>Be-Dura</i> (<i>Davvara</i>), a station near Hagronia. <span class=\"citation\">Ber. 31ᵃ</span> ed. (Ms. M. <span dir=\"rtl\">דיירא</span>, without <span dir=\"rtl\">בי</span>; Ms. F. <span dir=\"rtl\">בי דירא</span>; oth. var. <span dir=\"rtl\">דראי</span>, <a href=\"#\" data-headword=\"דרא\">דרא</a>, <span dir=\"rtl\">בי דודא</span>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"6641":{"h":"*דּוֹרָאטָא","r":"D00352","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (δώρατα, irreg. pl. of δῶρον, v. LXX, <span class=\"citation\">II Chr. XXXII, 23</span> ed. R.) <i>gifts</i>. Y’lamd. to Num. XV, 1 quot. in Ar. s. v. <span dir=\"rtl\">דריה</span>.</div>","alt":[]},"6642":{"h":"*דּוּרַאי","r":"D00353","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*דּוּרָא IV\">דּוּרָא</a>) <i>county governor</i>,—<span dir=\"rtl\">מרי ד׳</span> (Mylord, the governor), title of an officer. <span class=\"citation\">Yoma 82ᵇ</span>; <span class=\"citation\">Snh. 74ᵃ</span>; <span class=\"citation\">Pes. 25ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"דודאי\">דודאי</a>; Rashi: the lord of <i>my village</i>, v. <a href=\"#\" data-headword=\"*דּוּרָא IV\"><span dir=\"rtl\">דּוּרָא</span> I</a>).</div>","alt":[]},"6643":{"h":"דּוֹרְבָן","r":"D00354","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דָּֽרְבָן\">דָּֽרְבָן</a>.</div>","alt":[]},"6644":{"h":"דּוּרְבָּנָא","r":"D00355","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contract. of <span dir=\"rtl\">דברברנא</span>, reduplic. of <span dir=\"rtl\">דבר</span>, v. <a href=\"#\" data-headword=\"דַּבָּר\">דַּבָּר</a>; emp. <a href=\"#\" data-headword=\"*רוֹרְבָא\">רוֹרְבָּנָא</a> a. <a href=\"#\" data-headword=\"דָּֽרְבָן\">דָּֽרְבָן</a>) <i>a haughty leader</i>. <span class=\"citation\">Targ. Job XXXIV, 20</span> ed. Lag. (ed. Vien. <a href=\"#\" data-headword=\"דּוּרְבָּנָא\">דּוּרְבָּנֵי</a>).—Pl. <a href=\"#\" data-headword=\"דּוּרְבָּנָא\">דּוּרְבָּנַיָּא</a>, <a href=\"#\" data-headword=\"דּוּרְבָּנָא\">דּוּרְבָּנֵי</a>. <span class=\"citation\">Ib. XXXV, 9</span> (Var. <a href=\"#\" data-headword=\"רַבְרְבָנָא\">רַבְרְבָנַ׳</a>). <span class=\"citation\">Targ. Prov. VIII, 16</span> Var. ed. Lag. <span dir=\"rtl\">דוכרני</span> (corr. acc.). <span class=\"citation\">Targ. Ps. XXXI, 24</span>.</div>","alt":[]},"6645":{"h":"דּוּרְגּוֹן","r":"D00356","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דרג</span>) <i>a suite of graded officers</i>. <span class=\"citation\">Y. Hor. III, beg. 47ᵃ</span> הוא וכל דו׳ דידיה Himself and His entire staff (of angels); <span class=\"citation\">Y. Snh. II, 20ᵃ</span> top <span dir=\"rtl\">דר׳</span>. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">היה מניח דר׳ שלו</span> he (Moses) left his escort.—Y’lamd. to Num. XII, 1, quot. in Ar. <span dir=\"rtl\">דרוגין</span>. <span class=\"citation\">Num. R. s. 4</span> <span dir=\"rtl\">שיהיו עושין דר׳ לפניו</span> that they should form a hierarchy of officers before him. Y. Keth. XII, 35ᵃ bot. <span dir=\"rtl\">חמא דורגין דידיה וכ׳</span>; <span class=\"citation\">Koh. R. to IX, 10</span> <span dir=\"rtl\">דרגין</span> (corr. acc.) he saw his (R. Ḥiya’s) suite in the future world, and his eyes became dim.</div>","alt":["דַּרְגּוֹן"]},"6646":{"h":"דּוּרְדָּא","r":"D00357","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. <i>durd</i>, cmp., however, <a href=\"#\" data-headword=\"דרד\">דרד</a>) <i>sediment, lees, dregs</i>. <span class=\"citation\">Ab. Zar. 32ᵃ</span>.—Pl. <a href=\"#\" data-headword=\"דּוּרְדָּיָא\">דּוּרְדַּיָּא</a>, <a href=\"#\" data-headword=\"דּוּרְדֵּס\">דּוּרְדֵּי</a> (used as sing.). <span class=\"citation\">Targ. Ps. LXXV, 9</span>—<span class=\"citation\">Meg. 12ᵇ</span> like wine resting <span dir=\"rtl\">על דּוּרְדַּיֵּיה</span> upon its lees (<span class=\"citation\">Jer. XLVIII, 11</span>). <span class=\"citation\">Ab. Zar. 34ᵃ</span>; a. e.</div>","alt":[]},"6647":{"h":"דּוֹרְדַּנְיָא","r":"D00358","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּרְדַּנְיָא\">דַּרְדּנְיָיא</a></div>","alt":[]},"6648":{"h":"דּוּרְדֵּס","r":"D00359","html":"<div class=\"sense\">, v. <span dir=\"rtl\">דַּרְדֵּס</span></div>","alt":[]},"6649":{"h":"דּוּרְדָּיָא","r":"D00360","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Durdaya</i>. <span class=\"citation\">Ab. Zar. 17ᵃ</span> El. ben D. (Var. <span dir=\"rtl\">דרודיא</span>).</div>","alt":[]},"6650":{"h":"דּוּרָה","r":"D00361","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*דּוּרָא IV\"><span dir=\"rtl\">דּוּרָא</span> I</a>, II.</div>","alt":[]},"6651":{"h":"דּוֹרוֹן I","r":"D00362","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\">, <span dir=\"rtl\">כרם ד׳</span> <i>the vineyard of Doron</i>. Y. Kil. VII, 20ᵃ bot.</div>","alt":[]},"6652":{"h":"דּוֹרוֹן II","r":"D00363","html":"<div class=\"sense\">, ch. form <span dir=\"rtl\">דּוֹרוֹנָא</span> m. (δῶρον) <i>present, honorary gift</i>. <span class=\"citation\">Targ. Ps. CXLI, 2</span>. <span class=\"citation\">Ib. XL, 7</span>; a. e.—<span class=\"citation\">Zeb. 7ᵇ</span> <span dir=\"rtl\">עולה ד׳ הוא</span> the burnt offering is a votive gift (not a means of atonement). <span class=\"citation\">Pes. 118ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">דּוֹרוֹנִין</span>. <span class=\"citation\">Targ. Y. Ex. XII, 46</span>; a. e.—<span dir=\"rtl\">דּוֹרוֹנוֹת</span>. <span class=\"citation\">Gen. R. s. 79</span>. (<span class=\"citation\">Yalk. ib. 133</span> <a href=\"#\" data-headword=\"דּוֹרָיוֹת\">דּוֹרָנוֹת</a>); a. fr.—Chald. form. <span dir=\"rtl\">דּוֹרוֹנְיָתָא</span>. <span class=\"citation\">Targ. Ps. XX, 4</span> ed. Lag. (Ms. a. some ed. <span dir=\"rtl\">דוכר׳</span> incorr.). <span class=\"citation\">Cant. R. to VIII, 11</span> <span dir=\"rtl\">דורוניות</span>, v. <a href=\"#\" data-headword=\"דּוֹרְיָא\">next w.</a></div>","alt":[]},"6653":{"h":"דּוֹרְיָא","r":"D00364","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (δωρεά) <a href=\"#\" data-headword=\"דּוֹרוֹן II\">same</a>. . <span class=\"citation\">Gen. R. s. 85</span>, end, the one sent (to Babylon) dates, and the other (to Palestine) <a href=\"#\" data-headword=\"דּוֹרָיוֹת\">דוריות</a> gifts of honor (purple cloak, ref. to <span class=\"citation\">Josh. VII, 21</span>); <span class=\"citation\">Cant. R. to VIII, 11</span> <span dir=\"rtl\">דורוניות</span> (corr. acc. or <span dir=\"rtl\">דּוֹרוֹנוֹת</span>).—<span class=\"citation\">Ex. R. s. 5</span> <span dir=\"rtl\">דוראות של עטרות</span> gifts consisting of crowns.</div>","alt":[]},"6654":{"h":"דּוֹרִיָּה","r":"D00365","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּוּר I\">דור</a>, <span dir=\"rtl\">דרר</span>, v. <a href=\"#\" data-headword=\"דְּרוֹר\">דְּרוֹר</a>) <i>freedom, remission of tribute </i>or<i> fine, pardon</i>. <span class=\"citation\">Gen. R. s. 53</span> (play on <span dir=\"rtl\">י̇צ̇ח̇ק̇</span>) [read:] <span dir=\"rtl\">י̇צ̇א ח̇וק̇ לעולם ליתן דו׳ לעולם</span> a law was issued to give a grant (remission of sin) &amp;c.; <span class=\"citation\">Yalk. ib. 92</span> <span dir=\"rtl\">יצא חוק דרור׳ וכ׳</span>. Gen. R. l. c. [read:] <span dir=\"rtl\">מה עשייה … ליתן ד׳ לעולם אף עשייה … ליתן ד׳ לעולם</span> as the verb <span dir=\"rtl\">עשה</span> used there (<span class=\"citation\">Esth. II, 18</span>) means to grant a remission to the world, so does the verb <span dir=\"rtl\">עשה</span> (<span class=\"citation\">Gen. XXI, 8</span>) etc.; Pesik. Sos, p. 146ᵃ <a href=\"#\" data-headword=\"דורניא\">דורניא</a> (corr. acc.); <span class=\"citation\">Yalk. Gen. 93</span> <span dir=\"rtl\">דרור׳</span>.—Y’lamd. to Lev. XXI, 10, quot. in Ar. <span dir=\"rtl\">ד׳ שלימה</span> full pardon.</div>","alt":["דּוֹרִיָּיה","דְּרוֹרִיָּה"]},"6655":{"h":"דּוֹרָיוֹת","r":"D00366","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹרְיָא\">דּוֹרְיָא</a></div>","alt":[]},"6656":{"h":"דּוֹרִיָּיה","r":"D00367","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹרִיָּה\">דּוֹרִיָּה</a></div>","alt":[]},"6657":{"h":"דּוֹרְכָא","r":"D00368","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דרך</span>) <i>threshing</i>. <span class=\"citation\">Targ. Y. II, Deut. XXV, 4</span> <span dir=\"rtl\">דּוֹרְכֵיה</span> (Y. I <span dir=\"rtl\">דָּרְכֵיה</span>, h. text <a href=\"#\" data-headword=\"דַּיִשׁ\">דיש</a>).</div>","alt":[]},"6658":{"h":"דּוֹרְכָאוֹת","r":"D00369","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דּוֹרְכָא\">preced.</a>) <i>pomace</i>. <span class=\"citation\">Tosef. Maas. Sh. I, 10</span> <span dir=\"rtl\">ד׳ של תמרה</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"ריתכאות\">ריתכאות</a>).</div>","alt":[]},"6659":{"h":"דוֹרְכָאוֹת","r":"D00370","html":"<div class=\"sense\"><i>reliefs</i>, v. <a href=\"#\" data-headword=\"דִּידְכֵי\">דִּידְכֵי</a>.</div>","alt":["דּוֹרְכִיאוֹת","דוֹרְכִיּוֹת"]},"6660":{"h":"דוּרְמוֹס","r":"D00371","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a disguise of Ἕρμης, or Mercurius, the divinity of commerce to whom a great annual fair, prob. of Tyre, was dedicated, v. Y. Ab. Zar. I, 39ᵈ top, quot. s. v. <a href=\"#\" data-headword=\"ארקליס\">ארקליס</a>) <i>Durmos</i>, name of <i>a great annual fair</i>. <span class=\"citation\">B. Mets. 72ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"אסרטיון\">אסרטיון</a>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"6661":{"h":"דורמוסקית","r":"D00372","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּרְמַסְקִית\">דּוּרְמַסְקִית</a></div>","alt":[]},"6662":{"h":"דורמילוס","r":"D00373","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דרומילוס\">דרומילוס</a></div>","alt":["דורמלוס","דורמליס"]},"6663":{"h":"דורמסיאות","r":"D00374","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אנדרולומוסיא\">אנדרולומוסיא</a></div>","alt":["דורמסיות","דורמייס׳"]},"6664":{"h":"דורמסקין","r":"D00375","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּרְמַסְקִינָא\">דַּרְמַסְקִינָא</a></div>","alt":[]},"6665":{"h":"דּוּרְמַסְקִית","r":"D00376","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>Durmaskith (of Damascus)</i>. <span class=\"citation\">Sifré Deut. 1</span> R. José ben D.; <span class=\"citation\">Ḥag. 3ᵇ</span>; <span class=\"citation\">Tosef. Yad. II, 16</span> <span dir=\"rtl\">דורמוס׳</span>; <span class=\"citation\">Tosef. Sot. III, 9</span>; a. fr.—Mekh. Yithro, Baḥod. 1 Abba José b. D.—[Tanḥ. Noah 1 <a href=\"#\" data-headword=\"דוסמקא\">דוסמקא</a>, <a href=\"#\" data-headword=\"דוסמקא\">דוסקמא</a> (corr. acc.), Var. <a href=\"#\" data-headword=\"קַצְרַת\">קצרתא</a>, v. Tanḥ. ed. Bub. ib.] [Pl. <a href=\"#\" data-headword=\"דּוּרְמַסְקִית\">דּוּרְמַסְקִיּוֹת</a>, v. <a href=\"#\" data-headword=\"דַּרְמַסְקִינָא\">דַּרְמַסְקִינָא</a>.]</div>","alt":[]},"6666":{"h":"דורמסקנא","r":"D00377","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּרְמַסְקִינָא\">דַּרְמַסְקִינָא</a></div>","alt":["דורמסקניות","דורמסקנין"]},"6667":{"h":"דורניא","r":"D00378","html":"<div class=\"sense\">, Pesik. Sos p. 146ᵃ, v. <a href=\"#\" data-headword=\"דּוֹרִיָּה\">דּוֹרִיָּה</a></div>","alt":[]},"6668":{"h":"דורניאות","r":"D00379","html":"<div class=\"sense\">, <span class=\"citation\">Esth. R. to I, 1</span>, read <span dir=\"rtl\">דּוֹרוֹנִיּוֹת</span>, v. <a href=\"#\" data-headword=\"דִּידְכֵי\">דִּידְכֵי</a></div>","alt":[]},"6669":{"h":"דורסות","r":"D00380","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Maas. Sh. I, 10</span> Var., v. <a href=\"#\" data-headword=\"דְּרוּסוֹת\">דְּרוּסוֹת</a></div>","alt":[]},"6670":{"h":"דורסים","r":"D00381","html":"<div class=\"sense\">, <span class=\"citation\">Y. Kidd. I, 58ᵈ</span>, v. <a href=\"#\" data-headword=\"דָּרוֹסָה\">דָּרוֹסָה</a></div>","alt":[]},"6671":{"h":"דּוֹרְסָן","r":"D00382","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דרס</span>) <i>place where hides are trodden or fulled</i> before tanning. <span class=\"citation\">Bets. I, 5</span> (<span class=\"citation\">11ᵃ</span>) you must not place the hide <span dir=\"rtl\">לפני הד׳</span> in front of the <i>dor’san</i> (Mish. Nap. a. oth. <span dir=\"rtl\">בית הדריסה</span>, Y. ed. <span dir=\"rtl\">לפני הדריסה</span>).</div>","alt":[]},"6672":{"h":"דּוּרְצִינִי","r":"D00383","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּרְצִינִי\">דַּרְצִינִי</a></div>","alt":[]},"6673":{"h":"דּוֹרְקְטִי","r":"D00384","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (a perversion of τρωκτή, sub. σταφυλή, v. infra) <i>grape used for dessert</i>, fit for eating but yielding no wine, fig. <i>a woman who has no menstruation</i>. <span class=\"citation\">Nidd. IX, 11</span>. <span class=\"citation\">Ib. 64ᵇ</span>; <span class=\"citation\">Keth. 10ᵇ</span> (phonetic etymology) <span dir=\"rtl\">דור קטוע</span> [hence the perversion] a cut-off race (bound to die out). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">משפחת ד׳</span> a family the women of which have neither menstruation nor symptoms of injured virginity. Y. ib. I, 25ᵃ bot. quoting Mish. Nidd. l. c. <a href=\"#\" data-headword=\"טְרוֹקְטִי\">טְרוֹקְטִי</a>.</div>","alt":[]},"6674":{"h":"דורקין","r":"D00385","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. III, 14</span> Var., v. <a href=\"#\" data-headword=\"דּוֹקְרָן\">דּוֹקְרָן</a></div>","alt":["דורקן"]},"6675":{"h":"דּוֹרֵשׁ","r":"D00386","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>lecturer</i>, v. <a href=\"#\" data-headword=\"דָּרַשׁ\">דָּרַשׁ</a>.</div>","alt":[]},"6676":{"h":"דּוּרְשִׁינֵּי","r":"D00387","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (comp. of <a href=\"#\" data-headword=\"דּוּר\">דּוּר</a> a. <span dir=\"rtl\">שיני</span>, pl. of <a href=\"#\" data-headword=\"שִׁינּ־\">שִׁינָּא</a>) [<i>row of teeth</i>,] <i>gum</i>. <span class=\"citation\">Sabb. 65ᵃ</span> <span dir=\"rtl\">לד׳</span> (some ed. <span dir=\"rtl\">לדורשו׳</span>, incorr.; Ms. M. <span dir=\"rtl\">דורשני</span>, Var. a. Ar. in two words, v. Rabb. D. S. a. l. note) a remedy for the gum. Cmp. <a href=\"#\" data-headword=\"דְּרָרָא I\"><span dir=\"rtl\">דְּרָרָא</span> I</a>.</div>","alt":[]},"6677":{"h":"דּוּרְתָּא","r":"D00388","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּרְתָּא\">דַּרְתָּא</a></div>","alt":[]},"6678":{"h":"דּוּשׁ","r":"D00389","html":"<div class=\"sense\"> (b. h.), part. a. perf. <a href=\"#\" data-headword=\"דָּשׁ\">דָּשׁ</a> </div><div class=\"sense\"><b>1)</b> <i>to tread, trample, thresh</i>. <span class=\"citation\">Sabb. VII, 2</span> <span dir=\"rtl\">הדָּשׁ</span> he who threshes (on the Sabbath); a. fr.—Euphem. for sexual contact. <span class=\"citation\">Nidd. 41ᵇ</span>. <span class=\"citation\">Gen. R. s. 85</span>. <span class=\"citation\">Pes. 87ᵇ</span>; a. e.—<span dir=\"rtl\">דוש בעקב</span> to trample with one’s heel, <i>to treat lightly, not to heed</i>. <span class=\"citation\">Ab. Zar. 18ᵃ</span>. <span class=\"citation\">Lev. R. s. 27</span>.</div><div class=\"sense\"><b>—2)</b> <i>to walk about, be familiar, well-known</i>. <span class=\"citation\">Meg. 24ᵇ</span> <span dir=\"rtl\">אם היה דש בעירו</span> if he has been a familiar figure in his town (so that people do not mind his bodily disfigurement); <span class=\"citation\">Y. Taan. IV, beg. 67ᵇ</span>; a. fr.</div><div class=\"sense\"><b>Pi. דִּיֵּישׁ</b> <div class=\"sense\"><i>to trample</i>. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">הייתם מְדַיְּישִׁין את העץ וכ׳</span> you used to tread upon this piece of wood. <span class=\"citation\">Midr. Till. to Ps. VIII, 3</span> <span dir=\"rtl\">מְדַיֵּישׁ עליך כעפר</span> even one who treads upon thee as upon dust. <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">דַּיְּישֵׁם</span> tread upon them.</div></div><div class=\"sense\"><b>Polel. דּוֹשֵׁש</b> <div class=\"sense\">, v. <a href=\"#\" data-headword=\"דָּשַׁשׁ\">דָּשַׁשׁ</a></div></div>","alt":[]},"6679":{"h":"דּוּשׁ ²","r":"D00390","html":"<div class=\"sense\"><b>1)</b> <i>to thresh</i>. <span class=\"citation\">Targ. Ruth II, 17</span>.—<span class=\"citation\">Zeb. 116ᵇ</span>; <span class=\"citation\">Men. 22ᵃ</span>, v. <a href=\"#\" data-headword=\"דִּשְׁתָּאָה\">דַּשְׁתָּאָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>to tread upon, trample</i> (to death). <span class=\"citation\">Targ. II Kings VII, 17</span>; a. fr.—<span class=\"citation\">B. Kam. 9ᵃ</span> <span dir=\"rtl\">דָּיֵישׁ אמצרי</span> he sets his foot upon the landmark (symbol of possession).</div><div class=\"sense\"><b>—3)</b> <i>to be used to, not to mind</i>. <span class=\"citation\">Sabb. 129ᵇ</span> <span dir=\"rtl\">כיון דדָשוּ ביה רבים</span> since the people are in the habit of doing it. <span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">כיון דדש דש</span> being used (to the hammering) the gnat did not heed it. <span class=\"citation\">Keth. 62ᵃ</span> <span dir=\"rtl\">דַּשְׁנָן בה</span> we are used to it.—<span class=\"citation\">Targ. Prov. VIII, 33</span> <span dir=\"rtl\">תְדִישׁוּן</span>, v. Af.</div><div class=\"sense\"><b>Af. אָדֵישׁ  אָדֵשׁ</b> <div class=\"sense\"><i>to pass over, to leave unheeded, to be listless</i>. <span class=\"citation\">Targ. Prov. IV, 15</span>; <span class=\"citation\">XIII, 18</span>; <span class=\"citation\">XV, 32</span> Ar. a. Mss. (ed. Lag. <a href=\"#\" data-headword=\"אָרָמוּתָא\">אר׳</a>, <span dir=\"rtl\">מר׳</span> with <a href=\"#\" data-headword=\"ר\">ר</a>, h. text <a href=\"#\" data-headword=\"פְּרַע I\">פרע</a>); ib. VIII, 33 (v. supra, ed. Lag. <span dir=\"rtl\">תירשון</span>).—<span class=\"citation\">Snh. 7ᵃ</span> (prov.) <span dir=\"rtl\">טוביה לדשמע ואדיש</span> (Ms. M. <span dir=\"rtl\">ואריש</span>) happy he who hears (himself abused) and minds it not; he will escape a hundred evils.—Y. Peah I, 15ᶜ bot.; Y. Kidd. I, 61ᵇ <span dir=\"rtl\">אכול ואֲדֵישׁ … ומַדְשִׁין</span> eat and care not (do not share in our conversation), for so do dogs eat and mind not. [<span class=\"citation\">Targ. Y. II, Num. XI, 8</span> <span dir=\"rtl\">אדשין</span>, v. <a href=\"#\" data-headword=\"דְּשַׁשׁ\">דְּשַׁשׁ</a>.] </div></div><div class=\"sense\"><b>Ithpe. אִתְדַּשׁ  אִידַּשׁ</b> <div class=\"sense\"><i>to be trampled upon, threshed</i>. <span class=\"citation\">Targ. Is. XXIV, 3</span>. <span class=\"citation\">Ib. XXV, 10</span>.—[<span class=\"citation\">Targ. Jer. XLVIII, 26</span>, v. <a href=\"#\" data-headword=\"דְּשַׁשׁ\">דְּשַׁשׁ</a>.]</div></div><div class=\"sense\"><b>Polel. דּוֹשֵׁשׁ</b> <div class=\"sense\"><i>Palp.</i> <a href=\"#\" data-headword=\"דַּשְׁדֵּשׁ\">דַּשְׁדֵּשׁ</a>, v. <a href=\"#\" data-headword=\"דְּשַׁשׁ\">דְּשַׁשׁ</a>.</div></div>","alt":[]},"6680":{"h":"דַּוְשָׁא","r":"D00391","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּוְושָׁא\">דַּוְושָׁא</a></div>","alt":[]},"6681":{"h":"דּוֹשֶׁן","r":"D00392","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דשן</span>) <i>fat pasture ground</i>. <span class=\"citation\">Sifré Num. 81</span>; Deut. 62 <span dir=\"rtl\">דּוֹשְנָהּ של יריחו</span> (cmp. <a href=\"#\" data-headword=\"דֶּשֶׁן\">דֶּשֶׁן</a> <span class=\"citation\">Jer. XXXI, 39</span>).</div>","alt":[]},"6682":{"h":"דּוּת","r":"D00393","html":"<div class=\"sense\"> f. (sub. <span dir=\"rtl\">בית</span>) m. <i>a subterranean masoned store-room, cistern, cellar</i>. [Syr. <span dir=\"rtl\">חדותא</span> <i>grex, horreum</i>, P. Sm. 1200.] [In Mishnah Seder Tohăroth <span dir=\"rtl\">חדות</span>, v. R. S. to Ohol. XI, 8.] <span class=\"citation\">B. Bath. IV, 2</span> he who sells a house, has not sold with it <span dir=\"rtl\">לא את הבור ולא את הר׳</span> either the pit or the <i>duth</i>. <span class=\"citation\">Ib. 64ᵃ</span> אחד הבור ואחד הד׳ וכ׳ <i>bor</i> and <i>duth</i> are subterranean, <span dir=\"rtl\">בור בחפירה ד׳ בבנין</span> a <i>bor</i> is made by digging, a <i>duth</i> by masonry. Tosef. Erub. XI (VIII), 18; <span class=\"citation\">Tosef. Pes. I, 3</span> <span dir=\"rtl\">היציע והד׳</span>; Y. ib. I, 27ᵇ top <span dir=\"rtl\">והחד׳</span>. Ib. <span dir=\"rtl\">בח׳ שיש לה וכ׳</span> treating of a <i>ḥadduth</i> which has a lid. <span class=\"citation\">R. Hash. III, 7</span>.—<span class=\"citation\">Y. Ab. Zar. II, 40ᶜ</span> bot. <span dir=\"rtl\">עולה … לחרות</span> (corr. acc.) when going up with him to the upper story or down to the cellar &amp;c. <span class=\"citation\">Kel. V, 6</span> ed. Derenb. <span dir=\"rtl\">הח׳</span>. Ohol. XI, 8 <span dir=\"rtl\">הח׳</span>; Tosef. ib. XII, 4 <span dir=\"rtl\">הד׳</span>; a. fr.—Pl. <span dir=\"rtl\">דּוּתִיּוֹת</span>. <span class=\"citation\">Tosef. B. Bath. III, 1</span> (Var. <span dir=\"rtl\">דּוּתוֹת</span>, Mish. <span class=\"citation\">ib. IV, 2</span> sing.).—<span dir=\"rtl\">חַדּוּתִין</span>. Y. ib. IV, 14ᶜ bot. <span dir=\"rtl\">חרותין</span> ed. Krot. (corr. acc.). [Our w. seems to be originally <span dir=\"rtl\">חדות</span>, fr. <span dir=\"rtl\">יחד</span>. As to rejection of <a href=\"#\" data-headword=\"ח\">ח</a> cmp. <a href=\"#\" data-headword=\"חַלְבֵּצִין\">חַלְבֵּצִין</a>.]</div>","alt":["חַדּוּת"]},"6683":{"h":"דָּוְתָא","r":"D00394","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דָּוְותָא\">דָּוְותָא</a></div>","alt":["דְּוָתָא"]},"6684":{"h":"דָּחָא","r":"D00395","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דחי\">דחי</a></div>","alt":["דְּחָא"]},"6685":{"h":"*דְּחַד","r":"D00396","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"*דְּחַד\">דַּחֵד</a> (= <span dir=\"rtl\">חדחד</span>) <i>to set apart of each kind</i>. <span class=\"citation\">Targ. Y. I Deut. XV, 14</span> (O. <span dir=\"rtl\">פרש</span>, h. text <a href=\"#\" data-headword=\"עֲנָק I\">ענק</a> Hif.) <span dir=\"rtl\">מְדַחֲדָא תְדַחֲדוּן ליה</span> (ed. Amst. <span dir=\"rtl\">מדחר׳ תדחר׳</span>, corr. acc.).</div>","alt":[]},"6686":{"h":"דָּחָה","r":"D00397","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דחי\">דחי</a></div>","alt":[]},"6687":{"h":"דְּחַהּ","r":"D00398","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"זָהַהּ\">זָהַהּ</a>) <i>to be merry, wanton</i>.—Denom.:</div>","alt":["דְּחַח"]},"6688":{"h":"*דַּחֲוָא","r":"D00399","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>jester, dancer</i>.—Pl. <a href=\"#\" data-headword=\"*דַּחֲוָא\">דַּחֲוָן</a>. <span class=\"citation\">Dan. VI, 19</span> (cmp. <a href=\"#\" data-headword=\"דַּחְיָיא\">דַּחְיָיא</a>; oth. opin. = <a href=\"#\" data-headword=\"*דַּחֲוָונוֹת\">next w.</a>).</div>","alt":[]},"6689":{"h":"*דַּחֲוָונוֹת","r":"D00400","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*דַּחֲוָא\">preced.</a>) <i>boards used at weddings as tables</i>. <span class=\"citation\">Tosef. Kel. B. Mets. V, 3</span> kimḥi (ed. Zuck. <span dir=\"rtl\">רחזינית</span>, Var. <span dir=\"rtl\">רחזוינות</span>).</div>","alt":[]},"6690":{"h":"דָּחוֹחָא","r":"D00401","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">דְּחוֹחֵי</span> (<a href=\"#\" data-headword=\"דְּחַהּ\">דחח</a>, v. <a href=\"#\" data-headword=\"דְּחַהּ\">דְּחַהּ</a>) <i>wantonness</i>. <span class=\"citation\">Targ. Ps. LXII, 9</span> ed. Lag., v. <a href=\"#\" data-headword=\"זָהוֹהָא\">זְחוֹחָא</a>.</div>","alt":[]},"6691":{"h":"דָּחוּי","r":"D00402","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דחי\">דחי</a></div>","alt":[]},"6692":{"h":"דִּחוּי","r":"D00403","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיחוּי\">דִּיחוּי</a></div>","alt":[]},"6693":{"h":"דְּחוּכָא","r":"D00404","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּחֵיךְ\">דְּחֵיךְ</a>) <i>feast, wedding entertainment</i>. <span class=\"citation\">Koh. R. to II, 2</span> [read:] <span dir=\"rtl\">דדְחוֹכֵיה מערבבא וכ׳</span> he whose feast is disturbed,—what has rejoicing to do with him?; Pesik. Aḥaré p. 169ᵇ <span dir=\"rtl\">הן דרחבה מעורבב</span> (read <span dir=\"rtl\">הָן דדְחוֹכֵיה</span>); <span class=\"citation\">Lev. R. s. 20</span>.</div>","alt":[]},"6694":{"h":"דְּחוֹק","r":"D00405","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּחַק I\">דחק</a>) </div><div class=\"sense\"><b>1)</b> <i>oppression</i>. <span class=\"citation\">Targ. Ex. VI, 6</span>. <span class=\"citation\">Targ. Ps. XLIII, 2</span>.</div><div class=\"sense\"><b>—2)</b> <i>need, stint</i>. <span class=\"citation\">Targ. II Chr. XVIII, 26</span>; <span class=\"citation\">I Kings XXII, 27</span>.</div>","alt":[]},"6695":{"h":"דחי","r":"D00406","html":"<div class=\"sense\"><b>1)</b> <i>to push away, thrust</i>. <span class=\"citation\">Tosef. Yoma IV (III), 14</span> <span dir=\"rtl\">דְּחָאוֹ ולא מת</span>; Y. ib. VI, 43ᵃ bot. <span dir=\"rtl\">דְּחָייוֹ</span> if the man thrust the goat down the precipice, and it did not die. <span class=\"citation\">Snh. 107ᵇ</span>, a. e. <span dir=\"rtl\">תהא שמאל דּוֹחָה וכ׳</span> let the left hand repel them and the right invite; a. fr.—Transf. <span dir=\"rtl\">ד׳ בקש</span>, or <span dir=\"rtl\">בקנה</span> <i>to dismiss with a vague or paltry reply</i>. <span class=\"citation\">Ḥull. 27ᵇ</span>. Tanḥ. Ḥuck. 8; <span class=\"citation\">Num. R. s. 19</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to expel</i>. <span class=\"citation\">Tosef. Dem. III, 4</span>; <span class=\"citation\">Bekh. 31ᵃ</span>; <span class=\"citation\">Y. Dem. II, 23ᵃ</span> top, v. <a href=\"#\" data-headword=\"חֲבֵרוּת\">חֲבֵירוּת</a>.</div><div class=\"sense\"><b>—3)</b> <i>to suspend, make inoperative, supersede.</i> Ohol. VII, 6 <span dir=\"rtl\">אין דּוֹחִין נפש מפני וכ׳</span> we dare not set aside the regard due to one human life for the sake of saving another human life; <span class=\"citation\">Gen. R. s. 94</span> <span dir=\"rtl\">כך עושין דוחים וכ׳</span> is it thus one must act? dare you sacrifice one life &amp;c.?—<span class=\"citation\">Y. Snh. VIII, 26ᶜ</span> top <span dir=\"rtl\">ד׳ את הספק</span> to disregard the doubt the benefit of which is to be given to the criminal.—<span class=\"citation\">Y. Shek. IV, 47ᵈ</span> bot. <span dir=\"rtl\">דָּחִינוּ אותו וכ׳</span> we postponed it (the fast) to the first day of the week; <span class=\"citation\">Meg. 5ᵇ</span> <span dir=\"rtl\">דְחִינוּהוּ</span>; <span class=\"citation\">Erub. 41ᵃ</span> <span dir=\"rtl\">דְחִינֻהוּ</span>.—<span class=\"citation\">Pes. VI, 1</span> <span dir=\"rtl\">אלו דברים … דוחין וכ׳</span> the following performances needed for the Passover offering take precedence of the Sabbath (cause a suspension of the Sabbath laws); a. v. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"דָּחוּי\">דָּחוּי</a> a) <i>pushed, hurried</i>. <span class=\"citation\">M. Kat. 28ᵃ</span> <span dir=\"rtl\">מיתה דְחוּיָה</span> a hurried death.—b) <i>suspended, superseded</i>. <span class=\"citation\">Yoma 7ᵇ</span>, a. fr. <span dir=\"rtl\">טומאה דְּחוּיָה היא וכ׳</span> the law about levitical purity is only suspended for the sake of an entire community (and its suspension requires atonement), opp. <span dir=\"rtl\">טומאה הותרה</span> the law &amp;c. is inoperative. <span class=\"citation\">Zeb. 12ᵃ</span> <span dir=\"rtl\">ד׳ מעיקרו</span> unfit from the start, opp. <span dir=\"rtl\">נראה ונדחה</span>, v. infra.—[<span class=\"citation\">Yeb. 80ᵇ</span>; <span class=\"citation\">Gitt. 57ᵃ</span> <a href=\"#\" data-headword=\"דּוּחָה\">דוחה</a>, v. <a href=\"#\" data-headword=\"דִּיהַּ\">דִּיהַּ</a>.]</div><div class=\"sense\"><b>Nif. נִדְחֶה</b> <div class=\"sense\"><i>to be pushed aside, suspended; to give way</i>. <span class=\"citation\">Meg. 5ᵇ</span> <span dir=\"rtl\">הואיל ונ׳ יִדָּחֶה</span> the fast being once suspended (on account of the Sabbath), let it remain so (and not be taken up on Sunday). <span class=\"citation\">Pes. 66ᵇ</span> <span dir=\"rtl\">איש נ׳ … ואין צבור נִידָּחִין</span> an individual (if unclean on Passover) is suspended (postpones the celebration) until the second Passover (<span class=\"citation\">Num. IX, 10</span> sq.), but not a community. <span class=\"citation\">Yoma 64ᵃ</span> <span dir=\"rtl\">בעלי חיים אינן נידחין</span> animals (dedicated for sacrifices) cannot be removed forever from sacred use (as long as the obstacle lies not in their physical unfitness). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נראה ונ׳</span> once fit and then discarded (on account of a temporary unfitness).—<span class=\"citation\">Ber. 64ᵃ</span> <span dir=\"rtl\">כל הנ׳ … שעה נִדֶּחֶת מפניו</span> to him who gives way to time (yielding patiently to circumstances), time will give way, v. <a href=\"#\" data-headword=\"דָּחַק\">דָּחַק</a>.</div></div><div class=\"sense\"><b>Hif. הִדְחָה</b> <div class=\"sense\"><b>1)</b> <i>to remove hurriedly</i>. <span class=\"citation\">M. Kat. 22ᵃ</span> <span dir=\"rtl\">מדְחֶה מיטתו</span> he who is anxious to remove the bier of a relative (hurries the burial).</div><div class=\"sense\"><b>—2)</b> <i>to thrust</i>. <span class=\"citation\">Arakh. 30ᵇ</span> אַדְחֶה אבן אחר וכ׳ Rashi (ed. <span dir=\"rtl\">אידחה</span>, corrupt. of <span dir=\"rtl\">אֲיַדֶּה</span>; Ar. <span dir=\"rtl\">דְּחֵה</span> imperat. Kal) I will throw a stone after the fallen man (not give the sinner a chance to return). [<span class=\"citation\">Naz. 16ᵇ</span> מדחין בה Ar., read with ed. <span dir=\"rtl\">כדהוינן בה</span>.] [<span class=\"citation\">Tosef. Toh. VIII, 8</span> <span dir=\"rtl\">המדחה</span>, v. <a href=\"#\" data-headword=\"יָחַס\">יָּחַס</a>.]</div></div>","alt":["דָּחָא","דָּחָה"]},"6696":{"h":"דְּחִי","r":"D00407","html":"<div class=\"sense\"><b>1)</b> <i>to thrust, push, knock down</i>. <span class=\"citation\">Targ. O. Num. XXXV, 20</span> <span dir=\"rtl\">דְּחָהִי</span> he knocked him down (h. text <span dir=\"rtl\">הדף</span>; Y. <a href=\"#\" data-headword=\"דְּחִיָּה\">דַּחְיֵיה</a>). <span class=\"citation\">Targ. Ps. CXVIII, 13</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to suspend, supersede</i> &amp;c., v. <a href=\"#\" data-headword=\"דחי\">preced.</a> 3). <span class=\"citation\">Zeb. 12ᵇ</span> <span dir=\"rtl\">הוא ד׳ נפשיה בידים</span> he debarred himself from offering (on account of his apostasy). <span class=\"citation\">Pes. 69ᵇ</span> אימא לִידְחֵי I might think they take precedence of the Sabbath. <span class=\"citation\">Ber. 23ᵃ</span> <span dir=\"rtl\">גברא דְחוּיָא הוא</span> the person was for the time in an unfit condition to pray (and his prayer does not count at all).</div><div class=\"sense\"><b>Af. אַדְחֵי</b> <div class=\"sense\">, <i>Pa</i>. <span dir=\"rtl\">דַּחֵי</span> <i>to push aside, drive off</i>. <span class=\"citation\">Pes. 57ᵃ</span> <span dir=\"rtl\">דַּחוּיֵי קא מַדְחֵי לן</span> he sends us off (with a vain promise).</div></div><div class=\"sense\"><b>Ithpa. אִידָּחֵי</b> </div><div class=\"sense\"><b>Ithpe. אִידְּחֵי</b> <div class=\"sense\"><b>1)</b> <i>to be thrust down</i>. <span class=\"citation\">Targ. Ps. XXXVI, 13</span> אִידָּחֲיַין Ms. (ed. <span dir=\"rtl\">יִדְחֲיַן</span>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be superseded, postponed</i> &amp;c. (v. <a href=\"#\" data-headword=\"דחי\">preced.</a> Nif.). <span class=\"citation\">Targ. Y. Num. IX, 10</span>.—<span class=\"citation\">Zeb. 12ᵇ</span> <span dir=\"rtl\">ממילא אי׳</span> he was debarred from offering through no fault of his. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">גברא אי׳</span> the person was unfit; a. fr.</div></div>","alt":["דְּחָא"]},"6697":{"h":"דְּחִיָּה","r":"D00408","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּחִי\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>thrusting, knocking down</i>. <span class=\"citation\">Snh. 45ᵃ</span> (ref. to <span dir=\"rtl\">דוחפו</span>, Mish. <span class=\"citation\">ib. VI, 4</span>) <span dir=\"rtl\">מניין שבד׳</span> whence do we derive the law that he must be knocked down?; Y. ib. VI, 23ᶜ top <span dir=\"rtl\">מניין שטעון ד׳</span>.—Pl. <span dir=\"rtl\">דְּחִיּיוֹת</span>, <span dir=\"rtl\">דְּחִיּוֹת</span>. Ib.</div><div class=\"sense\"><b>—2)</b> <i>postponement, suspension</i>. <span class=\"citation\">Y. Sabb. XIX, beg. 16ᵈ</span> <span dir=\"rtl\">עיקר דְּחִיָּיתָן וכ׳</span> what they chiefly supersede is the Sabbath and that which is required for their execution is labor (otherwise forbidden).—[<span dir=\"rtl\">דְּחִיּוֹת</span> in later Hebr. literature: <i>the reasons for shifting the first day of Tishri</i> in the Jewish calendar.]</div>","alt":["דְּחִיָּיה"]},"6698":{"h":"דַּחְיָיא","r":"D00409","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*דַּחֲוָא\">דַּחֲוָא</a>) <i>feaster, reveller.</i> <i>—</i> Pl. <span dir=\"rtl\">דַּחְיִין</span>. <span class=\"citation\">Lev. R. s. 33</span>, v. <a href=\"#\" data-headword=\"*דִּיאוֹנִיסִין\">דִּיאוֹנִיסִין</a>.—Fem. <span dir=\"rtl\">דַּחְיְיתָא</span>. Lam. R. introd. (R. Joḥan. I) <span dir=\"rtl\">קרתא ד׳</span> (translation of <span dir=\"rtl\">קריה עליזה</span> <span class=\"citation\">Is. XXII, 2</span>; Targ. <a href=\"#\" data-headword=\"חֲדָאָה\">חדאה</a>).</div>","alt":[]},"6699":{"h":"דְּחֵיךְ","r":"D00410","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"דְּחַהּ\">דְּחַהּ</a>) <i>to laugh; to deride</i>. <span class=\"citation\">Targ. Job XI, 3</span>; <span class=\"citation\">Targ. Ps. II, 4</span>, v. <a href=\"#\" data-headword=\"דְּהֵיךְ\">דְּהֵיךְ</a>. <span class=\"citation\">Targ. Ps. XXII, 8</span> (ed. Lag. <span dir=\"rtl\">רהב</span>). <span class=\"citation\">Targ. Prov. I, 26</span> (Var. <span dir=\"rtl\">דחף</span>, incorr.).—Pesik. B’shall. p. 93ᵇ <span dir=\"rtl\">דַּחֲכָא וכ׳</span> laughing and weeping (<span class=\"citation\">Koh. R. to XI, 2</span> <span dir=\"rtl\">חייכת</span>).</div><div class=\"sense\"><b>Pa. דַּחֵךְ</b> <div class=\"sense\"><i>to make sport of, to play</i>. <span class=\"citation\">Gen. R. s. 79</span> <span dir=\"rtl\">לית אנא מְדַחֵךְ בהדין וכ׳</span> (<span class=\"citation\">Koh. R. to X, 8</span> <span dir=\"rtl\">מגחך</span>) will I not make sport of that elder of the Jews?! <span class=\"citation\">Koh. R. to III, 2</span> children <span dir=\"rtl\">מְדַחֲכִין וכ׳</span> (ed. Wil. <span dir=\"rtl\">מדה׳</span>) playing in front of a dwelling.</div></div>","alt":["דְּחֵךְ","דְּחַךְ"]},"6700":{"h":"דּחֵיל","r":"D00411","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"זְחַל I\">זחל</a> a. Arab. <i>daḥala</i>) [<i>to be depressed, bent</i>,] <i>to fear, be afraid of, shun; to worship, revere</i>. <span class=\"citation\">Targ. Gen. XVIII, 15</span>. <span class=\"citation\">Targ. Ps. XXXIII, 8</span>; a. fr.—<i>Part.</i> <a href=\"#\" data-headword=\"דּחִיל\">דָּחִיל</a>, <a href=\"#\" data-headword=\"דּחֵיל\">דְּחֵיל</a>; constr. <a href=\"#\" data-headword=\"דּחִיל\">דְּחִיל</a>. <span class=\"citation\">Targ. Ex. IX, 20</span>. <span class=\"citation\">Targ. Gen. XIX, 30</span>; a. fr.—<span class=\"citation\">Sabb. 23ᵇ</span> <span dir=\"rtl\">דד׳ מרבנן</span> he who reveres the scholars. <span class=\"citation\">Y. Naz. IX, end 58ᵃ</span> (play on <span dir=\"rtl\">מורה</span> a. <a href=\"#\" data-headword=\"מוֹר ²\">מורא</a>, v. Mishn. ib. IX, 5) <span dir=\"rtl\">מה ביזרא ד׳ וכ׳</span> as the grain is afraid of the iron (scythe), so is the hair &amp;c.; a. fr.—<span class=\"citation\">Sabb. 31ᵇ</span>, a. fr. <span dir=\"rtl\">דְּחִיל חטאין</span> shunning sin.</div><div class=\"sense\"><b>Pa. דַּחַל</b> <div class=\"sense\"><i>to frighten, to cause fear</i>. <span class=\"citation\">Targ. II Sam. XIV, 15</span> <span dir=\"rtl\">דַּחֲלוּנִי</span> ed. Lag. (ed. <span dir=\"rtl\">דחלונני</span>).</div></div><div class=\"sense\"><b>Af. אַדְחֵיל</b> <div class=\"sense\"><i>to frighten, scare</i>. <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">מן הדא את מדחיל לי</span> with this (fire) wilt thou frighten me?—<span class=\"citation\">Koh. R. to VII, 1</span> (prov.) whom a snake once has bitten, <span dir=\"rtl\">חבלא מדחיל ליה</span> a rope will frighten.</div></div><div class=\"sense\"><b>Ithpe. אִידְּחִיל</b> <div class=\"sense\"><i>to be afraid</i>. <span class=\"citation\">Lev. R. s. 9</span> <span dir=\"rtl\">אִידְּחִילַת מיניה</span> she was afraid of him.</div></div>","alt":["דְּחַל"]},"6701":{"h":"דּחִיל","r":"D00412","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּחֵיל\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>fearing</i>, v. <a href=\"#\" data-headword=\"דּחֵיל\">preced.</a></div><div class=\"sense\"><b>—2)</b> <i>fearful, terrible, awe-inspiring</i>. <span class=\"citation\">Targ. Y. Gen. XXVIII, 17</span>. <span class=\"citation\">Targ. Ps. LXXVI, 5</span> דָּחִיל Ms. (ed. <span dir=\"rtl\">נהיר דחיל</span>, combin. of two versions). <span class=\"citation\">Targ. Deut. X, 17</span>. <span class=\"citation\">Ib. VIII, 15</span>; a. fr.—<span class=\"citation\">Lev. R. s. 9</span> <span dir=\"rtl\">מה ד׳ הדין שליטא</span> how severe is this ruler!—Pl. <a href=\"#\" data-headword=\"דִּקְיוֹן\">דְּחִילִין</a>, f. <a href=\"#\" data-headword=\"דְּחִילָא\">דְּחִילַן</a>. Targ. <span class=\"citation\">Hab. I, 7</span>. <span class=\"citation\">Targ. Ps. XLV, 5</span> (noun).</div>","alt":["דְּחִילָא"]},"6702":{"h":"דְּחִילָא","r":"D00413","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דּחִיל\">preced.</a>) <i>fear, reverence</i>. <span class=\"citation\">Targ. Jon. I, 16</span> (ed. Lag. <a href=\"#\" data-headword=\"דחלא\">דַּחְלָא</a>).</div>","alt":[]},"6703":{"h":"דְּחִילוּ","r":"D00414","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"דְּחִילָא\">same</a>, <i>fear, worship</i>. <span class=\"citation\">Targ. O. Gen. XXVIII, 17</span> מא ד׳ אתרא וכ׳ Oh, the fearfulness of this place!—*Pl. <span dir=\"rtl\">דְּחִילָוָון</span> <i>manifestations of worship</i>. <span class=\"citation\">Targ. Is. LXVI, 20</span> ed. Ven. I a. Levita (ed. Lag. <span dir=\"rtl\">רחילוון</span>, oth. ed. <span dir=\"rtl\">רחילין</span>; h. text <span dir=\"rtl\">צַבִּים</span>(!); cmp. <span dir=\"rtl\">תושבחן</span> for <span dir=\"rtl\">כרכרות</span> ibid.).</div>","alt":[]},"6704":{"h":"דחינוניתא","r":"D00415","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּהֲנוּנִיתָא\">דַּהֲנוּנִיתָא</a></div>","alt":[]},"6705":{"h":"דְּחִיס","r":"D00416","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּחַס\">דְּחַס</a></div>","alt":[]},"6706":{"h":"דְּחִיף","r":"D00417","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּחַף\">דְּחף</a></div>","alt":[]},"6707":{"h":"דְּחִיפָה","r":"D00418","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">דחף</span>) <i>pushing, knocking down</i>. <span class=\"citation\">Y. Sabb. VII, 9ᵈ</span> bot. <span dir=\"rtl\">נגיחה וד׳ אב</span> goring and knocking down are chief actionable damages, v. <a href=\"#\" data-headword=\"אַבָּא I\">אָב</a> (Y. B. Kam. I, beg. 2ᵃ <a href=\"#\" data-headword=\"נְגִיפָה\">נגיפה</a>).</div>","alt":[]},"6708":{"h":"דְּחֵיק","r":"D00419","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּחַק I\">דְּחַק</a></div>","alt":["דְּחִיק"]},"6709":{"h":"דָּחִיק","r":"D00420","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"דְּחַק I\">דחק</a>) </div><div class=\"sense\"><b>1)</b> <i>narrow, pressed</i>. <span class=\"citation\">Targ. Y. Num. XXII, 26</span>. <span class=\"citation\">Targ. I Kings VIII, 64</span> (not <a href=\"#\" data-headword=\"ר\">ר</a>); a. e.—<span class=\"citation\">Taan. 21ᵃ</span> <span dir=\"rtl\">ד׳ להו מילתא טובא</span> they were hard pressed (in great distress); <span class=\"citation\">B. Mets. 114ᵇ</span>.—Pl. <span dir=\"rtl\">דְּחִיקִין</span>, f. <a href=\"#\" data-headword=\"דָּחִיק\">דְּחִיקַן</a>. <span class=\"citation\">Targ. Ez. XLII, 5</span> sq.</div><div class=\"sense\"><b>—2)</b> <i>forced</i>. <span class=\"citation\">B. Kam. 43ᵃ</span>, a. e. <span dir=\"rtl\">שינוייא ד׳</span> a forced answer (argument).</div>","alt":["דְּחִיקָא"]},"6710":{"h":"דְּחַל","r":"D00421","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּחֵיל\">דְּחֵיל</a></div>","alt":[]},"6711":{"h":"דַּחֲלָא I","r":"D00422","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּחַל\">preced.</a>) <i>fearer, worshipper</i>.—ד׳ דיי׳ <i>God-fearing</i>. <span class=\"citation\">Targ. Gen. XXII, 12</span>; a. e.—Pl. <span dir=\"rtl\">דַּחֲלַיָּא</span>. <span class=\"citation\">Targ. Ps. CXXXV, 20</span>; a. e.—<span class=\"citation\">Targ. Is. LV, 13</span> <span dir=\"rtl\">דחלי חטאה</span> shunning evil.—Fem. <a href=\"#\" data-headword=\"דַּחְלְתָא\">דַּחְלְתָא</a>. <span class=\"citation\">Targ. Prov. XXXI, 30</span> ד׳ דיי׳ Ms. (ed. <span dir=\"rtl\">דחלתיה דאלהא</span>). <span class=\"citation\">Targ. II Kings IV, 8</span>.</div>","alt":[]},"6712":{"h":"דַּחֲלָא II","r":"D00423","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דַּחֲלָא I\">preced.</a>) <i>fear</i>. <span class=\"citation\">Targ. Ps. II, 11</span>. <span class=\"citation\">Targ. Prov. I, 7</span>; a. fr.—<span class=\"citation\">Y. B. Mets. II, 8ᶜ</span> bot. <span dir=\"rtl\">בגין דַּחַלְתֵּיךְ</span> from fear of thee; a. e.—Trnsf. (cmp. <a href=\"#\" data-headword=\"יִרְאָה\">יִרְאָה</a>) m. <i>deity</i>. <span class=\"citation\">Targ. Is. II, 22</span>. <span class=\"citation\">Targ. Y. II, Deut. XXXII, 15</span>. Targ. Y. I ib. 18 <span dir=\"rtl\">דַּחֲלַת</span> (Ms. <a href=\"#\" data-headword=\"דחלא\">דחלא</a>); a. fr. Pl. <span dir=\"rtl\">דַּחְלָן</span>. Ib. 17; a. fr.—<a href=\"#\" data-headword=\"דַּחֲלָא II\">דַּחֲלָתָא</a>. <span class=\"citation\">Targ. Ps. LV, 5</span>.</div>","alt":["דַּחַלְתָּא"]},"6713":{"h":"דחלא","r":"D00424","html":"<div class=\"sense\">, Pesik. Zakhor, p. 26ᵇ, read: <a href=\"#\" data-headword=\"זַחֲלָא\">זַחֲלָא</a>.</div>","alt":[]},"6714":{"h":"דַּחֲלוּלָא","r":"D00425","html":"<div class=\"sense\"><i>scarecrows</i>. <span class=\"citation\">B. Bath. 27ᵇ</span> ונד׳ בעלמא סגי ליה Ms. (v. Rabb. D. S. a. l.) and the putting up of scarecrows (to keep the birds off) would be sufficient (Rashi: cutting <i>gaps</i> between the branches).</div>","alt":["דַּחֲלוּלֵי"]},"6715":{"h":"דַּחֲלוֹנָא","r":"D00426","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דַּחֲלָא I\">דַּחֲלָא</a>) <i>God-fearing, conscientious</i>.—Pl. <span dir=\"rtl\">דַּחֲלוֹנַיָּא</span>. <span class=\"citation\">Y. Maas. Sh. V, 56ᵇ</span> bot., v. <a href=\"#\" data-headword=\"חֲבַר\">חֲבַר</a>.</div>","alt":[]},"6716":{"h":"דַּחְלְתָא","r":"D00427","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּחֲלָא I\">דַּחֲלָא</a></div>","alt":["דַּחַלְתָּא"]},"6717":{"h":"דחם","r":"D00428","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דָּחַס\">next w.</a></div>","alt":[]},"6718":{"h":"דָּחַס","r":"D00429","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"דחי\">דחי</a>) <i>to press, crowd.</i> <i>—Part. pass</i>. <span dir=\"rtl\">דָּחוּס</span>, f. <a href=\"#\" data-headword=\"דְּרוּסָה\">דְּחוּסָה</a> <i>crowded, thick, full</i>. <span class=\"citation\">Lev. R. s. 30</span> ד׳ בעלין Ar. (ed. <span dir=\"rtl\">רחוש</span>) thick with leaves; <span dir=\"rtl\">ד׳ בבנים</span> richly blessed with children; Pesik. Ul’kaḥ. p. 184ᵃ דָחוּשׁ Ms. O. (ed. <a href=\"#\" data-headword=\"ר׳\">ר׳</a>, v. Ar. Compl. ed. Koh. s. v. <a href=\"#\" data-headword=\"חָשׁ\">חש</a> 3, a. Koh. Ar. Compl. s. v. <span dir=\"rtl\">דחס</span>).</div><div class=\"sense\"><b>Pi. דִּחֵס</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"דחם\">same</a>. <span class=\"citation\">Tosef. Toh. VIII, 8</span> <span dir=\"rtl\">המְדַחֵס כליו וכ׳</span> (ed. Zuck. <span dir=\"rtl\">המדחם</span>, ed. <span dir=\"rtl\">המדחה</span>; R. S. to <span class=\"citation\">Toh. VII, 7</span> <a href=\"#\" data-headword=\"חָרַשׁ I\">חרש</a>, corr. acc.) if one stuffs his bathing apparel into the bather’s window closet (opp. to <span dir=\"rtl\">המניח</span>).</div></div>","alt":["(דָּחַשׁ)"]},"6719":{"h":"דְּחַס","r":"D00430","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דָּחַס\">preced.</a>) <i>to press, stamp</i>. <span class=\"citation\">Targ. Lam. II, 2</span> ed. Lag.—<span class=\"citation\">Yeb. 103ᵃ</span> <span dir=\"rtl\">צריך למִדְחֲסֵיה לכרעיה</span> must press his foot (rest it firmly on the ground). Y. B. Mets. IX, beg. 12 <span dir=\"rtl\">הוו דחשין</span> (read: <span dir=\"rtl\">דְּחִישִׁין</span> or <span dir=\"rtl\">דְּחִיסִין</span>) they were crowded, opp. <a href=\"#\" data-headword=\"דְּלִיל\">דְּלִיל</a>.</div><div class=\"sense\"><b>Pa. דַּחֵיס</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"דָּחַס\">same</a>. Ib. [<span class=\"citation\">Targ. Y. Deut. XXV, 9</span> <span dir=\"rtl\">ויחדס</span> ed. pr., oth. <span dir=\"rtl\">ויחכס</span>, prob. <span dir=\"rtl\">וִידַחֵס</span>.]</div></div>","alt":[]},"6720":{"h":"דְּחָסָה","r":"D00431","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דָּחַס\">דָּחַס</a>) <i>squeezing, pressure</i> (on the abdomen). <span class=\"citation\">Yeb. 42ᵃ</span> bot.</div>","alt":[]},"6721":{"h":"דָּחַף","r":"D00432","html":"<div class=\"sense\"><i>to push, thrust, knock down</i> (interchanging with <a href=\"#\" data-headword=\"דָּחָה\">דָּחָה</a>). <span class=\"citation\">Yoma VI, 6</span> <span dir=\"rtl\">דְּחָפוֹ וכ׳</span> knocked him down backward. <span class=\"citation\">Ib. 66ᵇ</span> <span dir=\"rtl\">דחפו</span> (<span class=\"citation\">Tosef. ib. IV</span> (<span class=\"citation\">III), 14</span> <span dir=\"rtl\">דחאו</span>), v. <a href=\"#\" data-headword=\"דחי\">דחי</a>. <span class=\"citation\">Snh. VI, 4</span>; a. e.—Part. pass. <span dir=\"rtl\">דָּחוּף</span>, f. <span dir=\"rtl\">דְּחוּפָה</span> <i>impelled, hastened</i>. <span class=\"citation\">M. Kat. 28ᵃ</span> <span dir=\"rtl\">מיתה ד׳</span> (stronger than <span dir=\"rtl\">דְּחוּיָה</span>, v. <a href=\"#\" data-headword=\"דחי\">דחי</a>; Var. <span dir=\"rtl\">סחופה</span>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"6722":{"h":"דְּחַף","r":"D00433","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Lev. XXIV, 23</span> (v. <span class=\"citation\">Snh. 45ᵃ</span> quot. s. v. <a href=\"#\" data-headword=\"דְּחִיָּה\">דְּחִיָּה</a>). <span class=\"citation\">Targ. Y. Deut. VI, 19</span> (some ed. <a href=\"#\" data-headword=\"דחי\">דחי</a>; h. text <span dir=\"rtl\">הדף</span>). <span class=\"citation\">Targ. Job XVIII, 18</span> Ms. Var. (ed. <span dir=\"rtl\">הדף</span>).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"דְּחִיף\">דְּחִיף</a>, pl. <span dir=\"rtl\">דְּחִיפִין</span> <i>hastened, hurried</i>. Targ. II Esth. III, 15; VIII, 14 (Targ. I Esth. <span dir=\"rtl\">סחיפין</span>, cmp. <a href=\"#\" data-headword=\"דָּחַף\">preced.</a>). [<span class=\"citation\">Targ. Prov. I, 26</span>, v. <a href=\"#\" data-headword=\"דְּחֵיךְ\">דְּחֵיךְ</a>.]</div><div class=\"sense\"><b>Ithpe. אִתְדְּחַף  אִידְּחַף</b> <div class=\"sense\"><i>to be pressed against, to hold firm</i>. <span class=\"citation\">Targ. Y. I Deut. XIX, 5</span> Levita <span dir=\"rtl\">תתד׳</span> (ed. <span dir=\"rtl\">תִדְחַף</span>, Pe., Var. <span dir=\"rtl\">תִדְּ׳</span>; Y. II <span dir=\"rtl\">תקף</span>, h. text <a href=\"#\" data-headword=\"דחי\">נדחה</a>).</div></div>","alt":[]},"6723":{"h":"דָּחַק","r":"D00434","html":"<div class=\"sense\"> cmp. <a href=\"#\" data-headword=\"דְּחַף\">preced.</a>) <i>to press, squeeze, crowd, stamp</i>. <span class=\"citation\">Pes. 95ᵇ</span>, a. e. <span dir=\"rtl\">דָּחֲקוּ זבין וכ׳</span> if persons afflicted with … forced their way &amp;c.—<span class=\"citation\">Men. 98ᵇ</span> top <span dir=\"rtl\">דּוֹחֲקִין ובולטין וכ׳</span> pressed against and protruded &amp;c. <span class=\"citation\">Ab. II, 15</span> <span dir=\"rtl\">בעה&quot;ב דוחק</span> the employer (the Lord) presses (urges to work). <span class=\"citation\">Ber. 64ᵃ</span> <span dir=\"rtl\">ד׳ את השעה</span> to force time, be importunate, v. <a href=\"#\" data-headword=\"דָּחָה\">דָּחָה</a>. <span class=\"citation\">Lev. R. s. 28</span>; Pesik. Haom. p. 70ᵇ; <span class=\"citation\">Pesik. R. s. 18</span>; Yalk. Job 998 (ref. to <span dir=\"rtl\">ושאף</span>, <span class=\"citation\">Job V, 5</span>) <span dir=\"rtl\">מי ד׳</span> (<a href=\"#\" data-headword=\"ל\">ל</a>)(<a href=\"#\" data-headword=\"ב\">ב</a>)<span dir=\"rtl\">ממונו וכ׳</span> who trampled upon the wealth of &amp;c.?—Sifra Vayikra Par. 1, ch. II <span dir=\"rtl\">ד׳ להיות מדבר וכ׳</span> (<span class=\"citation\">Yalk. Lev. 430</span> <a href=\"#\" data-headword=\"דָּחַק\">נדחק</a>) He pressed himself (confined His Presence) between the Cherubim &amp;c.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"דְּחוֹק\">דָּחוּק</a> <i>pressed, scarce</i>. <span class=\"citation\">Ab. Zar. 35ᵇ</span></div><div class=\"sense\"><b>Nif. נִדְחָק</b> <div class=\"sense\"><i>to be pressed, confined</i>, v. supra.</div></div>","alt":[]},"6724":{"h":"דְּחַק I","r":"D00435","html":"<div class=\"sense\"><b>1)</b> <i>to push, squeeze</i> &amp;c. <span class=\"citation\">Targ. Jud. I, 34</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to impel, hurry, press</i>. <span class=\"citation\">Targ. Josh. X, 13</span> (h. text <a href=\"#\" data-headword=\"אוּץ\">אוץ</a>). <span class=\"citation\">Targ. Y. Deut. XV, 3</span>; a. fr.—<span class=\"citation\">M. Kat. 28ᵃ</span> <span dir=\"rtl\">דָּחֲקָא רגליה וכ׳</span> the foot of Bar Nathan is pressing (his predestined term of office has begun).</div><div class=\"sense\"><b>Pa. דַּחֵק</b> <div class=\"sense\"><i>to press</i> (a debtor). <span class=\"citation\">Targ. Y. Deut. XV, 2</span> <span dir=\"rtl\">למְדַחֲקָא</span> (ed. Vien. <span dir=\"rtl\">למדה׳</span>).</div></div><div class=\"sense\"><b>Ithpe. אִדְּחֵק  אִידְּ׳</b> <div class=\"sense\"><b>1)</b> <i>to be pressed, squeeze one’s self</i>. <span class=\"citation\">Targ. O. Num. XXII, 25</span> (Y. <span dir=\"rtl\">אַדְחָקַת</span>, read <a href=\"#\" data-headword=\"דְּכַר I\">אִדְּ׳</a>).</div><div class=\"sense\"><b>—2)</b> <i>to be distressed</i>. <span class=\"citation\">Targ. I Sam. XIII, 6</span>; <span class=\"citation\">XIV, 24</span>.</div></div>","alt":["דְּחֵיק"]},"6725":{"h":"דְּחָק","r":"D00436","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּחַק I\">preced.</a>) l) <i>emergency</i>. <span class=\"citation\">Nidd. 9ᵇ</span>, a. fr. <span dir=\"rtl\">בשעת הד׳</span> in a case of emergency.—2) <i>pressure, need</i>, v. <a href=\"#\" data-headword=\"דֹּוחַק\">דּוֹחַק</a>.</div>","alt":[]},"6726":{"h":"דְּחַק II","r":"D00437","html":"<div class=\"sense\">, <i>oppression, distress</i>. <span class=\"citation\">Targ. Y. Deut. XXVI, 7</span> <span dir=\"rtl\">דּחְקָן</span> (O. <span dir=\"rtl\">דּוֹחֲקָנָא</span>).</div>","alt":["דַּחְקָא"]},"6727":{"h":"דַּחֲקָא","r":"D00438","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דְּחַק II\">preced.</a>) <i>oppressor.</i> Pl. <span dir=\"rtl\">דַּחֲקַיָּא</span>. <span class=\"citation\">Targ. Jud. II, 18</span>.</div>","alt":[]},"6728":{"h":"דַּחֲקוּתָא","r":"D00439","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"דְּחַק II\">דַּחְקָא</a>. <span class=\"citation\">Targ. Y. Gen. XXX, 8</span>.</div>","alt":[]},"6729":{"h":"דחש","r":"D00440","html":"<div class=\"sense\">, v. <span dir=\"rtl\">דחס</span> h. a. ch.</div>","alt":[]},"6730":{"h":"*דטסים","r":"D00441","html":"<div class=\"sense\">, <span class=\"citation\">Y. Bets. III, beg. 62ᵃ</span> top; Y. Sabb. III, 14ᵃ bot., read: <span dir=\"rtl\">רִיטִיס</span> (retis) <span dir=\"rtl\">כההיא ר׳</span> a stoppage in the river as one made with a net (v. Sm. Ant. s. v. Retis).</div>","alt":[]},"6731":{"h":"דִּי","r":"D00442","html":"<div class=\"sense\"><b>1)</b> <i>who, which, where, whom</i> &amp;c. <span class=\"citation\">Dan. IV, 5</span>; a. fr.—<span class=\"citation\">Targ. Gen. XXIV, 27</span>. <span class=\"citation\">Targ. Ps. LXXIII, 27</span>; a. fr.—Mostly as prefix: <a href=\"#\" data-headword=\"דִּי־\">דִּי־</a>, <span dir=\"rtl\">דִּ־</span>, <a href=\"#\" data-headword=\"דְּ־\">דְּ־</a>, v. <a href=\"#\" data-headword=\"דְּ־\">דְּ־</a>.—With personal pronouns <span dir=\"rtl\">דִּידִי</span>, <a href=\"#\" data-headword=\"דִּיל־\">דִּילִי</a>; <span dir=\"rtl\">דִּידָךְ</span>, <span dir=\"rtl\">דִּידֵיךְ</span>, <a href=\"#\" data-headword=\"דִּיל־\">דִּילָךְ</a>, <span dir=\"rtl\">דִּילִיךְ</span>; <span dir=\"rtl\">דִּידֵיה</span>, <span dir=\"rtl\">דִּידָהּ</span>, <span dir=\"rtl\">דִּילֵיה</span>, <span dir=\"rtl\">דִּילָהּ</span>; <span dir=\"rtl\">דִּידָן</span>, <span dir=\"rtl\">דִּילָן</span>; <span dir=\"rtl\">דִּידְכוֹן</span>, <a href=\"#\" data-headword=\"דִּלְכוֹן\">דִּלְכוֹן</a>, <span dir=\"rtl\">דִּידְכוּ</span>, <span dir=\"rtl\">דִּידְכֶן</span>; <span dir=\"rtl\">דִּידְהוֹן</span>, <span dir=\"rtl\">דִּידְהוּ</span>, <span dir=\"rtl\">דִּידְהִי</span> <i>mine, thine</i> &amp;c. <span class=\"citation\">Targ. O. Gen. XXXI, 16</span> <span dir=\"rtl\">דילנא</span> (Y. <span dir=\"rtl\">די לנא</span>). Targ. O. ib. XXXIII, 9; a. fr.—<span class=\"citation\">B. Bath. 4ᵇ</span> <span dir=\"rtl\">דידי ודידיה הוא</span> it is mine and his. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עבד דידיה</span> he made the <i>ḥazith</i> on his side, v. <a href=\"#\" data-headword=\"חָזִית\">חָזִית</a>. <span class=\"citation\">Ber. 2ᵇ</span> <span dir=\"rtl\">בין השמשות דידך</span> thy definition of <i>ben hash-sh’mashoth</i>. <span class=\"citation\">Tam. 32ᵃ</span> <span dir=\"rtl\">דידי טבא מדידכו</span> my advice is better than yours. <span class=\"citation\">Gitt. 84ᵇ</span> <span dir=\"rtl\">דילכון</span> your countryman (Rab Kahăna). <span class=\"citation\">B. Kam. 117ᵇ</span> דילכון אמרי דילהון היא I believed (learning) was yours (the Palestineans’); but it is theirs (the Babylonians’); <span class=\"citation\">Succ. 44ᵃ</span> <a href=\"#\" data-headword=\"דִּלְכוֹן\">דִּלְכוֹן</a>, <a href=\"#\" data-headword=\"דִּלְכוֹן\">דִּלְהוֹן</a>.—<span class=\"citation\">Ḥull. 42ᵇ</span> <span dir=\"rtl\">תנא דידן</span> the author or compiler of our Mishnah. <span class=\"citation\">Deut. R. s. 2</span> ר&quot;י דידיה אמר R. J. said in his own name. <span class=\"citation\">Ab. Zar. 17ᵃ</span> <span dir=\"rtl\">פליגא דידיה אדידיה</span> there is a discrepancy between two opinions of his. <span class=\"citation\">Y. Ḥag. II, 78ᵃ</span> top <span dir=\"rtl\">מן דידכֶן</span>; <span class=\"citation\">Y. Snh. VI, 23ᶜ</span> bot. <span dir=\"rtl\">מן דידכון</span> one of yours.</div><div class=\"sense\"><b>—2)</b> <i>that</i> (<i>quod</i>). <span class=\"citation\">Dan. IV, 3</span>; a. fr.—<span class=\"citation\">Y. Taan. IV, 67ᶜ</span> bot. <span dir=\"rtl\">די תעניתא</span> that it is a fast-day.</div>","alt":[]},"6732":{"h":"דִּי II","r":"D00443","html":"<div class=\"sense\"> = <span dir=\"rtl\">דְּאִי</span>, <i>for if</i>. Y. R. Hasḥ. I, 56ᵇ, <span dir=\"rtl\">די לא כן</span>. Also <a href=\"#\" data-headword=\"דִּילָ־\">דִּילָא</a>, <a href=\"#\" data-headword=\"דִּילָ־\">דִּלָא</a> <i>for if not</i>. <span class=\"citation\">Y. Ter. V, 43ᶜ</span>; a. fr.—<a href=\"#\" data-headword=\"דִּילָכֵן\">דִּילָכֵן</a>, <a href=\"#\" data-headword=\"דִּלָכֵן\">דִּלָכֵן</a> <i>for if not so</i>. Y. Shebi. IV, 35ᵃ bot.; a. fr. V. <a href=\"#\" data-headword=\"דִּל\">דִּל</a>.</div>","alt":[]},"6733":{"h":"דַּי","r":"D00444","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sufficiency, plenty</i>; constr. <span dir=\"rtl\">דֵּי</span> <i>enough for</i>; <a href=\"#\" data-headword=\"דַּיי\">דּיִּי</a> <i>enough for me</i>, <a href=\"#\" data-headword=\"דּוּךְ\">דַּיֶּיךָ</a> <i>enough for thee</i> &amp;c. <span class=\"citation\">Nidd. I, 1</span> <span dir=\"rtl\">דַּיָּין שעתן</span> they have enough for the time being, i.e. the unclean condition, now discovered, has no retrospective effect, opp. <span dir=\"rtl\">מפְּקִידָה לפקידה</span>. <span class=\"citation\">Pes. 8ᵇ</span> <span dir=\"rtl\">דַּיֵּינוּ</span> we should have been contented. <span class=\"citation\">Taan. 24ᵇ</span> <span dir=\"rtl\">דַּיּוֹ בקב וכ׳</span> (Ms. M. <span dir=\"rtl\">דַּיי לו קב</span>) he is contented with a Kab of &amp;c. <span class=\"citation\">B. Kam. II, 5</span> (<span class=\"citation\">25ᵃ</span>) <span dir=\"rtl\">דיו לבא מן הדין וכ׳</span> it is sufficient for the law which is derived by conclusion <i>ad majus</i> to be as strict as the law from which it is derived, i.e. you cannot go beyond the latter. B. Kam. <span dir=\"rtl\">ור&quot;ט לית ליה דיו</span> does R. T. not follow the principle of <i>dayyo</i> (that the derived law cannot go beyond the original)? <span dir=\"rtl\">והא דיו דאורייתא הוא</span> is not the principle of <i>dayyo</i> biblical?—<span class=\"citation\">Gen. R. s. 21</span> <span dir=\"rtl\">דייך פפוס</span> it is enough for thee, Papus, i.e. say no more; a. fr.—With prefix <a href=\"#\" data-headword=\"כְּדַי\">כְּדַי</a> (v. <a href=\"#\" data-headword=\"כְּדָיי\">כְּדָיי</a>), constr. <a href=\"#\" data-headword=\"כְּדֵי\">כְּדֵי</a> <i>as much as is required for, corresponding to</i>, as conj. <i>in order to.</i> <span class=\"citation\">Maasr. V, 6</span> <span dir=\"rtl\">ומצא כ׳ מדתו</span> and found a quantity corresponding to what he had measured into it (reasonably increased); <span dir=\"rtl\">יתר על כ׳ מדתו</span> more than the reasonable quantity.—<span dir=\"rtl\">כ׳ דיבור</span> or <span dir=\"rtl\">תוך כ׳ ד׳</span> as much, within as much, time as is needed for an utterance (e.g. a greeting, v. Y. Ber. I, 4ᵇ). <span class=\"citation\">B. Kam. 73ᵃ</span>, a. fr. <span dir=\"rtl\">תוך כ׳ דיבור כדיבור דמי</span> two statements following each other immediately are considered one. <span class=\"citation\">Ib. 73ᵇ</span> <span dir=\"rtl\">תרי ת׳ כ׳ ד׳</span> there are two different intervals comprised under the expression <i>tokh k’d’e dibbur</i>. <span class=\"citation\">Snh. 31ᵇ</span> bot. <span dir=\"rtl\">כ׳ לחלוק וכ׳</span> in order to give honor to &amp;c. <span class=\"citation\">Ib. 32ᵃ</span> bot. <span dir=\"rtl\">כ׳ שלא תנעול דלת וכ׳</span> in order not to make loans too difficult, v. <a href=\"#\" data-headword=\"דֶּלֶת\">דֶּלֶת</a>; a. fr.</div>","alt":[]},"6734":{"h":"דִּי־","r":"D00445","html":"<div class=\"sense\"> (representing δις-, δύο) <i>two, twice</i>, cmp. <a href=\"#\" data-headword=\"דּוּ III\"><span dir=\"rtl\">דּוּ</span> III</a>.</div>","alt":[]},"6735":{"h":"*דִּיאֵו","r":"D00446","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דאו</span> = <span dir=\"rtl\">דאו</span> formed like <a href=\"#\" data-headword=\"עִוֵּר I\">עִוֵּר</a>, v. <a href=\"#\" data-headword=\"דְּיוֹ I\">דֵּיו</a>) <i>longing, faint, love-sick</i>. <span class=\"citation\">Cant. R. to II, 9</span>, v. <a href=\"#\" data-headword=\"דְּיוֹ I\">דֵּיו</a>.</div>","alt":[]},"6736":{"h":"*דיאו","r":"D00447","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> top, <span dir=\"rtl\">קַלּוֹן ד׳</span>, read <span dir=\"rtl\">דִּיאֶן</span> (calo diem) <i>I proclaim</i> (<i>welcome</i>) <i>the day</i>, an etymology of <i>calenda</i> (v. Sm. Ant. s. v. Calendar). V. <a href=\"#\" data-headword=\"קָלִנְדַּס\">קָלִנְדַּס</a>.</div>","alt":[]},"6737":{"h":"*דִּיאוֹנִיסִין","r":"D00448","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (διονύσια, τὰ) <i>the Dionysian feast, bacchantic revels</i>. <span class=\"citation\">Lev. R. s. 33</span> (ref. to <span class=\"citation\">Ezek. XXIII, 42</span>) <span dir=\"rtl\">מובאים קאניסין וכ׳</span> (corr. acc.) ‘<i>carried along</i>’ (in procession) refers to the Dionysia, ‘drunken’, means the revellers, v. <a href=\"#\" data-headword=\"דַּחְיָיא\">דַּחְיָיא</a>.</div>","alt":[]},"6738":{"h":"דִּיאֵטָא","r":"D00449","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּיֵיטָא\">דְּיִיטָא</a></div>","alt":[]},"6739":{"h":"דִּיאֲטַגְמָא","r":"D00450","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (διάταγμα) <i>edict, ordinance</i>. Targ. II Esth. III, 15; a. e.—Sifré Deut. s. 33 <span dir=\"rtl\">כדיוט׳ ישנה</span> like an antiquated ordinance. Lev. R. s. l; a. fr.—Pl. <span dir=\"rtl\">דִּיאֲטַגְמָאוֹת</span>, <span dir=\"rtl\">דִּיטַ׳</span>, <a href=\"#\" data-headword=\"דִּיאֲטַגְמָא\">דְּיוֹטַ׳</a>. <span class=\"citation\">Ex. R. s. 30</span>; a. e.—<span dir=\"rtl\">דִּיאֲטַגְמָטִין</span>. <span class=\"citation\">Y. Shebu. VII, 38ᵃ</span> bot. <a href=\"#\" data-headword=\"דיאטיגמתין\">דיאטיגמתין</a>; <span class=\"citation\">Y. Keth. IX, 33ᵇ</span> bot. <span dir=\"rtl\">דין מוגמרין</span> (corr. acc.).</div>","alt":["דִּיטַגְמָא","(דְּיוֹטַ׳)"]},"6740":{"h":"דִּיאֵטָה","r":"D00451","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּיֵיטָא\">דְּיִיטָא</a></div>","alt":["דִּיאֵטוֹת"]},"6741":{"h":"דיאטיגמתין","r":"D00452","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיאֲטַגְמָא\">דִּיאֲטַגְמָא</a></div>","alt":[]},"6742":{"h":"דִּיאַטְרִיטָא","r":"D00453","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (diatreta, v. Sm. Ant. s. v. Vitrum) <i>cut or engraved glass vessels</i>. <span class=\"citation\">Ex. R. s. 27</span>, end [read:] <span dir=\"rtl\">ב׳ כוסות הללו ד׳</span> these two cups of cut glass. <span class=\"citation\">Esth. R. to I, 7</span> <span dir=\"rtl\">כוסות דיוטירי׳</span> (corr. acc.). <span class=\"citation\">Gen. R. s. 19</span> <span dir=\"rtl\">דייטרו׳</span> (corr. acc.). <span class=\"citation\">Ruth R. to I, 1</span> <span dir=\"rtl\">כוסות דיוטריטון</span> (corr. acc.); a. fr.</div>","alt":["דִּיאַטְרִיטִין","דְּיַי׳","(דְּיוֹ׳)"]},"6743":{"h":"*דִּיאִיקִיטָא","r":"D00454","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (διοικήτης, dioecetes) <i>overseer of the treasury, treasurer</i>. <span class=\"citation\">Lev. R. s. 5</span> (prov.) unfortunate the district where the physician has the gout, <span dir=\"rtl\">ודאיקוטטא בחד עינא</span> ed. (Mus. <span dir=\"rtl\">ודייקטסא</span>, corr. acc.) and the treasurer only one eye (is unable to examine the coins).</div>","alt":["דִּיאִיקִיטֵיס"]},"6744":{"h":"דַּיָּאלָא","r":"D00455","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּיָּילָא\">דַּיָּילָא</a></div>","alt":[]},"6745":{"h":"דיאלקטו","r":"D00456","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִלְקְטִי\">אִלְקְטִי</a></div>","alt":[]},"6746":{"h":"דיאנא","r":"D00457","html":"<div class=\"sense\">, <span class=\"citation\">Men. 77ᵃ</span> ed., v. <a href=\"#\" data-headword=\"זְיָינָא II\"><span dir=\"rtl\">זְיָינָא</span> II</a></div>","alt":["דיאנה"]},"6747":{"h":"*דיאתימון","r":"D00458","html":"<div class=\"sense\">, read <span dir=\"rtl\">דִּיאֶתִּימִין</span> (διεθέμην, sec. aor. med. of διατίθημι) <i>I disposed by will</i>. <span class=\"citation\">Y. B. Bath. VIII, 16ᶜ</span> top <span dir=\"rtl\">אף הכותב ד׳ בלעז וכ׳</span> even if one writes in Greek διεθέμην (<i>I willed</i>, instead of <i>I will</i>), it is to be considered as if it were a gift (cmp. <span class=\"citation\">ib.</span> <span dir=\"rtl\">עשיתי</span>, <span dir=\"rtl\">יחזק</span> &amp;c.); ib. <span dir=\"rtl\">חיזרתי וכ׳</span> I went around to all linguists to find out what <a href=\"#\" data-headword=\"ד׳\">ד׳</a> was &amp;c.; Tosef. ib. IX, 14 <span dir=\"rtl\">דיותומין</span> (ed. Zuck. <span dir=\"rtl\">דייתיקי</span>, corr. acc.).</div>","alt":[]},"6748":{"h":"דִּיאֲתִיקִי","r":"D00459","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (διαθήκη) <i>a disposition of property</i>, esp. <i>by will and testament; covenant, contract</i>, v. <span class=\"citation\">Y. Peah III, 17ᵈ</span> bot. for difference between <a href=\"#\" data-headword=\"ד׳\">ד׳</a> a. <span dir=\"rtl\">מתנה</span>.—<span class=\"citation\">Targ. Y. Gen. XXIV, 10</span> ד׳ דריבונא Ar. (ed. <span dir=\"rtl\">שפר אפותיקי</span>); <span class=\"citation\">Gen. R. s. 59</span>, end (ref. to Gen. l. c.) <span dir=\"rtl\">זו ד׳</span> this means (his master’s) will (in favor of Isaac).—Y. Ber. V, 9ᵇ top <span dir=\"rtl\">בד׳ נתתיו לו וכ׳</span> have I given it to him as a bequest (which may be cancelled)? I have given it to him as a donation. <span class=\"citation\">Y. B. Bath. VIII, 16ᵇ</span> bot. <span dir=\"rtl\">ויחזור בדְיָיתִיקָתוֹ</span> he may change his will. Ib.; Bab. <span class=\"citation\">B. Bath. 152ᵇ</span> <span dir=\"rtl\">ד׳ מבטלת ד׳</span> the later will cancels the prior. Y. B. Mets. I, end, 8ᵃ <span dir=\"rtl\">אין … לפגם דייתיקין וכ׳</span> nobody is likely to make a defective will (by anticipating in it the receipt of a debt before it has been collected).—Pl. <span dir=\"rtl\">דְּיָיתִיקָאוֹת</span>. <span class=\"citation\">B. Mets. 19ᵃ</span>. <span class=\"citation\">Tosef. B. Bath. XI, 6</span>; a. e.</div>","alt":["דְּיָיתִיקִי","(דְּיוֹ׳)"]},"6749":{"h":"דִּיב","r":"D00460","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּב\">דּוּב</a></div>","alt":[]},"6750":{"h":"דֵּיבָא","r":"D00461","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"זְאֵב\">זְאֵב</a>), <i>wolf</i>. <span class=\"citation\">Targ. Y. I Gen. XLIX, 27</span> (<span class=\"citation\">II</span> <a href=\"#\" data-headword=\"דּוֹב\">דּוֹב</a>). <span class=\"citation\">Targ. Is. XI, 6</span> (Regia <a href=\"#\" data-headword=\"דּוֹב ²\">דּוּבָא</a>); <span class=\"citation\">LXV, 25</span>.—Pl. <span dir=\"rtl\">דֵּיבִין</span>. <span class=\"citation\">Targ. Zeph. III, 3</span>.—[<span class=\"citation\">Targ. Is. XI, 7</span> דיבא <i>bear</i>, v. <a href=\"#\" data-headword=\"דּוֹב ²\">דּוּבָּא</a>.]</div>","alt":[]},"6751":{"h":"דִּיבָא","r":"D00462","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>flux, gonorrhoea</i>, v. <a href=\"#\" data-headword=\"דּוֹבָא\">דּוֹבָא</a>.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">סני דיבא</span> or <span dir=\"rtl\">סניא דיבי</span> <i>a certain part of the maw</i>, v. <a href=\"#\" data-headword=\"סַנֵּי\">סַנֵּי</a>.</div>","alt":[]},"6752":{"h":"דִּיבָּא","r":"D00463","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"דִּבָּה\">דִּבָּה</a>. <span class=\"citation\">Targ. O. Gen. XXXVII, 2</span> <span dir=\"rtl\">דִּיבְּהוֹן</span>, <span dir=\"rtl\">דִּבְּהוֹן</span>, ed. Berl. <span dir=\"rtl\">טִיבְּהוֹן</span>.</div>","alt":[]},"6753":{"h":"דִּיבָבָא","r":"D00464","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"זְבוּב\">זְבוּב</a>) <i>fly</i>. <span class=\"citation\">Targ. Koh. X, 1</span> (h. text <span dir=\"rtl\">זבובי מות</span>, ed. Buxt. <span dir=\"rtl\">דבובא</span>).—Pl. <span dir=\"rtl\">רִּיבְבַיָּא</span>, <span dir=\"rtl\">דִּיבְבֵי</span>. <span class=\"citation\">Targ. Is. VII, 18</span> (ed. Lag. <span dir=\"rtl\">דבב׳</span>, ed. Buxt. <span dir=\"rtl\">דְּבוּבַיָּא</span>). <span class=\"citation\">Targ. Y. Lev. XI, 20</span> <span dir=\"rtl\">דִּיַבְבֵי</span> (read <a href=\"#\" data-headword=\"דִּכְוָון\">דִּי׳</a>); <span class=\"citation\">Targ. Y. Deut. XIV, 19</span>.  v. <a href=\"#\" data-headword=\"דִּידְבָא\">דִּידְבָא</a>.</div>","alt":[]},"6754":{"h":"דִּיבָּה","r":"D00465","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּבָּה\">דִּבָּה</a></div>","alt":[]},"6755":{"h":"דיבון","r":"D00466","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. II, Num. XXXII, 24</span> some ed., v. <a href=\"#\" data-headword=\"דִּכְוָון\">דִּכְוָון</a></div>","alt":["דיבוון"]},"6756":{"h":"דיבונא","r":"D00467","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XXIV, 2</span>, v. <a href=\"#\" data-headword=\"דִּיכּוּנָא\">דִּיכּוּנָא</a>.</div>","alt":[]},"6757":{"h":"דִּיבּוּק","r":"D00468","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דבק</span>) </div><div class=\"sense\"><b>1)</b> <i>attachment, junction, intimacy</i>. <span class=\"citation\">Cant. R. to II, 6</span> (ref. to <span class=\"citation\">Deut. XI, 22</span>) <span dir=\"rtl\">איזהו ד׳</span> what is the form of intimacy? [<span class=\"citation\">Ab. ch. VI</span> (Boraitha) <span dir=\"rtl\">ד׳ חברים</span> (some ed. <a href=\"#\" data-headword=\"דִּקְדּוּק\">דקדוק</a>) the friendship of students (the care in selection of friends).—2) <i>glue, paste, solder</i>. <span class=\"citation\">Y. Sabb. III, 6ᵃ</span> bot. <span dir=\"rtl\">שמא נתאכל דִּיבּוּקוֹ</span> (read: <span dir=\"rtl\">שלא יתא׳ וכ׳</span>) lest its solder may be consumed (if the vessel be left without water). [<span class=\"citation\">Ḥull. 52ᵃ</span>, read <span dir=\"rtl\">דָּבוּק</span> if the bird is caught by means of glue, v. <a href=\"#\" data-headword=\"דָּבֵק\">דָּבַק</a>.]</div>","alt":["דִּבּוּק"]},"6758":{"h":"דִּיבּוּק ²","r":"D00469","html":"<div class=\"sense\">, <i>joining</i>. <span class=\"citation\">Targ. I Kings VII, 30</span> <span dir=\"rtl\">עובד ד׳</span> joiner’s work.</div>","alt":["דִּבּוּק"]},"6759":{"h":"דִּיבּוּר","r":"D00470","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דבר</span>) <i>utterance, speech, dictate</i>. <span class=\"citation\">Cant. R. to III, 4</span> <span dir=\"rtl\">ד׳ קשה</span> of the various expressions for prophecy <i>dibbur</i> is the severest; <span class=\"citation\">Gen. R. s. 44</span>; <span class=\"citation\">Macc. 11ᵃ</span>; (Sifre Num. 99 <a href=\"#\" data-headword=\"דִּיבֵּר\">דִּבֵּר</a>). <span class=\"citation\">Lev. R. s. 1</span> (play on <span dir=\"rtl\">ויקר</span>, <span class=\"citation\">Num. XXIII, 4</span>, a. <a href=\"#\" data-headword=\"וַיִּקְרָא\">ויקרא</a> <span class=\"citation\">Lev. I, 1</span>) the Lord reveals Himself to the gentile prophets <span dir=\"rtl\">בחצי ד׳</span> only with half a word (defective revelation), opp. <span dir=\"rtl\">ד׳ שלם</span>. <span class=\"citation\">Ex. R. s. 28</span> <span dir=\"rtl\">ד׳ זכור וכ׳</span> the commandment, ‘Remember the Sabbath’. <span class=\"citation\">Y. Ned. III, 37ᵈ</span> bot.; a. fr.—<span dir=\"rtl\">תוך כדי ד׳</span>, v. <a href=\"#\" data-headword=\"דַּי\">דַּי</a>.—Esp. <span dir=\"rtl\">הַדִּ׳</span> <i>revelation, Divine Speech</i>, (hypostasized) <i>the Word, the Dibbur</i>. <span class=\"citation\">Lev. R. s. 1</span>, beg. <span dir=\"rtl\">קול הד׳ עצמו</span> the direct voice of the Dibbur. <span class=\"citation\">Yeb. 5ᵇ</span>, a. fr. <span dir=\"rtl\">לפני הד׳</span> prior to the revelation. <span class=\"citation\">Cant. R. to I, 2</span>; a. fr.—<span dir=\"rtl\">על פי הד׳</span> following the Divine order. <span class=\"citation\">Y. Sabb. VII, 10ᶜ</span>; a. fr.—Pl. <span dir=\"rtl\">דִּיבּוּרִים</span>, <span dir=\"rtl\">דִּיכּוּרִין</span>, <span dir=\"rtl\">דִּבּ׳</span>. <span class=\"citation\">Gen. R. s. 38</span> <span dir=\"rtl\">ד׳ אחדים</span> mysterious words (accounts), v. <a href=\"#\" data-headword=\"אֶחָד\">אֶחָד</a>. Cant. R. l. c.; a. fr. V. <a href=\"#\" data-headword=\"דָּבָר\">דָּבָר</a>.</div><div class=\"sense\"><b>—2)</b>  (homilet., v. <span class=\"citation\">Ps. XLVII, 4</span>) <i>being led, submission</i>. <span class=\"citation\">Sabb. 63ᵃ</span> <span dir=\"rtl\">אין ד׳ אלא נחת</span> the root <span dir=\"rtl\">דבר</span> (in <span class=\"citation\">Mal. III, 16</span> <span dir=\"rtl\">נדברו</span>) means submission; <span class=\"citation\">Macc. 11ᵃ</span> (corr. acc.).</div>","alt":["דִּבּוּר"]},"6760":{"h":"דִּיבּוּרָא","r":"D00471","html":"<div class=\"sense\"> esp. <i>revelation</i>. <span class=\"citation\">Targ. Ez. I, 24</span>; <span class=\"citation\">25</span> ed. Lag. <span dir=\"rtl\">דבי׳</span> (oth. <a href=\"#\" data-headword=\"דִּיבּוּרָא\">דבו׳</a>, some ed. <span dir=\"rtl\">די בירא</span>, read <a href=\"#\" data-headword=\"דִּיבֵּירָא\">דִּיבֵּירָא</a>). <span class=\"citation\">Targ. Y. Num. VII, 89</span>; a. fr.—<span class=\"citation\">R. Hash. 6ᵃ</span> אימא ד׳ לא כלום הוא I might have thought a mere word (without action) was of no effect. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא קיימיה לדִיבּוּרֵיה</span> he did not substantiate his word (by an action). <span class=\"citation\">Ned. 41ᵃ</span> <span dir=\"rtl\">ד׳ קשי וכ׳</span> talking is injurious to the eyes; a. fr.—Pl. <span dir=\"rtl\">דִּיבּוּרַיָּא</span>, <span dir=\"rtl\">דְּבִירַיָּא</span>, <span dir=\"rtl\">דִּיבֵּירַיָּא</span>, <span dir=\"rtl\">דִּבּ׳</span>, esp. <i>the Ten Commandments</i>. <span class=\"citation\">Targ. Y. Ex. XX, 1</span> (<span class=\"citation\">II</span> <span dir=\"rtl\">דִּיבְרַיָּא</span>); a. fr.—Y. Meg. IV, 75ᵇ bot. <span dir=\"rtl\">קטע בריבי׳ וכ׳</span> cut the Ten Commandments apart, so that our children may be able to study them.</div>","alt":["דִּבּוּ׳","דִּבֵּירָא","דְּבִירָא"]},"6761":{"h":"דִּיבְחָא","r":"D00472","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּבַח II\">דִּבְחָא</a></div>","alt":[]},"6762":{"h":"דִּיבֵי","r":"D00473","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיבָא\">דִּיבָא</a></div>","alt":[]},"6763":{"h":"דִּיבֵירָא","r":"D00474","html":"<div class=\"sense\">, <i>of Bera, Bire</i>, v. <a href=\"#\" data-headword=\"בֵּיר\">בֵּירָא</a>.</div>","alt":[]},"6764":{"h":"דִּיבֵּירָא","r":"D00475","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיבּוּרָא\">דִּיבּוּרָא</a></div>","alt":[]},"6765":{"h":"דִּיבְלָא","r":"D00476","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּבֵילְתָּא\">דְּבֵילְתָּא</a>.—[דיבלא <span class=\"citation\">Yoma 78ᵇ</span>, v. ַ<a href=\"#\" data-headword=\"בְּלָא\">בְלָא</a>.]</div>","alt":[]},"6766":{"h":"דִּיבְקָא","r":"D00477","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">דבק</span>) <i>joining, combination</i>. <span class=\"citation\">Meïl. 16ᵇ</span> האי ד׳ דידך היא Ar. (ed. <a href=\"#\" data-headword=\"דְּיוּקָא\">דְּיוּקָא</a>) this is merely thy own combination (that Rab’s opinion was delivered in connection with the Mishnah), but Rab himself recited merely a tradition (without reference to that special clause of the Mishnah).</div>","alt":["דּוּבְקָא"]},"6767":{"h":"דִּיבֵּר","r":"D00478","html":"<div class=\"sense\"> (b. h.) m. = <a href=\"#\" data-headword=\"דִּיבּוּר\">דִּיבּוּר</a>, esp. <i>revelation</i>. Sifra Thazr., <span class=\"citation\">Neg., ch. I</span>. Mekh. Bo, beg. (Tanḥ. ib. 5 <span dir=\"rtl\">דבור</span>); a. fr.—Pl. <span dir=\"rtl\">דִּיבְּרוֹת</span> (fem.). <span class=\"citation\">Mekh. I. c., v. <a href=\"#\" data-headword=\"כָּלוּל\">כָּלוּל</a>. <span class=\"citation\">Y. Ber. IV, 8ᶜ</span> top; a. fr.—Esp. <i>the Ten Commandments</i>. <span class=\"citation\">B. Kam. 54ᵇ</span> <span dir=\"rtl\">ד׳ הראשונות</span> the text of the Decalogue in Exodus, <span dir=\"rtl\">ד׳ האחרונות</span> the one in Deuteronomy. <span class=\"citation\">Snh. 67ᵃ</span>, <span dir=\"rtl\">מִדִּבְּרוֹתֶיךָ</span>, v. <a href=\"#\" data-headword=\"כָּלָה\">כָּלָה</a>.</span></div>","alt":["דִּבֵּר"]},"6768":{"h":"דִּיבְרָא","r":"D00479","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיבּוּרָא\">דִּיבּוּרָא</a></div>","alt":["דִּיבָּרָא"]},"6769":{"h":"דִּיבְשָׁא","r":"D00480","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּבְשָׁא\">דּוּבְשָׁא</a></div>","alt":[]},"6770":{"h":"דִּיגָּאלָא","r":"D00481","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּגָּלָא\">דַּגָּלָא</a></div>","alt":[]},"6771":{"h":"דִּיגּוּל","r":"D00482","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (דָּגַל I) <i>stratagem, deception</i>. <span class=\"citation\">Cant. R. to II, 4</span> <a href=\"#\" data-headword=\"דִּיגּוּל\">דִּיגּוּלוֹ</a> his (Jacob’s) stratagem (<span class=\"citation\">Gen. XXVII, 16</span>).—Pl. <span dir=\"rtl\">דִּיגּוּלִין</span>, <a href=\"#\" data-headword=\"דִּגּוּל\">דִּגּוּ׳</a>. Ib.; v. <a href=\"#\" data-headword=\"דָּגַל I\">דָּגַל</a>.</div>","alt":[]},"6772":{"h":"דִּיגּוּן","r":"D00483","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <span dir=\"rtl\">דגן</span>) <i>storing of grain, piling up</i>. <span class=\"citation\">Gitt. 47ᵃ</span> <span dir=\"rtl\">דִּיגּוּנְךָ ולא ד׳ נכרי</span> (the word <span dir=\"rtl\">דגנך</span>, <span class=\"citation\">Deut. XIV, 23</span> means) what thou (the Israelite) storest up (is subject to tithes), but not what the gentile stores up, opp. to <span dir=\"rtl\">דְּגָנְךָ וכ׳</span> the grain growing on thy ground (Palestine). <span class=\"citation\">B. Mets. 88ᵇ</span> בני ד׳ Ms. F. (ed. <a href=\"#\" data-headword=\"גּוֹרֶן\">גורן</a>, v. Rabb. D. S. a. l. note 100) adapted for storage.</div>","alt":[]},"6773":{"h":"דִּיגוֹן","r":"D00484","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  (δίγονος) prop. <i>born a second time</i>, in gen. <i>for a second term, twice</i> (Lat. <i>bis</i>). <span class=\"citation\">B. Bath. 164ᵇ</span> such is the custom of that nation <span dir=\"rtl\">ארכן שנייה קורין לו ד׳</span> (Ms. M. <span dir=\"rtl\">דזגין</span>) an archont in his second term is called <i>digonos</i> (bis, iterum consul). Ib.; <span class=\"citation\">Naz. 8ᵇ</span> if one says, I vow to be a Nazir … די׳ שתים <i>digon</i>, he has to be a Nazir twice in succession; Tosef. ib. I, 2 <a href=\"#\" data-headword=\"טִיגּוּן\">טיגון</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"דריגון\">דריגון</a>, corr. acc.).</div><div class=\"sense\"><b>—2)</b>  (by analogy with τριγώνιον, τετραγώνιον) <i>having two corners</i>. <span class=\"citation\">Tosef. Neg. VI, 3</span> <span dir=\"rtl\">(<span dir=\"rtl\">בית</span>) <span dir=\"rtl\">דיגין וכ׳</span></span> ed. Zuck. (corr. acc.) a house which has only two corners (semicircularly built); B. Bath. l. c.; Naz. l. c.</div>","alt":[]},"6774":{"h":"דיגטסיס","r":"D00485","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיגְנוֹסִיס\">דִּיגְנוֹסִיס</a></div>","alt":[]},"6775":{"h":"דִּיגְלָא","r":"D00486","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*דִּגְלָא\">דִּגְלָא</a></div>","alt":[]},"6776":{"h":"דִּיגְלַת","r":"D00487","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>the river Tigris</i>. <span class=\"citation\">Targ. Gen. II, 14</span>.—<span class=\"citation\">M. Kat. 25ᵇ</span> bot. <span dir=\"rtl\">נשוק כיפי ד־׳ וכ׳</span> the shores of the Tigris touched each other (the water forming a level with the banks). <span class=\"citation\">Kidd. 71ᵇ</span>. <span class=\"citation\">Yeb. 121ᵃ</span>. <span class=\"citation\">Ber. 59ᵇ</span>. <span class=\"citation\">Taan. 24ᵇ</span> <span dir=\"rtl\">שפוך מרזבי דמחוזא לד׳</span> (not <span dir=\"rtl\">דציפורי</span>, v. Rabb. D. S. a. l. note) the gutters of Maḥuza emptied themselves into the Tigris.</div>","alt":["דִּגְ׳"]},"6777":{"h":"דִּיגְמָא","r":"D00488","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוּגְמָא\">דּוּגְמָא</a></div>","alt":[]},"6778":{"h":"דִּיגְנוֹסִיס","r":"D00489","html":"<div class=\"sense\">, f. (διάγνωσις) <i>decree</i>. Targ. II Esth. II, 8 ed. Lag. (ed. <span dir=\"rtl\">דיגט׳</span>, corr. acc.).</div>","alt":[]},"6779":{"h":"דִּיד־","r":"D00490","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּי\">דִּי</a></div>","alt":[]},"6780":{"h":"דִּידְבָא","r":"D00491","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">דנדבא</span>, v. <a href=\"#\" data-headword=\"דִּיבָבָא\">דִּיבבָא</a>) <i>fly</i>. <span class=\"citation\">Ḥull. 58ᵇ</span> <span dir=\"rtl\">לית די׳ בת שתא</span> (Ar. <span dir=\"rtl\">דד׳</span>) no fly lives a whole year. <span class=\"citation\">Ber. 44ᵃ</span> <span dir=\"rtl\">עד דהוה שריק ליה דו׳ וכ׳</span> (Ms. M. <span dir=\"rtl\">דשריא … דור׳</span>; v. Rabb. D. S. a. l. note) so that a fly would glide down his (fat and smooth) face.—<span class=\"citation\">Gitt. 86ᵇ</span> <span dir=\"rtl\">דִּידְבְתָא דביני כיפי</span> a large fly found among sheaves.</div>","alt":["דּוּדְבָא","(דִּדְבָא)"]},"6781":{"h":"*דִּידְיוֹנִי","r":"D00492","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (reduplic. of <a href=\"#\" data-headword=\"דוי\">דוי</a> or <span dir=\"rtl\">דוע</span>; cmp. <a href=\"#\" data-headword=\"*אוּדְיָיתָא I\">אוּדְיָיתָא</a>) <i>the vapor room</i>. <span class=\"citation\">Nidd. 67ᵃ</span> אימר בד׳ נפל Ar. s. v. <a href=\"#\" data-headword=\"אַדְווּתָא\">אדוותא</a> (ed. <a href=\"#\" data-headword=\"רִדְיוֹנֵי\">רדיוני</a>) I say, it (the mud) fell off in the vapor room (where she entered after the bath).</div>","alt":[]},"6782":{"h":"דִּידְכֵי","r":"D00493","html":"<div class=\"sense\"> (διαδοχή, v. <a href=\"#\" data-headword=\"דְּיָיּתִּיכוֹס\">דייתיכוס</a>) <i>relays, guards at stations</i>. [Popular adaptation <span dir=\"rtl\">דרכ׳</span>, as if fr. <a href=\"#\" data-headword=\"דֶּרֶךְ\">דֶּרֶךְ</a>.] <span class=\"citation\">Yoma VI, 8</span> (<span class=\"citation\">68ᵇ</span>) <span dir=\"rtl\">דיד׳</span> Y. ed. (Mish. <a href=\"#\" data-headword=\"דִּירְכָאוֹת\">דִּרְכָאוֹת</a>; Bab. ed. <a href=\"#\" data-headword=\"דִּירְכָא\">דִּירְכָ׳</a>, Ms. M. <span dir=\"rtl\">דִּיתְּכָ׳</span>, Ms. L. <span dir=\"rtl\">דוד׳</span>, <span dir=\"rtl\">דיד׳</span>; Mish. Nap. <a href=\"#\" data-headword=\"דִּירְכָאוֹת\">דִּירְכָיוֹת</a>, v. Rabb. D. S. a. l. note). Mekh. B’shall. s. 1 דורכיות היו לו Pharaoh had guards at stations (communicating with one another).—<span class=\"citation\">Gen. R. s. 10</span>; <span class=\"citation\">Yalk. ib. 16</span> [read:] <span dir=\"rtl\">הרבה להן בריצה והרבה להן בדְיָידוֹכִין</span> he increased for them the speed (of the mail bearers), and the number of mail stations. <span class=\"citation\">Esth. R. to I, 1</span> <span dir=\"rtl\">דורכ׳ עם דורניאות וכ׳</span></div>","alt":["דִּידְכָאוֹת"]},"6783":{"h":"דַּיָּה","r":"D00494","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"דָּאָה I\">דָּאָה</a>) <i>Dayyah</i> name of several unclean birds. <span class=\"citation\">Ḥull. 63ᵃ</span><i>ḥăsidah</i> (<span class=\"citation\">Lev. XI, 19</span>) <span dir=\"rtl\">זו ד׳ לבנה</span> is the white <i>dayyah</i> (stork), <i>anaphah</i> (ib.) <span dir=\"rtl\">זו ד׳ רגזנית</span> the irascible <i>dayyah;</i> v. <a href=\"#\" data-headword=\"דַּיְּיתָא\">דַּיְּיתָא</a>.</div>","alt":[]},"6784":{"h":"דִּיהַּ","r":"D00495","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"דוי\">דוי</a>) <i>to be faint</i>.—<i>Af</i>. <span dir=\"rtl\">אֲדִיהַּ</span> <i>to make fainter, paler</i>. <span class=\"citation\">Nidd. 20ᵃ</span> <span dir=\"rtl\">אֲדִיהוּ ליה וכ׳</span> they showed him a fainter color, and he declared it clean.</div>","alt":[]},"6785":{"h":"דֵּיהֶא","r":"D00496","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דִּיהַּ\">preced.</a>; cmp. form and meaning of <a href=\"#\" data-headword=\"כֵּהֶה\">כֵּהֶה</a>) <i>faint, feeble, dim; light</i> in substance, <i>thin.</i> <span class=\"citation\">Neg. I, 2</span> <span dir=\"rtl\">של סיד דֵּיהָה הימנה</span> the red within the lime-colored leprosy is fainter than the latter, opp. <span dir=\"rtl\">עז</span>; <span class=\"citation\">Tosef. ib. I, 3</span> <span dir=\"rtl\">דּוֹהֶא</span>. <span class=\"citation\">Tosef. Nidd. III, 11</span> <span dir=\"rtl\">ד׳ מכאן</span> if fainter than this (shoe-black), opp. <a href=\"#\" data-headword=\"עָמוֹק\">עמוק</a>; <span class=\"citation\">Nidd. II, 7</span>; <span class=\"citation\">20ᵃ</span> <span dir=\"rtl\">ד׳ מכן</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ד׳ דד׳</span> extremely faint. <span class=\"citation\">Gitt. 57ᵃ</span> דיהה מן האור Ar. (ed. <a href=\"#\" data-headword=\"דּוּחָה\">דוחה</a>, read <span dir=\"rtl\">דּוֹהָה</span>, fr. <a href=\"#\" data-headword=\"דָּהָה\">דָּהָה</a>) gets faint from the effect of the heat. <span class=\"citation\">Yeb. 80ᵇ</span>; <span class=\"citation\">Tosef. ib. X, 6</span> <span dir=\"rtl\">שכבת זרעו דוחה</span> his semen is watery, opp. <span dir=\"rtl\">מקושר</span> cohesive; Tosef. <span class=\"citation\">Zabim II, 4</span> <span dir=\"rtl\">דוהה</span>; <span class=\"citation\">Nidd. 35ᵇ</span>.—<span class=\"citation\">Y. B. Bath. VIII, 16ᵃ</span> bot. wherever the word <span dir=\"rtl\">מורשה</span> (heirloom) is used, <span dir=\"rtl\">לשין דיהא</span> it is a faint (vague) expression (not meant in its true sense as a real inheritance). <span class=\"citation\">Ib.</span> (ref. to <span class=\"citation\">Deut. XXXIII, 4</span>) <span dir=\"rtl\">לית ד׳ סיגין וכ׳</span> there is none vaguer than this (<i>morashah</i>), for whosoever labors (studies), obtains the whole of it.—Pl. f. <span dir=\"rtl\">דֵּיהוֹת</span>. <span class=\"citation\">Y. Ter. III, 42ᵇ</span> top <span dir=\"rtl\">ענבים ד׳</span> the juice of grapes is light in substance (incohesive).</div>","alt":["דֵּיהֶה"]},"6786":{"h":"דֵּיהִי","r":"D00497","html":"<div class=\"sense\"> (= <span dir=\"rtl\">דִּי הִי</span>) <i>of this</i> (certain event). <span class=\"citation\">Targ. Y. Gen. XXV, 33</span> <span dir=\"rtl\">כיום ד׳</span> as if it were the day of a certain event (of Isaac’s death and Esau’s succession, cmp. <span class=\"citation\">Targ. Y. ib. 31</span>); Targ. O. ib. 31; 33 <a href=\"#\" data-headword=\"דִּלְהֵי\">דִּלְהֵי</a> ed. Berl. (ed. <a href=\"#\" data-headword=\"דִּלְהֵי\">דִּלְהֵין</a>, <a href=\"#\" data-headword=\"דִּלְהֵי\">דִּילְהֵין</a>, cmp. <a href=\"#\" data-headword=\"דִּיל־\">דִּילִי</a>, <span dir=\"rtl\">דִּילֵיה</span>, s. v. <a href=\"#\" data-headword=\"דִּי\">דִּי</a>).</div>","alt":[]},"6787":{"h":"דִּיהֲנָא","r":"D00498","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"דְּהַן II\">דַּהֲנָא</a>. <span class=\"citation\">Targ. Ps. LXV, 12</span>.</div>","alt":[]},"6788":{"h":"דַּיּוּ","r":"D00499","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דַּיְּיתָא\">דַּיְּיתָא</a></div>","alt":[]},"6789":{"h":"דְּיוֹ I","r":"D00500","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>fluid, writing ink.</i> <span class=\"citation\">Ab. IV, 20</span>. <span class=\"citation\">Sabb. 133ᵇ</span>. <span class=\"citation\">Y. Sot. II, 18ᵃ</span> top, v. <span dir=\"rtl\">אֶרֶר</span>; a. fr.—Pl. <span dir=\"rtl\">דְּיוֹאוֹת</span>, <a href=\"#\" data-headword=\"פְּרוּזְדָּאוֹת\">דָּיוֹת</a>. Midr. Sam. ch. XXVII, end <span dir=\"rtl\">(דיוא׳</span>); <span class=\"citation\">Gen. R. s. 58</span>; <span class=\"citation\">Yalk. ib. 102</span>; <span class=\"citation\">Yalk. Kings 170</span> <span dir=\"rtl\">כמה ד׳ וכ׳</span> how many ink drops have been spilt … to write ‘the sons of Heth’ ten times!</div>","alt":[]},"6790":{"h":"דִּיוֹ II","r":"D00501","html":"<div class=\"sense\"> (δι-) <i>two, double</i>, a Greek prefix, sometimes used as a separate word (δύο) for etymological purposes, and sometimes separated from its junction. <span class=\"citation\">Erub. 18ᵃ</span> (explain. <span dir=\"rtl\">דיומדין</span>, v. <a href=\"#\" data-headword=\"דְּיוֹמַד\">דְּיוֹמַד</a>) <span dir=\"rtl\">דיו עמודין</span> two columns; <span class=\"citation\">ib.</span> (expl. <a href=\"#\" data-headword=\"דְּיוֹפְרָא\">דיופרא</a>, v. <a href=\"#\" data-headword=\"דִּיפְרָא\">דִּיפְרָא</a>) <span dir=\"rtl\">העושה ד׳ פירות</span> bearing fruits twice a year.—<span dir=\"rtl\">ד׳ זוגי</span>, <span dir=\"rtl\">ד׳ פרצוף</span> &amp;c., v. <span dir=\"rtl\">דיוז׳</span>, <span dir=\"rtl\">דיופ׳</span></div>","alt":[]},"6791":{"h":"דיו־","r":"D00502","html":"<div class=\"sense\"> a Greek prefix.</div><div class=\"sense\"><b>—1)</b>  = δι-, v. <a href=\"#\" data-headword=\"דִּיוֹ II\">preced.</a></div><div class=\"sense\"><b>—2)</b>  = δια-.</div>","alt":[]},"6792":{"h":"*דֵּין","r":"D00503","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"דְּוַי\">דְּוַי</a>) </div><div class=\"sense\"><b>1)</b> <i>faintness, trouble, sickness</i>. <span class=\"citation\">Y. Ber. IX, 13ᵃ</span> bot. <span dir=\"rtl\">ד׳ ליה וכ׳</span> he was in trouble; (so) we let him pass.</div><div class=\"sense\"><b>—2)</b>  interj. expressive of love-longing (cmp. <a href=\"#\" data-headword=\"אוֹי\">אוֹי</a> &amp;c.) <i>Oh! Ah!</i> <span class=\"citation\">Cant. R. to II, 9</span> (play on <span dir=\"rtl\">דודי</span>) <span dir=\"rtl\">את אומר לנו ד׳ ד׳ וכ׳</span> thou (O Lord) sayest to us, Oh! Oh! [strike out the gloss <span dir=\"rtl\">פי׳ דיאו דיאו</span>]. <i>Thou</i> art sighing for <i>us</i> first (instead of our aspiring for thee)! <span class=\"citation\">Ib.</span> (twice more; correct slight inaccuracies). <span class=\"citation\">Pesik. R. s. 15</span> [read:] <span dir=\"rtl\">את אתת לגבן קדמאה</span>, <span dir=\"rtl\">דיאו את לגבן</span>, <span dir=\"rtl\">את אמרת לנו דיו</span>; <span class=\"citation\">Num. R. s. 11</span> [read:] <span dir=\"rtl\">את אמרת לנו דיו את אתת וכ׳</span>.</div>","alt":[]},"6793":{"h":"דֵּיוָא","r":"D00504","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*דֵּין\">preced.</a> a. <a href=\"#\" data-headword=\"דְּוַי\">דְּוַי</a>) <i>grief</i>. <span class=\"citation\">Targ. Prov. XXIII, 29</span> ed., Ms. <a href=\"#\" data-headword=\"*דִּיוָודָא\">דִּיוָודָא</a>.</div>","alt":[]},"6794":{"h":"דְּיוֹבִיט","r":"D00505","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (διαβήτης, diabetes) <i>siphon</i>. <span class=\"citation\">Y. Erub. X, 26ᵈ</span> top <span dir=\"rtl\">מעלין בד׳</span> you may draw liquids by means of a siphon on the Sabbath; <span class=\"citation\">Tosef. Sabb. II, 8</span>; <span class=\"citation\">Erub. 104ᵃ</span> <span dir=\"rtl\">בדְיוֹפִי</span> (popular perversion, as though = <a href=\"#\" data-headword=\"דְּיוֹפִי\">דְּיוֹ פִי</a> <i>double mouth</i>, v. <a href=\"#\" data-headword=\"דִּיוֹ II\"><span dir=\"rtl\">דְּיוֹ</span> II</a>).</div>","alt":[]},"6795":{"h":"*דִּיוָודָא","r":"D00506","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (reduplic. of <span dir=\"rtl\">דוו</span>, v. <a href=\"#\" data-headword=\"דוי\">דוי</a>) <i>grief</i>. <span class=\"citation\">Targ. Prov. XXIII, 29</span> Ms. <span dir=\"rtl\">די׳</span>, ed. Lag. <span dir=\"rtl\">דוו׳</span>; ed. <a href=\"#\" data-headword=\"דֵּיוָא\">דֵּיוָא</a> (Var. in ed. Lag. p. XII <a href=\"#\" data-headword=\"רֵיו\">ריוא</a>, corr. acc.). [Prob. a corrupt. fr. <a href=\"#\" data-headword=\"דִּיוּוּי\">דִּיוּוּיָא</a>, v. next w.]</div>","alt":["דִּוָודָא"]},"6796":{"h":"דִּיוּוּי","r":"D00507","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"דָּוָה\">דָוָה</a>) <i>grief</i>. Gen. R. <i>s</i>. 74 חזר לדִיוּוּיוֹ Ar. s. v. <a href=\"#\" data-headword=\"קַרְקַר\">קרקר</a> 2; <span class=\"citation\">Yalk. Gen. 130</span> (ed. Gen. R. <span dir=\"rtl\">לסורו</span>) he (Laban) went back to his grief.</div>","alt":[]},"6797":{"h":"דיוזגו","r":"D00508","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּיוֹזוּגֵי\">next w.</a></div>","alt":["דיוזגי"]},"6798":{"h":"דְּיוֹזוּגֵי","r":"D00509","html":"<div class=\"sense\"> (a popular perversion of διαδοχή, as though = <a href=\"#\" data-headword=\"דְּיוֹזוּגֵי\">דְּיוֹ זוּגֵי</a> <i>two sets</i>, v. <a href=\"#\" data-headword=\"דִּיוֹ II\"><span dir=\"rtl\">דְּיוֹ</span> II</a>) <i>succession in government, surrender of office</i>. <span class=\"citation\">Sot. 13ᵇ</span> <span dir=\"rtl\">אותה שבת של ד׳ היתה וכ׳</span> (Ar. <a href=\"#\" data-headword=\"דיוזגו\">דיוזגי</a>; <span class=\"citation\">Yalk. Deut. 941</span> <a href=\"#\" data-headword=\"דיוזגו\">דיוזגו</a>) it was the week of transmission of office when the office was taken from the one (Moses) and given to the other (Joshua, hence ‘Moses and Joshua went’ &amp;c., <span class=\"citation\">Deut. XXXI, 14</span>); v. <a href=\"#\" data-headword=\"דְּיָיּתִּיכוֹס\">דייתיכוס</a>.</div>","alt":[]},"6799":{"h":"דְּיוֹטָא","r":"D00510","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּיֵיטָא\">דְּיֵיטִי</a></div>","alt":[]}};
